insert into public.bible_verses (version, book_abbrev, chapter, verse, text) values
('acf','2cr',1,1,'Salomão, filho de Davi, fortaleceu-se no seu reino; e o SENHOR seu Deus era com ele, e o engrandeceu sobremaneira.'),
('acf','2cr',1,2,'E falou Salomão a todo o Israel, aos capitães de mil e de cem, aos juízes e a todos os governadores em todo o Israel, chefes das famílias.'),
('acf','2cr',1,3,'E foi Salomão, e toda a congregação com ele, ao alto que estava em Gibeom, porque ali estava a tenda da congregação de Deus, que Moisés, servo do Senhor, tinha feito no deserto.'),
('acf','2cr',1,4,'Mas Davi tinha feito subir a arca de Deus de Quiriate-Jearim ao lugar que lhe preparara; porque lhe tinha armado uma tenda em Jerusalém.'),
('acf','2cr',1,5,'Também o altar de cobre que tinha feito Bezaleel, filho de Uri, filho de Hur, estava ali diante do tabernáculo do Senhor; e Salomão e a congregação o buscavam.'),
('acf','2cr',1,6,'E Salomão ofereceu ali sacrifícios perante o Senhor, sobre o altar de cobre que estava na tenda da congregação; e ofereceu sobre ele mil holocaustos.'),
('acf','2cr',1,7,'Naquela mesma noite Deus apareceu a Salomão, e disse-lhe: Pede o que queres que eu te dê.'),
('acf','2cr',1,8,'E Salomão disse a Deus: Tu usaste de grande benignidade com meu pai Davi, e a mim me fizeste rei em seu lugar.'),
('acf','2cr',1,9,'Agora, pois, ó Senhor Deus, confirme-se a tua palavra, dada a meu pai Davi; porque tu me fizeste reinar sobre um povo numeroso como o pó da terra.'),
('acf','2cr',1,10,'Dá-me, pois, agora, sabedoria e conhecimento, para que possa sair e entrar perante este povo; pois quem poderia julgar a este tão grande povo?'),
('acf','2cr',1,11,'Então Deus disse a Salomão: Porquanto houve isto no teu coração, e não pediste riquezas, bens, ou honra, nem a morte dos que te odeiam, nem tampouco pediste muitos dias de vida, mas pediste para ti sabedoria e conhecimento, para poderes julgar a meu povo, sobre o qual te constituí rei,'),
('acf','2cr',1,12,'Sabedoria e conhecimento te são dados; e te darei riquezas, bens e honra, quais não teve nenhum rei antes de ti, e nem depois de ti haverá.'),
('acf','2cr',1,13,'Assim Salomão veio a Jerusalém, do alto que estava em Gibeom, de diante da tenda da congregação; e reinou sobre Israel.'),
('acf','2cr',1,14,'E Salomão ajuntou carros e cavaleiros, e teve mil e quatrocentos carros, e doze mil cavaleiros; os quais pôs nas cidades dos carros, e junto ao rei em Jerusalém.'),
('acf','2cr',1,15,'E fez o rei que houvesse ouro e prata em Jerusalém como pedras; e cedros em tanta abundância como figueiras bravas que há pelas campinas.'),
('acf','2cr',1,16,'E os cavalos, que tinha Salomão, eram trazidos do Egito; e os mercadores do rei os recebiam em tropas, cada uma pelo seu preço.'),
('acf','2cr',1,17,'E faziam subir e sair do Egito cada carro por seiscentos siclos de prata, e cada cavalo por cento e cinqüenta; e assim, por meio deles eram para todos os reis dos heteus, e para os reis da Síria.'),
('acf','2cr',2,1,'E determinou Salomão edificar uma casa ao nome do SENHOR, como também uma casa para o seu reino.'),
('acf','2cr',2,2,'E designou Salomão setenta mil homens de carga, e oitenta mil que talhavam pedras na montanha, e três mil e seiscentos inspetores sobre eles.'),
('acf','2cr',2,3,'E Salomão mandou dizer a Hirão, rei de Tiro: Como fizeste com Davi meu pai, mandando-lhe cedros, para edificar uma casa em que morasse, assim também faze comigo.'),
('acf','2cr',2,4,'Eis que estou para edificar uma casa ao nome do Senhor meu Deus, para lhe consagrar, para queimar perante ele incenso aromático, e para a apresentação contínua do pão da proposição, para os holocaustos da manhã e da tarde, nos sábados e nas luas novas, e nas festividades do Senhor nosso Deus; o que é obrigação perpétua de Israel.'),
('acf','2cr',2,5,'E a casa que estou para edificar há de ser grande; porque o nosso Deus é maior do que todos os deuses.'),
('acf','2cr',2,6,'Porém, quem seria capaz de lhe edificar uma casa, visto que os céus e até os céus dos céus o não podem conter? E quem sou eu, que lhe edificasse casa, salvo para queimar incenso perante ele?'),
('acf','2cr',2,7,'Manda-me, pois, agora um homem hábil para trabalhar em ouro, em prata, em bronze, em ferro, em púrpura, em carmesim e em azul; e que saiba lavrar ao buril, juntamente com os peritos que estão comigo em Judá e em Jerusalém, os quais Davi, meu pai, preparou.'),
('acf','2cr',2,8,'Manda-me também madeiras de cedro, de cipreste, e algumins do Líbano; porque bem sei eu que os teus servos sabem cortar madeira no Líbano; e eis que os meus servos estarão com os teus servos.'),
('acf','2cr',2,9,'E isso para prepararem muita madeira; porque a casa que estou para fazer há de ser grande e maravilhosa.'),
('acf','2cr',2,10,'E eis que a teus servos, os cortadores, que cortarem a madeira, darei vinte mil coros de trigo malhado, vinte mil coros de cevada, vinte mil batos de vinho e vinte mil batos de azeite.'),
('acf','2cr',2,11,'E Hirão, rei de Tiro, respondeu por escrito que enviou a Salomão, dizendo: Porque o Senhor tem amado o seu povo, te constituiu sobre ele rei.'),
('acf','2cr',2,12,'Disse mais Hirão: Bendito seja o Senhor Deus de Israel, que fez os céus e a terra; o que deu ao rei Davi um filho sábio, de grande prudência e entendimento, que edifique casa ao Senhor, e para o seu reino.'),
('acf','2cr',2,13,'Agora, pois, envio um homem sábio de grande entendimento, a saber, Hirão Abiú.'),
('acf','2cr',2,14,'Filho de uma mulher das filhas de Dã, e cujo pai foi homem de Tiro; este sabe trabalhar em ouro, em prata, em bronze, em ferro, em pedras e em madeira, em púrpura, em azul, e em linho fino, e em carmesim, e é hábil para toda a obra do buril, e para toda a espécie de invenções, qualquer coisa que se lhe propuser, juntamente com os teus peritos, e os peritos de Davi, meu senhor, teu pai.'),
('acf','2cr',2,15,'Agora, pois, meu senhor, mande para os seus servos o trigo, a cevada, o azeite e o vinho, de que falou;'),
('acf','2cr',2,16,'E nós cortaremos tanta madeira no Líbano, quanta houveres mister, e ta traremos em jangadas pelo mar até Jope, e tu a farás subir a Jerusalém.'),
('acf','2cr',2,17,'E Salomão contou todos os homens estrangeiros, que havia na terra de Israel, conforme o censo com que os contara Davi seu pai; e acharam-se cento e cinqüenta e três mil e seiscentos.'),
('acf','2cr',2,18,'E designou deles setenta mil carregadores, e oitenta mil cortadores na montanha; como também três mil e seiscentos inspetores, para fazerem trabalhar o povo.'),
('acf','2cr',3,1,'E começou Salomão a edificar a casa do SENHOR em Jerusalém, no monte Moriá, onde o SENHOR aparecera a Davi seu pai, no lugar que Davi tinha preparado na eira de Ornã, o jebuseu.'),
('acf','2cr',3,2,'E começou a edificar no segundo mês, no segundo dia, no ano quarto do seu reinado.'),
('acf','2cr',3,3,'E estes foram os fundamentos que Salomão pôs para edificar a casa de Deus: o comprimento em côvados, segundo a primeira medida, era de sessenta côvados, e a largura de vinte côvados.'),
('acf','2cr',3,4,'E o pátio, que estava na frente, tinha vinte côvados de comprimento, segundo a largura da casa, e a altura era de cento e vinte; e por dentro o revestiu com ouro puro.'),
('acf','2cr',3,5,'E a casa grande forrou com madeira de faia; e então a revestiu com ouro fino; e fez sobre ela palmas e cadeias.'),
('acf','2cr',3,6,'Também a casa adornou de pedras preciosas, para ornamento; e o ouro era ouro de Parvaim.'),
('acf','2cr',3,7,'Também na casa revestiu, com ouro, as traves, os umbrais, as suas paredes e as suas portas; e lavrou querubins nas paredes.'),
('acf','2cr',3,8,'Fez mais a casa do lugar santíssimo, cujo comprimento, segundo a largura da casa, era de vinte côvados, e também a largura de vinte côvados; e revestiu-a de ouro fino, do peso de seiscentos talentos.'),
('acf','2cr',3,9,'O peso dos pregos era de cinqüenta siclos de ouro; e as câmaras cobriu de ouro.'),
('acf','2cr',3,10,'Também fez na casa do lugar santíssimo dois querubins de obra móvel, e cobriu-os de ouro.'),
('acf','2cr',3,11,'E, quanto às asas dos querubins, o seu comprimento era de vinte côvados; a asa de um deles, de cinco côvados, e tocava na parede da casa; e a outra asa de cinco côvados, e tocava na asa do outro querubim.'),
('acf','2cr',3,12,'Também a asa do outro querubim era de cinco côvados, e tocava na parede da casa; era também a outra asa de cinco côvados, que tocava na asa do outro querubim.'),
('acf','2cr',3,13,'E as asas destes querubins se estendiam vinte côvados; e estavam postos em pé, e os seus rostos virados para a casa.'),
('acf','2cr',3,14,'Também fez o véu de azul, púrpura, carmesim e linho fino; e pôs sobre ele querubins;'),
('acf','2cr',3,15,'Fez também, diante da casa, duas colunas de trinta e cinco côvados de altura; e o capitel, que estava sobre cada uma, era de cinco côvados.'),
('acf','2cr',3,16,'Também fez cadeias no oráculo, e as pôs sobre as cabeças das colunas; fez também cem romãs, as quais pôs entre as cadeias.'),
('acf','2cr',3,17,'E levantou as colunas diante do templo, uma à direita, e outra à esquerda; e chamou o nome da que estava à direita Jaquim, e o nome da que estava à esquerda Boaz.'),
('acf','2cr',4,1,'Também fez um altar de metal, de vinte côvados de comprimento, de vinte côvados de largura e de dez côvados de altura.'),
('acf','2cr',4,2,'Fez também o mar de fundição, de dez côvados de uma borda até a outra, redondo, e de cinco côvados de altura; cingia-o ao redor um cordão de trinta côvados.'),
('acf','2cr',4,3,'E por baixo dele havia figuras de bois, que cingiam o mar ao redor, dez em cada côvado, contornando-o; e tinha duas fileiras de bois, fundidos juntamente com o mar.'),
('acf','2cr',4,4,'E o mar estava posto sobre doze bois; três que olhavam para o norte, três que olhavam para o ocidente, três que olhavam para o sul e três que olhavam para o oriente; e o mar estava posto sobre eles; e as suas partes posteriores estavam todas para o lado de dentro.'),
('acf','2cr',4,5,'E tinha um palmo de grossura, e a sua borda foi feita como a borda de um copo, ou como uma flor-de-lis, da capacidade de três mil batos.'),
('acf','2cr',4,6,'Também fez dez pias; e pôs cinco à direita e cinco à esquerda, para lavarem nelas; o que pertencia ao holocausto o lavavam nelas; porém o mar era para que os sacerdotes se lavassem nele.'),
('acf','2cr',4,7,'Fez também dez castiçais de ouro, segundo a sua forma, e pô-los no templo, cinco à direita, e cinco à esquerda.'),
('acf','2cr',4,8,'Também fez dez mesas, e pô-las no templo, cinco à direita e cinco à esquerda; também fez cem bacias de ouro.'),
('acf','2cr',4,9,'Fez mais o pátio dos sacerdotes, e o grande átrio; como também as portas para o pátio, as quais revestiu de cobre.'),
('acf','2cr',4,10,'E pôs o mar ao lado direito, para o lado do oriente, na direção do sul.'),
('acf','2cr',4,11,'Também Hirão fez as caldeiras, as pás e as bacias. Assim acabou Hirão de fazer a obra, que fazia para o rei Salomão, na casa de Deus.'),
('acf','2cr',4,12,'As duas colunas, os globos, e os dois capitéis sobre as cabeças das colunas; e as duas redes, para cobrir os dois globos dos capitéis, que estavam sobre a cabeça das colunas.'),
('acf','2cr',4,13,'E as quatrocentas romãs para as duas redes; duas carreiras de romãs para cada rede, para cobrirem os dois globos dos capitéis que estavam em cima das colunas.'),
('acf','2cr',4,14,'Também fez as bases; e as pias pôs sobre as bases;'),
('acf','2cr',4,15,'Um mar, e os doze bois debaixo dele;'),
('acf','2cr',4,16,'Semelhantemente as caldeiras, as pás, os garfos e todos os seus utensílios, fez Hirão Abiú ao rei Salomão, para a casa do Senhor, de cobre polido.'),
('acf','2cr',4,17,'Na campina do Jordão os fundiu o rei, na terra argilosa, entre Sucote e Zeredá.'),
('acf','2cr',4,18,'E fez Salomão todos estes objetos em grande abundância, que não se podia averiguar o peso do cobre.'),
('acf','2cr',4,19,'Fez também Salomão todos os objetos que eram para a casa de Deus, como também o altar de ouro, e as mesas, sobre as quais estavam os pães da proposição.'),
('acf','2cr',4,20,'E os castiçais com as suas lâmpadas de ouro finíssimo, para as acenderem segundo o costume, perante o oráculo.'),
('acf','2cr',4,21,'E as flores, as lâmpadas e os espevitadores eram de ouro, do mais finíssimo ouro.'),
('acf','2cr',4,22,'Como também os apagadores, as bacias, as colheres e os incensários de ouro finíssimo; e quanto à entrada da casa, as suas portas de dentro do lugar santíssimo, e as portas da casa do templo, eram de ouro.'),
('acf','2cr',5,1,'Assim se acabou toda a obra que Salomão fez para a casa do SENHOR; então trouxe Salomão as coisas que seu pai Davi havia consagrado, a prata, o ouro e todos os objetos, e pô-los entre os tesouros da casa de Deus.'),
('acf','2cr',5,2,'Então Salomão congregou em Jerusalém os anciãos de Israel, e todos os chefes das tribos, os chefes dos pais entre os filhos de Israel, para fazerem subir a arca da aliança do Senhor, da cidade de Davi, que é Sião.'),
('acf','2cr',5,3,'E todos os homens de Israel se congregaram ao rei na ocasião da festa, que foi no sétimo mês.'),
('acf','2cr',5,4,'E vieram todos os anciãos de Israel; e os levitas levantaram a arca.'),
('acf','2cr',5,5,'E fizeram subir a arca, e a tenda da congregação, com todos os objetos sagrados, que estavam na tenda; os sacerdotes e os levitas os fizeram subir.'),
('acf','2cr',5,6,'Então o rei Salomão e toda a congregação de Israel, que se tinha reunido com ele diante da arca, sacrificaram carneiros e bois, que não se podiam contar, nem numerar, por causa da sua abundância.'),
('acf','2cr',5,7,'Assim trouxeram os sacerdotes a arca da aliança do Senhor ao seu lugar, ao oráculo da casa, ao lugar santíssimo, até debaixo das asas dos querubins.'),
('acf','2cr',5,8,'Porque os querubins estendiam ambas as asas sobre o lugar da arca, e os querubins cobriam, por cima, a arca e os seus varais.'),
('acf','2cr',5,9,'Então os varais sobressaíam para que as pontas dos varais da arca se vissem perante o oráculo, mas não se vissem de fora; e ali tem estado até ao dia de hoje.'),
('acf','2cr',5,10,'Na arca não havia coisa alguma senão as duas tábuas, que Moisés tinha posto em Horebe, quando o Senhor fez aliança com os filhos de Israel, saíndo eles do Egito.'),
('acf','2cr',5,11,'E sucedeu que, saindo os sacerdotes do santuário (porque todos os sacerdotes, que ali se acharam, se santificaram, sem respeitarem as suas turmas,'),
('acf','2cr',5,12,'E os levitas, que eram cantores, todos eles, de Asafe, de Hemã, de Jedutum, de seus filhos e de seus irmãos, vestidos de linho fino, com címbalos, com saltérios e com harpas, estavam em pé para o oriente do altar; e com eles até cento e vinte sacerdotes, que tocavam as trombetas).'),
('acf','2cr',5,13,'E aconteceu que, quando eles uniformemente tocavam as trombetas, e cantavam, para fazerem ouvir uma só voz, bendizendo e louvando ao Senhor; e levantando eles a voz com trombetas, címbalos, e outros instrumentos musicais, e louvando ao Senhor, dizendo: Porque ele é bom, porque a sua benignidade dura para sempre, então a casa se encheu de uma nuvem, a saber, a casa do Senhor;'),
('acf','2cr',5,14,'E os sacerdotes não podiam permanecer em pé, para ministrar, por causa da nuvem; porque a glória do Senhor encheu a casa de Deus.'),
('acf','2cr',6,1,'Então falou Salomão: O SENHOR disse que habitaria nas trevas.'),
('acf','2cr',6,2,'E eu te tenho edificado uma casa para morada, e um lugar para a tua eterna habitação.'),
('acf','2cr',6,3,'Então o rei virou o seu rosto, e abençoou a toda a congregação de Israel, e toda a congregação de Israel estava em pé.'),
('acf','2cr',6,4,'E ele disse: Bendito seja o Senhor Deus de Israel, que falou pela sua boca a Davi meu pai; e pelas suas mãos o cumpriu, dizendo:'),
('acf','2cr',6,5,'Desde o dia em que tirei a meu povo da terra do Egito, não escolhi cidade alguma de todas as tribos de Israel, para edificar nela uma casa em que estivesse o meu nome; nem escolhi homem algum para ser líder do meu povo, Israel.'),
('acf','2cr',6,6,'Porém escolhi a Jerusalém para que ali estivesse o meu nome; e escolhi a Davi, para que estivesse sobre o meu povo Israel.'),
('acf','2cr',6,7,'Também Davi meu pai teve no seu coração o edificar uma casa ao nome do Senhor Deus de Israel.'),
('acf','2cr',6,8,'Porém o Senhor disse a Davi, meu pai: Porquanto tiveste no teu coração o edificar uma casa ao meu nome, bem fizeste de ter isto no teu coração.'),
('acf','2cr',6,9,'Contudo tu não edificarás a casa, mas teu filho, que há de proceder de teus lombos, esse edificará a casa ao meu nome.'),
('acf','2cr',6,10,'Assim confirmou o Senhor a sua palavra, que falou; porque eu me levantei em lugar de Davi meu pai, e me assentei sobre o trono de Israel, como o Senhor disse, e edifiquei a casa ao nome do Senhor Deus de Israel.'),
('acf','2cr',6,11,'E pus nela a arca, em que está a aliança que o Senhor fez com os filhos de Israel.'),
('acf','2cr',6,12,'E pôs-se em pé, perante o altar do Senhor, na presença de toda a congregação de Israel, e estendeu as suas mãos.'),
('acf','2cr',6,13,'Porque Salomão tinha feito uma plataforma de metal, de cinco côvados de comprimento, de cinco côvados de largura e de três côvados de altura, e a tinha posto no meio do pátio, e pôs-se em pé sobre ela, e ajoelhou-se em presença de toda a congregação de Israel, e estendeu as suas mãos para o céu.'),
('acf','2cr',6,14,'E disse: Ó Senhor Deus de Israel, não há Deus semelhante a ti, nem nos céus nem na terra; que guardas a aliança e a beneficência aos teus servos que caminham perante ti de todo o seu coração.'),
('acf','2cr',6,15,'Que guardaste ao teu servo Davi, meu pai, o que lhe falaste; porque tu pela tua boca o disseste, e pela tua mão o cumpriste, como se vê neste dia.'),
('acf','2cr',6,16,'Agora, pois, Senhor Deus de Israel, guarda ao teu servo Davi, meu pai, o que falaste, dizendo: Nunca homem algum será cortado de diante de mim, que se assente sobre o trono de Israel; tão-somente que teus filhos guardem seu caminho, andando na minha lei, como tu andaste diante de mim.'),
('acf','2cr',6,17,'E agora, Senhor Deus de Israel, cumpra-se a tua palavra, que disseste ao teu servo Davi.'),
('acf','2cr',6,18,'Mas, na verdade, habitará Deus com os homens na terra? Eis que os céus, e o céu dos céus, não te podem conter, quanto menos esta casa que tenho edificado?'),
('acf','2cr',6,19,'Atende, pois, à oração do teu servo, e à sua súplica, ó Senhor meu Deus; para ouvires o clamor, e a oração, que o teu servo faz perante ti.'),
('acf','2cr',6,20,'Que os teus olhos estejam dia e noite abertos sobre este lugar, de que disseste que ali porias o teu nome; para ouvires a oração que o teu servo orar neste lugar.'),
('acf','2cr',6,21,'Ouve, pois, as súplicas do teu servo, e do teu povo Israel, que fizerem neste lugar; e ouve tu do lugar da tua habitação, desde os céus; ouve pois, e perdoa.'),
('acf','2cr',6,22,'Quando alguém pecar contra o seu próximo, e lhe impuser juramento de maldição, fazendo-o jurar, e o juramento de maldição vier perante o teu altar, nesta casa,'),
('acf','2cr',6,23,'Ouve tu, então, desde os céus, e age e julga a teus servos, condenando ao ímpio, retribuindo o seu proceder sobre a sua cabeça; e justificando ao justo, dando-lhe segundo a sua justiça.'),
('acf','2cr',6,24,'Quando também o teu povo Israel for ferido diante do inimigo, por ter pecado contra ti, e eles se converterem, e confessarem o teu nome, e orarem e suplicarem perante ti nesta casa,'),
('acf','2cr',6,25,'Então, ouve tu desde os céus, e perdoa os pecados do teu povo Israel; e torna a levá-los à terra que lhes tens dado e a seus pais.'),
('acf','2cr',6,26,'Quando os céus se fecharem, e não houver chuva, por terem pecado contra ti, e orarem neste lugar, e confessarem teu nome, e se converterem dos seus pecados, quando tu os afligires,'),
('acf','2cr',6,27,'Então, ouve tu desde os céus, e perdoa o pecado de teus servos, e do teu povo Israel, ensinando-lhes o bom caminho, em que andem; e dá chuva sobre a tua terra, que deste ao teu povo em herança.'),
('acf','2cr',6,28,'Quando houver fome na terra, quando houver peste, quando houver queima de seara, ou ferrugem, gafanhotos, ou lagarta, cercando-a algum dos seus inimigos nas terras das suas portas, ou quando houver qualquer praga, ou qualquer enfermidade,'),
('acf','2cr',6,29,'Toda a oração, e toda a súplica, que qualquer homem fizer, ou todo o teu povo Israel, conhecendo cada um a sua praga, e a sua dor, e estendendo as suas mãos para esta casa,'),
('acf','2cr',6,30,'Então, ouve tu desde os céus, do assento da tua habitação, e perdoa, e dá a cada um conforme a todos os seus caminhos, segundo conheces o seu coração (pois só tu conheces o coração dos filhos dos homens),'),
('acf','2cr',6,31,'A fim de que te temam, para andarem nos teus caminhos, todos os dias que viverem na terra que deste a nossos pais.'),
('acf','2cr',6,32,'Assim também ao estrangeiro, que não for do teu povo Israel, quando vier de terras remotas por amor do teu grande nome, e da tua poderosa mão, e do teu braço estendido, vindo eles e orando nesta casa;'),
('acf','2cr',6,33,'Então, ouve tu desde os céus, do assento da tua habitação, e faze conforme a tudo o que o estrangeiro te suplicar; a fim de que todos os povos da terra conheçam o teu nome, e te temam, como o teu povo Israel; e a fim de saberem que pelo teu nome é chamada esta casa que edifiquei.'),
('acf','2cr',6,34,'Quando o teu povo sair à guerra contra os seus inimigos, pelo caminho que os enviares, e orarem a ti para o lado desta cidade que escolheste, e desta casa, que edifiquei ao teu nome,'),
('acf','2cr',6,35,'Ouve, então, desde os céus a sua oração, e a sua súplica, e faze-lhes justiça.'),
('acf','2cr',6,36,'Quando pecarem contra ti (pois não há homem que não peque), e tu te indignares contra eles, e os entregares diante do inimigo, para que os que os cativarem os levem em cativeiro para alguma terra, remota ou vizinha,'),
('acf','2cr',6,37,'E na terra, para onde forem levados em cativeiro, caírem em si, e se converterem, e na terra do seu cativeiro, a ti suplicarem, dizendo: Pecamos, perversamente procedemos e impiamente agimos;'),
('acf','2cr',6,38,'E se converterem a ti com todo o seu coração e com toda a sua alma, na terra do seu cativeiro, a que os levaram presos, e orarem para o lado da sua terra, que deste a seus pais, e para esta cidade que escolheste, e para esta casa que edifiquei ao teu nome,'),
('acf','2cr',6,39,'Ouve, então, desde os céus, do assento da tua habitação, a sua oração e as suas súplicas, e executa o seu direito; e perdoa ao teu povo que houver pecado contra ti.'),
('acf','2cr',6,40,'Agora, pois, ó meu Deus, estejam os teus olhos abertos, e os teus ouvidos atentos à oração deste lugar.'),
('acf','2cr',6,41,'Levanta-te, pois, agora, Senhor Deus, para o teu repouso, tu e a arca da tua fortaleza; os teus sacerdotes, ó Senhor Deus, sejam vestidos de salvação, e os teus santos se alegrem do bem.'),
('acf','2cr',6,42,'Ó Senhor Deus, não faças virar o rosto do teu ungido; lembra-te das misericórdias de Davi teu servo.'),
('acf','2cr',7,1,'E acabando Salomão de orar, desceu o fogo do céu, e consumiu o holocausto e os sacrifícios; e a glória do SENHOR encheu a casa.'),
('acf','2cr',7,2,'E os sacerdotes não podiam entrar na casa do Senhor, porque a glória do Senhor tinha enchido a casa do Senhor.'),
('acf','2cr',7,3,'E todos os filhos de Israel vendo descer o fogo, e a glória do Senhor sobre a casa, encurvaram-se com o rosto em terra sobre o pavimento, e adoraram e louvaram ao Senhor, dizendo: Porque ele é bom, porque a sua benignidade dura para sempre.'),
('acf','2cr',7,4,'E o rei e todo o povo ofereciam sacrifícios perante o Senhor.'),
('acf','2cr',7,5,'E o rei Salomão ofereceu sacrifícios de bois, vinte e dois mil, e de ovelhas, cento e vinte mil; e o rei e todo o povo consagraram a casa de Deus.'),
('acf','2cr',7,6,'E os sacerdotes, serviam em seus ofícios; como também os levitas com os instrumentos musicais do Senhor, que o rei Davi tinha feito, para louvarem ao Senhor, porque a sua benignidade dura para sempre, quando Davi o louvava pelo ministério deles; e os sacerdotes tocavam as trombetas diante deles, e todo o Israel estava em pé.'),
('acf','2cr',7,7,'E Salomão santificou o meio do átrio, que estava diante da casa do Senhor; porquanto ali tinha ele oferecido os holocaustos e a gordura dos sacrifícios pacíficos; porque no altar de metal, que Salomão tinha feito, não podia caber o holocausto, e a oferta de alimentos, e a gordura.'),
('acf','2cr',7,8,'E, assim, naquele mesmo tempo celebrou Salomão a festa por sete dias e todo o Israel com ele, uma grande congregação, desde a entrada de Hamate, até ao rio do Egito.'),
('acf','2cr',7,9,'E no dia oitavo realizaram uma assembléia solene; porque sete dias celebraram a consagração do altar, e sete dias a festa.'),
('acf','2cr',7,10,'E no dia vigésimo terceiro do sétimo mês, despediu o povo para as suas tendas, alegres e de bom ânimo, pelo bem que o Senhor tinha feito a Davi, e a Salomão, e a seu povo Israel.'),
('acf','2cr',7,11,'Assim Salomão acabou a casa do Senhor, e a casa do rei, e tudo quanto Salomão intentou fazer na casa do Senhor e na sua casa prosperamente o efetuou.'),
('acf','2cr',7,12,'E o Senhor apareceu de noite a Salomão, e disse-lhe: Ouvi a tua oração, e escolhi para mim este lugar para casa de sacrifício.'),
('acf','2cr',7,13,'Se eu fechar os céus, e não houver chuva; ou se ordenar aos gafanhotos que consumam a terra; ou se enviar a peste entre o meu povo;'),
('acf','2cr',7,14,'E se o meu povo, que se chama pelo meu nome, se humilhar, e orar, e buscar a minha face e se converter dos seus maus caminhos, então eu ouvirei dos céus, e perdoarei os seus pecados, e sararei a sua terra.'),
('acf','2cr',7,15,'Agora estarão abertos os meus olhos e atentos os meus ouvidos à oração deste lugar.'),
('acf','2cr',7,16,'Porque agora escolhi e santifiquei esta casa, para que o meu nome esteja nela perpetuamente; e nela estarão fixos os meus olhos e o meu coração todos os dias.'),
('acf','2cr',7,17,'E, quanto a ti, se andares diante de mim, como andou Davi teu pai, e fizeres conforme a tudo o que te ordenei, e guardares os meus estatutos e os meus juízos,'),
('acf','2cr',7,18,'Também confirmarei o trono do teu reino, conforme a aliança que fiz com Davi, teu pai, dizendo: Não te faltará sucessor que domine em Israel.'),
('acf','2cr',7,19,'Porém se vós vos desviardes, e deixardes os meus estatutos, e os meus mandamentos, que vos tenho proposto, e fordes, e servirdes a outros deuses, e vos prostrardes a eles,'),
('acf','2cr',7,20,'Então os arrancarei da minha terra que lhes dei, e lançarei da minha presença esta casa que consagrei ao meu nome, e farei com que seja por provérbio e motejo entre todos os povos.'),
('acf','2cr',7,21,'E desta casa, que é tão exaltada, qualquer que passar por ela se espantará e dirá: Por que fez o Senhor assim com esta terra e com esta casa?'),
('acf','2cr',7,22,'E dirão: Porque deixaram ao Senhor Deus de seus pais, que os tirou da terra do Egito, e se deram a outros deuses, e se prostraram a eles, e os serviram; por isso ele trouxe sobre eles todo este mal.'),
('acf','2cr',8,1,'E sucedeu, ao fim de vinte anos, nos quais Salomão edificou a casa do SENHOR, e a sua própria casa,'),
('acf','2cr',8,2,'Que Salomão edificou as cidades que Hirão lhe tinha dado; e fez habitar nelas os filhos de Israel.'),
('acf','2cr',8,3,'Depois foi Salomão a Hamate-Zobá, e a tomou.'),
('acf','2cr',8,4,'Também edificou a Tadmor no deserto, e todas as cidades de provisões, que edificou em Hamate.'),
('acf','2cr',8,5,'Edificou também a alta Bete-Horom, e a baixa Bete-Horom; cidades fortes, com muros, portas e ferrolhos;'),
('acf','2cr',8,6,'Como também a Baalate, e todas as cidades de provisões, que Salomão tinha, e todas as cidades dos carros e as cidades dos cavaleiros; e tudo quanto, conforme ao seu desejo, Salomão quis edificar em Jerusalém, e no Líbano, e em toda a terra do seu domínio.'),
('acf','2cr',8,7,'Quanto a todo o povo, que tinha ficado dos heteus, amorreus, perizeus, heveus e jebuseus, que não eram de Israel,'),
('acf','2cr',8,8,'Dos seus filhos, que ficaram depois deles na terra, os quais os filhos de Israel não destruíram, Salomão os fez tributários, até ao dia de hoje.'),
('acf','2cr',8,9,'Porém, dos filhos de Israel, Salomão não fez servos para sua obra (mas eram homens de guerra, chefes dos seus capitàes, e capitàes dos seus carros e cavaleiros),'),
('acf','2cr',8,10,'Destes, pois, eram os chefes dos oficiais que o rei Salomão tinha, duzentos e cinqüenta, que presidiam sobre o povo.'),
('acf','2cr',8,11,'E Salomão fez subir a filha de Faraó da cidade de Davi para a casa que lhe tinha edificado; porque disse: Minha mulher não morará na casa de Davi, rei de Israel, porquanto santos são os lugares nos quais entrou a arca do Senhor.'),
('acf','2cr',8,12,'Então Salomão ofereceu holocaustos ao Senhor, sobre o altar do Senhor, que tinha edificado diante do pórtico,'),
('acf','2cr',8,13,'E isto segundo a ordem de cada dia, fazendo ofertas conforme o mandamento de Moisés, nos sábados e nas luas novas, e nas solenidades, três vezes no ano; na festa dos pães ázimos, na festa das semanas, e na festa das tendas.'),
('acf','2cr',8,14,'Também, conforme à ordem de Davi seu pai, designou as turmas dos sacerdotes para seus ministérios, como também as dos levitas acerca dos seus cargos, para louvarem e ministrarem diante dos sacerdotes, segundo o que estava ordenado para cada dia, e os porteiros pelas suas turmas a cada porta; porque assim tinha mandado Davi, o homem de Deus.'),
('acf','2cr',8,15,'E não se desviaram do mandado do rei aos sacerdotes e levitas, em negócio nenhum, nem acerca dos tesouros.'),
('acf','2cr',8,16,'Assim se preparou toda a obra de Salomão, desde o dia da fundação da casa do Senhor, até se acabar; e assim se concluiu a casa do Senhor.'),
('acf','2cr',8,17,'Então foi Salomão a Eziom-Geber, e a Elote, à praia do mar, na terra de Edom.'),
('acf','2cr',8,18,'E enviou-lhe Hirão, por meio de seus servos, navios, e servos práticos do mar, e foram com os servos de Salomão a Ofir, e tomaram de lá quatrocentos e cinqüenta talentos de ouro; e os trouxeram ao rei Salomão.'),
('acf','2cr',9,1,'E ouvindo a rainha de Sabá a fama de Salomão, veio a Jerusalém, para prová-lo com questões difíceis, com um grande séquito, e com camelos carregados de especiarias; ouro em abundância e pedras preciosas; e foi a Salomão, e falou com ele de tudo o que tinha no seu coração.'),
('acf','2cr',9,2,'E Salomão lhe respondeu a todas as suas questões; e não houve nada que não lhe pudesse esclarecer.'),
('acf','2cr',9,3,'Vendo, pois, a rainha de Sabá a sabedoria de Salomão, e a casa que edificara;'),
('acf','2cr',9,4,'E as iguarias da sua mesa, o assentar dos seus servos, o estar dos seus criados, e as vestes deles; e os seus copeiros e as vestes deles; e a sua subida pela qual ele chegava à casa do Senhor, ela ficou como fora de si.'),
('acf','2cr',9,5,'Então disse ao rei: Era verdade a palavra que ouvi na minha terra acerca dos teus feitos e da tua sabedoria.'),
('acf','2cr',9,6,'Porém não cria naquelas palavras, até que vim, e meus olhos o viram, e eis que não me disseram a metade da grandeza da tua sabedoria; sobrepujaste a fama que ouvi.'),
('acf','2cr',9,7,'Bem-aventurados os teus homens, e bem-aventurados estes teus servos, que estão sempre diante de ti, e ouvem a tua sabedoria!'),
('acf','2cr',9,8,'Bendito seja o Senhor teu Deus, que se agradou de ti para te colocar no seu trono como rei para o Senhor teu Deus; porque teu Deus ama a Israel, para estabelecê-lo perpetuamente; por isso te constituiu rei sobre eles para fazeres juízo e justiça.'),
('acf','2cr',9,9,'E deu ao rei cento e vinte talentos de ouro, e especiarias em grande abundância, e pedras preciosas; e nunca houve tais especiarias, quais a rainha de Sabá deu ao rei Salomão.'),
('acf','2cr',9,10,'E também os servos de Hirão e os servos de Salomão, que de Ofir tinham trazido ouro, trouxeram madeira de algumins, e pedras preciosas.'),
('acf','2cr',9,11,'E, da madeira de algumins, o rei fez balaústres, para a casa do Senhor, e para a casa do rei, como também harpas e saltérios para os cantores, quais nunca dantes se viram na terra de Judá.'),
('acf','2cr',9,12,'E o rei Salomão deu à rainha de Sabá tudo quanto ela desejou, e tudo quanto lhe pediu, mais do que ela mesma trouxera ao rei. Assim voltou e foi para a sua terra, ela e os seus servos.'),
('acf','2cr',9,13,'E o peso do ouro, que vinha em um ano a Salomão, era de seiscentos e sessenta e seis talentos de ouro,'),
('acf','2cr',9,14,'Afora o que os negociantes e mercadores traziam; também todos os reis da Arábia, e os governadores da mesma terra traziam a Salomão ouro e prata.'),
('acf','2cr',9,15,'Também fez o rei Salomão duzentos paveses de ouro batido; para cada pavês destinou seiscentos siclos de ouro batido.'),
('acf','2cr',9,16,'Como também trezentos escudos de ouro batido; para cada escudo destinou trezentos siclos de ouro; e Salomão os pôs na casa do bosque do Líbano.'),
('acf','2cr',9,17,'Fez mais o rei um grande trono de marfim, e o revestiu de ouro puro.'),
('acf','2cr',9,18,'E o trono tinha seis degraus, e um estrado de ouro, que eram ligados ao trono, e encostos de ambos os lados no lugar do assento; e dois leões estavam junto aos encostos.'),
('acf','2cr',9,19,'E doze leões estavam ali de ambos os lados, sobre os seis degraus; outro tal não se fez em nenhum reino.'),
('acf','2cr',9,20,'Também todas as taças do rei Salomão eram de ouro, e todos os vasos da casa do bosque do Líbano, de ouro puro; a prata reputava-se por nada nos dias de Salomão.'),
('acf','2cr',9,21,'Porque, indo os navios do rei com os servos de Hirão, a Társis, voltavam os navios de Társis, uma vez em três anos, e traziam ouro e prata, marfim, bugios e pavões.'),
('acf','2cr',9,22,'Assim excedeu o rei Salomão a todos os reis da terra, em riquezas e sabedoria.'),
('acf','2cr',9,23,'E todos os reis da terra buscavam a presença de Salomão, para ouvirem a sabedoria que Deus tinha posto no seu coração.'),
('acf','2cr',9,24,'E cada um trazia o seu presente, vasos de prata, e vasos de ouro, e roupas, armaduras, especiarias, cavalos e mulas; assim faziam de ano em ano.'),
('acf','2cr',9,25,'Teve também Salomão quatro mil estrebarias para os cavalos de seus carros, e doze mil cavaleiros; e colocou-os nas cidades dos carros, e junto ao rei em Jerusalém.'),
('acf','2cr',9,26,'E dominava sobre todos os reis, desde o rio até à terra dos filisteus, e até ao termo do Egito.'),
('acf','2cr',9,27,'Também o rei fez que houvesse prata em Jerusalém como pedras, e cedros em tanta abundância como as figueiras bravas que há pelas campinas.'),
('acf','2cr',9,28,'E do Egito e de todas aquelas terras traziam cavalos a Salomão.'),
('acf','2cr',9,29,'Os demais atos de Salomão, tanto os primeiros como os últimos, porventura não estão escritos no livro das crônicas de Natã, o profeta, e na profecia de Aías, o silonita, e nas visões de Ido, o vidente, acerca de Jeroboão, filho de Nebate?'),
('acf','2cr',9,30,'E reinou Salomão em Jerusalém quarenta anos sobre todo o Israel.'),
('acf','2cr',9,31,'E dormiu Salomão com seus pais, e o sepultaram na cidade de Davi seu pai; e Roboão, seu filho, reinou em seu lugar.'),
('acf','2cr',10,1,'E foi Roboão a Siquém, porque todo o Israel se reunira ali, para fazê-lo rei.'),
('acf','2cr',10,2,'Sucedeu que, ouvindo-o Jero-boão, filho de Nebate (o qual estava então no Egito para onde fugira da presença do rei Salomão), voltou do Egito,'),
('acf','2cr',10,3,'Porque enviaram a ele, e o chamaram; e vieram, Jeroboão e todo o Israel, e falaram a Roboão dizendo:'),
('acf','2cr',10,4,'Teu pai fez duro o nosso jugo; agora, pois, alivia tu a dura servidão de teu pai, e o pesado jugo que nos impôs, e nós te serviremos.'),
('acf','2cr',10,5,'E ele lhes disse: Daqui a três dias voltai a mim. Então o povo se foi.'),
('acf','2cr',10,6,'E tomou Roboão conselho com os anciãos, que estiveram perante Salomão seu pai, enquanto viveu, dizendo: Como aconselhais vós que se responda a este povo?'),
('acf','2cr',10,7,'E eles lhe falaram, dizendo: Se te fizeres benigno e afável para com este povo, e lhes falares boas palavras, todos os dias serão teus servos.'),
('acf','2cr',10,8,'Porém ele deixou o conselho que os anciãos lhe deram; e tomou conselho com os jovens, que haviam crescido com ele, e estavam perante ele.'),
('acf','2cr',10,9,'E disse-lhes: Que aconselhais vós, que respondamos a este povo, que me falou, dizendo: Alivia o jugo que teu pai nos impôs?'),
('acf','2cr',10,10,'E os jovens, que com ele haviam crescido, lhe falaram, dizendo: Assim dirás a este povo, que te falou: Teu pai agravou o nosso jugo, tu porém alivia-nos; assim, pois, lhe falarás: O meu dedo mínimo é mais grosso do que os lombos de meu pai.'),
('acf','2cr',10,11,'Assim que, se meu pai vos carregou de um jugo pesado, eu ainda aumentarei o vosso jugo; meu pai vos castigou com açoites, porém eu vos castigarei com escorpiões.'),
('acf','2cr',10,12,'Veio, pois, Jeroboão, e todo o povo, ao terceiro dia, a Roboão, como o rei havia ordenado, dizendo: Voltai a mim ao terceiro dia.'),
('acf','2cr',10,13,'E o rei lhes respondeu asperamente; porque o rei Roboão deixara o conselho dos anciãos.'),
('acf','2cr',10,14,'E falou-lhes conforme o conselho dos jovens, dizendo: Meu pai agravou o vosso jugo, porém eu o aumentarei mais; meu pai vos castigou com açoites, porém eu vos castigarei com escorpiões.'),
('acf','2cr',10,15,'Assim o rei não deu ouvidos ao povo, porque esta mudança vinha de Deus, para que o Senhor confirmasse a sua palavra, a qual falara pelo ministério de Aías, o silonita, a Jeroboão, filho de Nebate.'),
('acf','2cr',10,16,'Vendo, pois, todo o Israel, que o rei não lhe dava ouvidos, tornou-lhe o povo a responder, dizendo: Que parte temos nós com Davi? Já não temos herança no filho de Jessé. Cada um à sua tenda, ó Israel! Olha agora pela tua casa, ó Davi. Assim todo o Israel se foi para as suas tendas.'),
('acf','2cr',10,17,'Porém, quanto aos filhos de Israel, que habitavam nas cidades de Judá, sobre eles reinou Roboão.'),
('acf','2cr',10,18,'Então o rei Roboão enviou a Hadorão, que tinha cargo dos tributos; porém os filhos de Israel o apedrejaram, e ele morreu. Então o rei Roboão se esforçou para subir ao seu carro, e fugiu para Jerusalém.'),
('acf','2cr',10,19,'Assim se rebelaram os israelitas contra a casa de Davi, até ao dia de hoje.'),
('acf','2cr',11,1,'Vindo, pois, Roboão a Jerusalém, reuniu, da casa de Judá e Benjamim, cento e oitenta mil escolhidos, destros na guerra, para pelejarem contra Israel, e para restituírem o reino a Roboão.'),
('acf','2cr',11,2,'Porém a palavra do Senhor veio a Semaías, homem de Deus, dizendo:'),
('acf','2cr',11,3,'Fala a Roboão, filho de Salomão, rei de Judá, e a todo o Israel, em Judá e Benjamim, dizendo:'),
('acf','2cr',11,4,'Assim diz o Senhor: Não subireis, nem pelejareis contra os vossos irmãos; volte cada um à sua casa; porque de mim proveio isto. E ouviram as palavras do Senhor, e desistiram de ir contra Jeroboão.'),
('acf','2cr',11,5,'E Roboão habitou em Jerusalém; e para defesa, edificou cidades em Judá.'),
('acf','2cr',11,6,'Edificou, pois, a Belém, a Etã, e a Tecoa,'),
('acf','2cr',11,7,'E a Bete-Zur, a Socó, a Adulão,'),
('acf','2cr',11,8,'E a Gate, a Maressa, a Zife,'),
('acf','2cr',11,9,'E a Adoraim, a Laquis, e a Azeca,'),
('acf','2cr',11,10,'E a Zorá, a Aijalom, e a Hebrom, que estavam em Judá e em Benjamim; cidades fortes.'),
('acf','2cr',11,11,'E fortificou estas fortalezas e pôs nelas capitàes, e armazéns de víveres, de azeite, e de vinho.'),
('acf','2cr',11,12,'E pôs em cada cidade paveses e lanças; fortificou-as grandemente; e Judá e Benjamim pertenceram-lhe.'),
('acf','2cr',11,13,'Também os sacerdotes e os levitas, que havia em todo o Israel, se reuniram a ele de todos os seus termos.'),
('acf','2cr',11,14,'Porque os levitas deixaram os seus arrabaldes, e a sua possessão, e vieram a Judá e a Jerusalém, porque Jeroboão e seus filhos os lançaram fora para que não ministrassem ao Senhor.'),
('acf','2cr',11,15,'E ele constituiu para si sacerdotes, para os altos, para os demônios, e para os bezerros, que fizera.'),
('acf','2cr',11,16,'Depois desses também, de todas as tribos de Israel, os que deram o seu coração a buscarem ao Senhor Deus de Israel, vieram a Jerusalém, para oferecerem sacrifícios ao Senhor Deus de seus pais.'),
('acf','2cr',11,17,'Assim fortaleceram o reino de Judá e corroboraram a Roboão, filho de Salomão, por três anos; porque três anos andaram no caminho de Davi e Salomão.'),
('acf','2cr',11,18,'E Roboão tomou para si, por mulher, a Maalate, filha de Jerimote, filho de Davi; e Abiail, filha de Eliabe, filho de Jessé.'),
('acf','2cr',11,19,'A qual lhe deu filhos: Jeús, Samarias e Zaã.'),
('acf','2cr',11,20,'E depois dela tomou a Maaca, filha de Absalão; esta lhe deu Abias, Atai, Ziza e Selomite.'),
('acf','2cr',11,21,'E amava Roboão mais a Maaca, filha de Absalão, do que a todas as suas outras mulheres e concubinas; porque ele tinha tomado dezoito mulheres, e sessenta concubinas; e gerou vinte e oito filhos, e sessenta filhas.'),
('acf','2cr',11,22,'E Roboão designou Abias, filho de Maaca, para ser chefe e líder entre os seus irmãos, porque queria fazê-lo rei.'),
('acf','2cr',11,23,'E usou de prudência, e de todos os seus filhos, alguns espalhou por todas as terras de Judá, e Benjamim, por todas as cidades fortes; e deu-lhes víveres em abundância; e lhes procurou muitas mulheres.'),
('acf','2cr',12,1,'Sucedeu que, havendo Roboão confirmado o reino, e havendo-se fortalecido, deixou a lei do SENHOR, e com ele todo o Israel.'),
('acf','2cr',12,2,'E sucedeu que, no quinto ano do rei Roboão, Sisaque, rei do Egito, subiu contra Jerusalém (porque tinham transgredido contra o Senhor)'),
('acf','2cr',12,3,'Com mil e duzentos carros e com sessenta mil cavaleiros; e era inumerável o povo que vinha com ele do Egito, de líbios, suquitas e etíopes.'),
('acf','2cr',12,4,'E tomou as cidades fortificadas, que Judá tinha; e chegou até Jerusalém.'),
('acf','2cr',12,5,'Então veio Semaías, o profeta, a Roboão e aos príncipes de Judá que se ajuntaram em Jerusalém por causa de Sisaque, e disse-lhes: Assim diz o Senhor: Vós me deixastes a mim, por isso também eu vos deixei na mão de Sisaque.'),
('acf','2cr',12,6,'Então se humilharam os príncipes de Israel, e o rei, e disseram: O Senhor é justo.'),
('acf','2cr',12,7,'Vendo, pois, o Senhor que se humilhavam, veio a palavra do Senhor a Semaías, dizendo: Humilharam-se, não os destruirei; antes em breve lhes darei algum socorro, para que o meu furor não se derrame sobre Jerusalém, por mão de Sisaque.'),
('acf','2cr',12,8,'Porém serão seus servos; para que conheçam a diferença da minha servidão e da servidão dos reinos da terra.'),
('acf','2cr',12,9,'Subiu, pois, Sisaque, rei do Egito, contra Jerusalém, e tomou os tesouros da casa do Senhor, e os tesouros da casa do rei; levou tudo; também tomou os escudos de ouro, que Salomão fizera.'),
('acf','2cr',12,10,'E fez o rei Roboão em lugar deles escudos de cobre, e os entregou na mão dos chefes da guarda, que guardavam a porta da casa do rei.'),
('acf','2cr',12,11,'E todas as vezes que o rei entrava na casa do Senhor, vinham os da guarda, e os levavam; depois tornavam a pô-los na câmara da guarda.'),
('acf','2cr',12,12,'E humilhando-se ele, a ira do Senhor se desviou dele, para que não o destruísse de todo; porque em Judá ainda havia boas coisas.'),
('acf','2cr',12,13,'Fortificou-se, pois, o rei Roboão em Jerusalém, e reinou; porque Roboão era da idade de quarenta e um anos, quando começou a reinar; e reinou dezessete anos em Jerusalém, a cidade que o Senhor escolheu, dentre todas as tribos de Israel, para pôr ali o seu nome; e era o nome de sua mãe Naamá, amonita.'),
('acf','2cr',12,14,'E fez o que era mau; porquanto não preparou o seu coração para buscar ao Senhor.'),
('acf','2cr',12,15,'Os atos, pois, de Roboão, assim os primeiros, como os últimos, porventura não estão escritos nos livros de Semaías, o profeta, e de Ido, o vidente, na relação das genealogias? E houve guerras entre Roboão e Jeroboão em todos os seus dias.'),
('acf','2cr',12,16,'E Roboão dormiu com seus pais, e foi sepultado na cidade de Davi; e Abias, seu filho, reinou em seu lugar.'),
('acf','2cr',13,1,'No ano décimo oitavo do rei Jeroboão, Abias começou a reinar sobre Judá.'),
('acf','2cr',13,2,'Três anos reinou em Jerusalém; e era o nome de sua mãe Micaía, filha de Uriel de Gibeá; e houve guerra entre Abias e Jeroboão.'),
('acf','2cr',13,3,'E Abias ordenou a peleja com um exército de valentes guerreiros, quatrocentos mil homens escolhidos; e Jeroboão dispôs contra ele a batalha com oitocentos mil homens escolhidos, todos homens corajosos.'),
('acf','2cr',13,4,'E pôs-se Abias em pé em cima do monte de Zemaraim, que está na montanha de Efraim, e disse: Ouvi-me, Jeroboão e todo o Israel:'),
('acf','2cr',13,5,'Porventura não vos convém saber que o Senhor Deus de Israel deu para sempre a Davi a soberania sobre Israel, a ele e a seus filhos, por uma aliança de sal?'),
('acf','2cr',13,6,'Contudo levantou-se Jeroboão, filho de Nebate, servo de Salomão, filho de Davi, e se rebelou contra seu senhor.'),
('acf','2cr',13,7,'E ajuntaram-se a ele homens vadios, filhos de Belial; e fortificaram-se contra Roboão, filho de Salomão, sendo Roboão ainda jovem, e terno de coração, e não lhes podia resistir.'),
('acf','2cr',13,8,'E agora julgais que podeis resistir ao reino do Senhor, que está na mão dos filhos de Davi, visto que sois uma grande multidão, e tendes convosco os bezerros de ouro que Jeroboão vos fez para deuses.'),
('acf','2cr',13,9,'Não lançastes vós fora os sacerdotes do Senhor, os filhos de Arão, e os levitas, e não fizestes para vós sacerdotes, como os povos das outras terras? Qualquer que vem a consagrar-se com um novilho e sete carneiros logo se faz sacerdote daqueles que não são deuses.'),
('acf','2cr',13,10,'Porém, quanto a nós, o Senhor é nosso Deus, e nunca o deixamos; e os sacerdotes que ministram ao Senhor são filhos de Arão, e os levitas se ocupam na sua obra.'),
('acf','2cr',13,11,'E queimam ao Senhor cada manhã e cada tarde holocaustos, incenso aromático, com os pães da proposição sobre a mesa pura, e o castiçal de ouro, e as suas lâmpadas para se acenderem cada tarde, porque nós temos cuidado do serviço do Senhor nosso Deus; porém vós o deixastes.'),
('acf','2cr',13,12,'E eis que Deus está conosco, à nossa frente, como também os seus sacerdotes, tocando com as trombetas, para dar alarme contra vós. Ó filhos de Israel, não pelejeis contra o Senhor Deus de vossos pais; porque não prosperareis.'),
('acf','2cr',13,13,'Mas Jeroboão armou uma emboscada, para dar sobre eles pela retaguarda; de maneira que estavam em frente de Judá e a emboscada por detrás deles.'),
('acf','2cr',13,14,'Então Judá olhou, e eis que tinham que pelejar por diante e por detrás; então clamaram ao Senhor; e os sacerdotes tocaram as trombetas.'),
('acf','2cr',13,15,'E os homens de Judá gritaram; e sucedeu que, gritando os homens de Judá, Deus feriu a Jeroboão e a todo o Israel diante de Abias e de Judá.'),
('acf','2cr',13,16,'E os filhos de Israel fugiram de diante de Judá; e Deus os entregou na sua mão.'),
('acf','2cr',13,17,'De maneira que Abias e o seu povo fizeram grande matança entre eles; porque caíram feridos de Israel quinhentos mil homens escolhidos.'),
('acf','2cr',13,18,'E foram humilhados os filhos de Israel naquele tempo; e os filhos de Judá prevaleceram, porque confiaram no Senhor Deus de seus pais.'),
('acf','2cr',13,19,'E Abias perseguiu Jeroboão; e tomou-lhe a Betel com os lugares da sua jurisdição, e a Jesana com os lugares da sua jurisdição, e a Efrom com os lugares da sua jurisdição.'),
('acf','2cr',13,20,'E Jeroboão não recobrou mais o seu poder nos dias de Abias; porém o Senhor o feriu, e morreu.'),
('acf','2cr',13,21,'Abias, porém, se fortificou, e tomou para si catorze mulheres, e gerou vinte e dois filhos e dezesseis filhas.'),
('acf','2cr',13,22,'Os demais atos de Abias, tanto os seus caminhos como as suas palavras, estão escritos na história do profeta Ido.'),
('acf','2cr',14,1,'E Abias dormiu com seus pais, e o sepultaram na cidade de Davi, e Asa, seu filho, reinou em seu lugar; nos seus dias esteve a terra em paz dez anos.'),
('acf','2cr',14,2,'E Asa fez o que era bom e reto aos olhos do Senhor seu Deus.'),
('acf','2cr',14,3,'Porque tirou os altares dos deuses estranhos, e os altos; e quebrou as imagens, e cortou os bosques.'),
('acf','2cr',14,4,'E mandou a Judá que buscasse ao Senhor Deus de seus pais, e que observasse a lei e o mandamento.'),
('acf','2cr',14,5,'Também tirou de todas as cidades de Judá os altos e as imagens; e sob ele o reino esteve em paz.'),
('acf','2cr',14,6,'E edificou cidades fortificadas em Judá; porque a terra estava quieta, e não havia guerra contra ele naqueles anos; porquanto o Senhor lhe dera repouso.'),
('acf','2cr',14,7,'Disse, pois, a Judá: Edifiquemos estas cidades, e cerquemo-las de muros e torres, portas e ferrolhos, enquanto a terra ainda é nossa, pois buscamos ao Senhor nosso Deus; buscamo-lo, e deu-nos repouso de todos os lados. Edificaram, pois, e prosperaram.'),
('acf','2cr',14,8,'Tinha Asa um exército de trezentos mil de Judá, que traziam pavês e lança; e duzentos e oitenta mil de Benjamim, que traziam escudo e atiravam com arco; todos estes eram homens valentes.'),
('acf','2cr',14,9,'E Zerá, o etíope, saiu contra eles, com um exército de um milhão e com trezentos carros, e chegou até Maressa.'),
('acf','2cr',14,10,'Então Asa saiu contra ele; e ordenaram a batalha no vale de Zefatá, junto a Maressa.'),
('acf','2cr',14,11,'E Asa clamou ao Senhor seu Deus, e disse: Senhor, nada para ti é ajudar, quer o poderoso quer o de nenhuma força; ajuda-nos, pois, Senhor nosso Deus, porque em ti confiamos, e no teu nome viemos contra esta multidão. Senhor, tu és nosso Deus, não prevaleça contra ti o homem.'),
('acf','2cr',14,12,'E o Senhor feriu os etíopes diante de Asa e diante de Judá; e os etíopes fugiram.'),
('acf','2cr',14,13,'E Asa, e o povo que estava com ele os perseguiram até Gerar, e caíram tantos dos etíopes, que já não havia neles resistência alguma; porque foram destruídos diante do Senhor, e diante do seu exército; e levaram dali mui grande despojo.'),
('acf','2cr',14,14,'E feriram todas as cidades nos arredores de Gerar, porque o terror do Senhor veio sobre elas; e saquearam todas as cidades, porque havia nelas muita presa.'),
('acf','2cr',14,15,'Também feriram as malhadas do gado; e levaram ovelhas em abundância, e camelos, e voltaram para Jerusalém.'),
('acf','2cr',15,1,'Então veio o Espírito de Deus sobre Azarias, filho de Odede.'),
('acf','2cr',15,2,'E saiu ao encontro de Asa, e disse-lhe: Ouvi-me, Asa, e todo o Judá e Benjamim: O Senhor está convosco, enquanto vós estais com ele, e, se o buscardes, o achareis; porém, se o deixardes, vos deixará.'),
('acf','2cr',15,3,'E Israel esteve por muitos dias sem o verdadeiro Deus, e sem sacerdote que o ensinasse, e sem lei.'),
('acf','2cr',15,4,'Mas quando na sua angústia voltaram para o Senhor Deus de Israel, e o buscaram, o acharam.'),
('acf','2cr',15,5,'E naqueles tempos não havia paz, nem para o que saía, nem para o que entrava, mas muitas perturbações sobre todos os habitantes daquelas terras.'),
('acf','2cr',15,6,'Porque nação contra nação e cidade contra cidade se despedaçavam; porque Deus os perturbara com toda a angústia.'),
('acf','2cr',15,7,'Mas esforçai-vos, e não desfaleçam as vossas mãos; porque a vossa obra tem uma recompensa.'),
('acf','2cr',15,8,'Ouvindo, pois, Asa estas palavras, e a profecia do profeta Odede, cobrou ânimo e tirou as abominações de toda a terra, de Judá e de Benjamim, como também das cidades que tomara nas montanhas de Efraim, e renovou o altar do Senhor, que estava diante do pórtico do Senhor.'),
('acf','2cr',15,9,'E reuniu a todo o Judá, e Benjamim, e com eles os estrangeiros de Efraim e Manassés, e de Simeão; porque muitos de Israel tinham passado a ele, vendo que o Senhor seu Deus era com ele.'),
('acf','2cr',15,10,'E ajuntaram-se em Jerusalém no terceiro mês; no ano décimo do reinado de Asa.'),
('acf','2cr',15,11,'E no mesmo dia ofereceram em sacrifício ao Senhor, do despojo que trouxeram, setecentos bois e sete mil ovelhas.'),
('acf','2cr',15,12,'E entraram na aliança para buscarem o Senhor Deus de seus pais, com todo o seu coração, e com toda a sua alma;'),
('acf','2cr',15,13,'E de que todo aquele que não buscasse ao Senhor Deus de Israel, morresse; assim o menor como o maior, tanto o homem como a mulher.'),
('acf','2cr',15,14,'E juraram ao Senhor, em alta voz, com júbilo e com trombetas e buzinas.'),
('acf','2cr',15,15,'E todo o Judá se alegrou deste juramento; porque de todo o seu coração juraram, e de toda a sua vontade o buscaram, e o acharam; e o Senhor lhes deu repouso ao redor.'),
('acf','2cr',15,16,'E também a Maaca, sua mãe, o rei Asa depôs, para que não fosse mais rainha, porquanto fizera um horrível ídolo, a Aserá; e Asa destruiu o seu horrível ídolo, e o despedaçou, e o queimou junto ao ribeiro de Cedrom.'),
('acf','2cr',15,17,'Os altos, porém, não foram tirados de Israel; contudo o coração de Asa foi perfeito todos os seus dias.'),
('acf','2cr',15,18,'E trouxe, à casa de Deus, as coisas consagradas por seu pai, e as coisas que ele mesmo tinha consagrado: prata, ouro e vasos.'),
('acf','2cr',15,19,'E não houve guerra até ao ano trigésimo quinto do reinado de Asa.'),
('acf','2cr',16,1,'No trigésimo sexto ano do reinado de Asa, Baasa, rei de Israel, subiu contra Judá e edificou a Ramá, para não deixar ninguém sair, nem chegar a Asa, rei de Judá.'),
('acf','2cr',16,2,'Então Asa tirou a prata e o ouro dos tesouros da casa do Senhor, e da casa do rei; e enviou servos a Ben-Hadade, rei da Síria, que habitava em Damasco, dizendo:'),
('acf','2cr',16,3,'Acordo há entre mim e ti, como houve entre meu pai e o teu; eis que te envio prata e ouro; vai, pois, e anula o teu acordo com Baasa, rei de Israel, para que se retire de sobre mim.'),
('acf','2cr',16,4,'E Ben-Hadade deu ouvidos ao rei Asa, e enviou os capitães dos seus exércitos, contra as cidades de Israel, e eles feriram a Ijom, a Dã, a Abel-Maim, e a todas as cidades-armazéns de Naftali.'),
('acf','2cr',16,5,'E sucedeu que, ouvindo-o Baasa, deixou de edificar a Ramá, e não continuou a sua obra.'),
('acf','2cr',16,6,'Então o rei Asa tomou a todo o Judá, e levaram as pedras de Ramá, e a sua madeira, com que Baasa edificara; e com elas edificou a Geba e a Mizpá.'),
('acf','2cr',16,7,'Naquele mesmo tempo veio Hanani, o vidente, a Asa, rei de Judá, e disse-lhe: Porquanto confiaste no rei da Síria, e não confiaste no Senhor teu Deus, por isso o exército do rei da Síria escapou da tua mão.'),
('acf','2cr',16,8,'Porventura não foram os etíopes e os líbios um grande exército, com muitíssimos carros e cavaleiros? Confiando tu, porém, no Senhor, ele os entregou nas tuas mãos.'),
('acf','2cr',16,9,'Porque, quanto ao Senhor, seus olhos passam por toda a terra, para mostrar-se forte para com aqueles cujo coração é perfeito para com ele; nisto, pois, procedeste loucamente porque desde agora haverá guerras contra ti.'),
('acf','2cr',16,10,'Porém Asa se indignou contra o vidente, e lançou-o na casa do tronco; porque estava enfurecido contra ele, por causa disto; também Asa, no mesmo tempo, oprimiu a alguns do povo.'),
('acf','2cr',16,11,'E eis que os atos de Asa, tanto os primeiros, como os últimos, estão escritos no livro dos reis de Judá e Israel.'),
('acf','2cr',16,12,'E, no ano trinta e nove do seu reinado, Asa caiu doente de seus pés, a sua doença era em extremo grave; contudo, na sua enfermidade, não buscou ao Senhor, mas antes os médicos.'),
('acf','2cr',16,13,'E Asa dormiu com seus pais; e morreu no ano quarenta e um do seu reinado.'),
('acf','2cr',16,14,'E o sepultaram no seu sepulcro, que tinha cavado para si na cidade de Davi, havendo-o deitado na cama, que se enchera de perfumes e especiarias preparadas segundo a arte dos perfumistas; e, destas coisas fizeram-lhe uma grande queima.'),
('acf','2cr',17,1,'E Jeosafá, seu filho, reinou em seu lugar; e fortificou-se contra Israel.'),
('acf','2cr',17,2,'E pôs soldados em todas as cidades fortificadas de Judá, e estabeleceu guarnições na terra de Judá, como também nas cidades de Efraim, que Asa seu pai tinha tomado.'),
('acf','2cr',17,3,'E o Senhor era com Jeosafá; porque andou nos primeiros caminhos de Davi seu pai, e não buscou a Baalins.'),
('acf','2cr',17,4,'Antes buscou ao Deus de seu pai, andou nos seus mandamentos, e não segundo as obras de Israel.'),
('acf','2cr',17,5,'E o Senhor confirmou o reino na sua mão, e todo o Judá deu presentes a Jeosafá, o qual teve riquezas e glória em abundância.'),
('acf','2cr',17,6,'E exaltou-se o seu coração nos caminhos do Senhor e, ainda mais, tirou os altos e os bosques de Judá.'),
('acf','2cr',17,7,'E no terceiro ano do seu reinado enviou ele os seus príncipes, a Bene-Hail, a Obadias, a Zacarias, a Natanael e a Micaías, para ensinarem nas cidades de Judá.'),
('acf','2cr',17,8,'E com eles os levitas, Semaías, Netanias, Zebadias, Asael, Semiramote, Jônatas, Adonias, Tobias e Tobe-Adonias e, com estes levitas, os sacerdotes, Elisama e Jeorão.'),
('acf','2cr',17,9,'E ensinaram em Judá, levando consigo o livro da lei do Senhor; e foram a todas as cidades de Judá, ensinando entre o povo.'),
('acf','2cr',17,10,'E veio o temor do Senhor sobre todos os reinos das terras, que estavam ao redor de Judá, e não guerrearam contra Jeosafá.'),
('acf','2cr',17,11,'E alguns dentre os filisteus traziam presentes a Jeosafá, e prata como tributo; também os árabes lhe trouxeram gado miúdo; sete mil e setecentos carneiros, e sete mil e setecentos bodes.'),
('acf','2cr',17,12,'Cresceu, pois, Jeosafá grandemente em extremo e edificou fortalezas e cidades de provisões em Judá.'),
('acf','2cr',17,13,'E teve muitas obras nas cidades de Judá, e homens de guerra e valentes, em Jerusalém.'),
('acf','2cr',17,14,'E este é o número deles segundo as suas casas paternas; em Judá eram capitàes dos milhares: o chefe Adna, e com ele trezentos mil homens valentes;'),
('acf','2cr',17,15,'E depois dele o capitão Joanã, e com ele duzentos e oitenta mil;'),
('acf','2cr',17,16,'E depois Amasias, filho de Zicri, que voluntariamente se entregou ao Senhor, e com ele duzentos mil homens valentes;'),
('acf','2cr',17,17,'E de Benjamim, Eliada, homem valente, e com ele duzentos mil, armados de arco e de escudo;'),
('acf','2cr',17,18,'E depois dele Jozabade, e com ele cento e oitenta mil, armados para a guerra.'),
('acf','2cr',17,19,'Estes estavam no serviço do rei; afora os que o rei tinha posto nas cidades fortes por todo o Judá.'),
('acf','2cr',18,1,'Tinha, pois, Jeosafá riquezas e glória em abundância, e aparentou-se com Acabe.'),
('acf','2cr',18,2,'E depois de alguns anos desceu ele para Acabe em Samaria; e Acabe matou ovelhas e bois em abundância, para ele e para o povo que vinha com ele; e o persuadiu a subir com ele a Ramote de Gileade.'),
('acf','2cr',18,3,'Porque Acabe, rei de Israel, disse a Jeosafá, rei de Judá: Irás tu comigo a Ramote de Gileade? E ele lhe disse: Como tu és, serei eu; e o meu povo, como o teu povo; iremos contigo à guerra.'),
('acf','2cr',18,4,'Disse mais Jeosafá ao rei de Israel: Peço-te, consulta hoje a palavra do Senhor.'),
('acf','2cr',18,5,'Então o rei de Israel reuniu os profetas, quatrocentos homens, e disse-lhes: Iremos à guerra contra Ramote de Gileade, ou deixarei de ir? E eles disseram: Sobe; porque Deus a entregará na mão do rei.'),
('acf','2cr',18,6,'Disse, porém, Jeosafá: Não há ainda aqui algum profeta do Senhor, para que o consultemos?'),
('acf','2cr',18,7,'Então o rei de Israel disse a Jeosafá: Ainda há um homem por quem podemos consultar ao Senhor; porém eu o odeio, porque nunca profetiza de mim o que é bom, senão sempre o mal; este é Micaías, filho de Inlá. E disse Jeosafá: Não fale o rei assim.'),
('acf','2cr',18,8,'Então o rei de Israel chamou um oficial, e disse: Traze aqui depressa a Micaías, filho de Inlá.'),
('acf','2cr',18,9,'E o rei de Israel, e Jeosafá, rei de Judá, estavam assentados cada um no seu trono, vestidos com suas roupas reais, e estavam assentados na praça à entrada da porta de Samaria; e todos os profetas profetizavam na sua presença.'),
('acf','2cr',18,10,'E Zedequias, filho de Quenaaná, fez para si uns chifres de ferro, e disse: Assim diz o Senhor: Com estes ferirás aos sírios, até de todo os consumires.'),
('acf','2cr',18,11,'E todos os profetas profetizavam o mesmo, dizendo: Sobe a Ramote de Gileade, e triunfarás; porque o Senhor a dará na mão do rei.'),
('acf','2cr',18,12,'E o mensageiro, que foi chamar a Micaías, falou-lhe, dizendo: Eis que as palavras dos profetas, a uma voz, predizem coisas boas para o rei; seja, pois, também a tua palavra como a de um deles, e fala o que é bom.'),
('acf','2cr',18,13,'Porém Micaías disse: Vive o Senhor, que o que meu Deus me disser, isso falarei.'),
('acf','2cr',18,14,'Vindo, pois, ele ao rei, este lhe disse: Micaías, iremos a Ramote de Gileade à guerra, ou deixaremos de ir? E ele disse: Subi, e triunfarás; e serão dados na vossa mão.'),
('acf','2cr',18,15,'E o rei lhe disse: Até quantas vezes, te conjurarei, para que não me fales senão a verdade em nome do Senhor?'),
('acf','2cr',18,16,'Então disse ele: Vi a todo o Israel disperso pelos montes, como ovelhas que não têm pastor; e disse o SENHOR: Estes não têm senhor; torne cada um em paz para sua casa.'),
('acf','2cr',18,17,'Então o rei de Israel disse a Jeosafá: Não te disse eu, que ele não profetizaria de mim o que é bom, porém sempre o mal?'),
('acf','2cr',18,18,'Disse mais: Ouvi, pois, a palavra do Senhor: Vi ao Senhor assentado no seu trono, e todo o exército celestial em pé à sua mão direita, e à sua esquerda.'),
('acf','2cr',18,19,'E disse o Senhor: Quem persuadirá a Acabe rei de Israel, para que suba, e caia em Ramote de Gileade? Um dizia desta maneira, e outro de outra.'),
('acf','2cr',18,20,'Então saiu um espírito e se apresentou diante do Senhor, e disse: Eu o persuadirei. E o Senhor lhe disse: Com quê?'),
('acf','2cr',18,21,'E ele disse: Eu sairei, e serei um espírito de mentira na boca de todos os seus profetas. E disse o Senhor: Tu o persuadirás, e ainda prevalecerás; sai, e faze-o assim.'),
('acf','2cr',18,22,'Agora, pois, eis que o Senhor pôs um espírito de mentira na boca destes teus profetas; e o Senhor falou o mal a teu respeito.'),
('acf','2cr',18,23,'Então Zedequias, filho de Quenaaná, chegando-se, feriu a Micaías no queixo, e disse: Por que caminho passou de mim o Espírito do Senhor para falar a ti?'),
('acf','2cr',18,24,'E disse Micaías: Eis que o verás naquele dia, quando andares de câmara em câmara, para te esconderes.'),
('acf','2cr',18,25,'Então disse o rei de Israel: Tomai a Micaías, e tornai a levá-lo a Amom, o governador da cidade, e a Joás, filho do rei.'),
('acf','2cr',18,26,'E direis: Assim diz o rei: Colocai este homem na casa do cárcere; e sustentai-o com pão de angústia, e com água de angústia, até que eu volte em paz.'),
('acf','2cr',18,27,'E disse Micaías: Se voltares em paz, o Senhor não tem falado por mim. Disse mais: Ouvi, povos todos!'),
('acf','2cr',18,28,'Subiram, pois, o rei de Israel e Jeosafá, rei de Judá, a Ramote de Gileade.'),
('acf','2cr',18,29,'E disse o rei de Israel a Jeosafá: Disfarçando-me eu, então entrarei na peleja; tu, porém, veste as tuas roupas reais. Disfarçou-se, pois, o rei de Israel, e entraram na peleja.'),
('acf','2cr',18,30,'Deu ordem, porém, o rei da Síria aos capitães dos carros que tinha, dizendo: Não pelejareis nem contra pequeno, nem contra grande; senão só contra o rei de Israel.'),
('acf','2cr',18,31,'Sucedeu que, vendo os capitães dos carros a Jeosafá, disseram: Este é o rei de Israel, e o cercaram para pelejar; porém Jeosafá clamou, e o Senhor o ajudou. E Deus os desviou dele.'),
('acf','2cr',18,32,'Porque sucedeu que, vendo os capitães dos carros, que não era o rei de Israel, deixaram de segui-lo.'),
('acf','2cr',18,33,'Então um homem armou o arco e atirou a esmo, e feriu o rei de Israel entre as junturas e a couraça; então disse ao carreteiro: Dá volta, e tira-me do exército, porque estou gravemente ferido.'),
('acf','2cr',18,34,'E aquele dia cresceu a peleja, mas o rei de Israel susteve-se em pé no carro defronte dos sírios até à tarde; e morreu ao tempo do pôr do sol.'),
('acf','2cr',19,1,'E Jeosafá, rei de Judá, voltou em paz à sua casa em Jerusalém.'),
('acf','2cr',19,2,'E Jeú, filho de Hanani, o vidente, saiu ao encontro do rei Jeosafá e lhe disse: Devias tu ajudar ao ímpio, e amar aqueles que odeiam ao Senhor? Por isso virá sobre ti grande ira da parte do Senhor.'),
('acf','2cr',19,3,'Boas coisas contudo se acharam em ti; porque tiraste os bosques da terra, e preparaste o teu coração para buscar a Deus.'),
('acf','2cr',19,4,'Habitou, pois, Jeosafá em Jerusalém; e tornou a passar pelo povo desde Berseba até as montanhas de Efraim, e fez com que tornassem ao Senhor Deus de seus pais.'),
('acf','2cr',19,5,'E estabeleceu juízes na terra, em todas as cidades fortificadas, de cidade em cidade.'),
('acf','2cr',19,6,'E disse aos juízes: Vede o que fazeis; porque não julgais da parte do homem, senão da parte do Senhor, e ele está convosco quando julgardes.'),
('acf','2cr',19,7,'Agora, pois, seja o temor do Senhor convosco; guardai-o, e fazei-o; porque não há no Senhor nosso Deus iniqüidade nem acepção de pessoas, nem aceitação de suborno.'),
('acf','2cr',19,8,'E também estabeleceu Jeosafá a alguns dos levitas e dos sacerdotes e dos chefes dos pais de Israel sobre o juízo do Senhor, e sobre as causas judiciais; e voltaram a Jerusalém.'),
('acf','2cr',19,9,'E deu-lhes ordem, dizendo: Assim fazei no temor do Senhor, com fidelidade, e com coração íntegro.'),
('acf','2cr',19,10,'E em toda a diferença que vier a vós de vossos irmãos que habitam nas suas cidades, entre sangue e sangue, entre lei e mandamento, entre estatutos e juízos, admoestai-os, que não se façam culpados para com o Senhor, e não venha grande ira sobre vós, e sobre vossos irmãos; fazei assim, e não vos fareis culpados.'),
('acf','2cr',19,11,'E eis que Amarias, o sumo sacerdote, presidirá sobre vós em todo o negócio do Senhor; e Zebadias, filho de Ismael, líder da casa de Judá, em todo o negócio do rei; também os oficiais, os levitas, estão perante vós; esforçai-vos, pois, e fazei-o; e o Senhor será com os bons.'),
('acf','2cr',20,1,'E sucedeu que, depois disto, os filhos de Moabe, e os filhos de Amom, e com eles outros dos amonitas, vieram à peleja contra Jeosafá.'),
('acf','2cr',20,2,'Então vieram alguns que avisaram a Jeosafá, dizendo: Vem contra ti uma grande multidão dalém do mar e da Síria; e eis que já estão em Hazazom-Tamar, que é En-Gedi.'),
('acf','2cr',20,3,'Então Jeosafá temeu, e pôs-se a buscar o Senhor, e apregoou jejum em todo o Judá.'),
('acf','2cr',20,4,'E Judá se ajuntou, para pedir socorro ao Senhor; também de todas as cidades de Judá vieram para buscar ao Senhor.'),
('acf','2cr',20,5,'E pôs-se Jeosafá em pé na congregação de Judá e de Jerusalém, na casa do Senhor, diante do pátio novo.'),
('acf','2cr',20,6,'E disse: Ah! Senhor Deus de nossos pais, porventura não és tu Deus nos céus? Não és tu que dominas sobre todos os reinos das nações? Na tua mão há força e potência, e não há quem te possa resistir.'),
('acf','2cr',20,7,'Porventura, ó nosso Deus, não lançaste fora os moradores desta terra de diante do teu povo Israel, e não a deste para sempre à descendência de Abraão, teu amigo?'),
('acf','2cr',20,8,'E habitaram nela e edificaram-te nela um santuário ao teu nome, dizendo:'),
('acf','2cr',20,9,'Se algum mal nos sobrevier, espada, juízo, peste, ou fome, nós nos apresentaremos diante desta casa e diante de ti, pois teu nome está nesta casa, e clamaremos a ti na nossa angústia, e tu nos ouvirás e livrarás.'),
('acf','2cr',20,10,'Agora, pois, eis que os filhos de Amom, e de Moabe e os das montanhas de Seir, pelos quais não permitiste passar a Israel, quando vinham da terra do Egito, mas deles se desviaram e não os destruíram,'),
('acf','2cr',20,11,'Eis que nos dão o pago, vindo para lançar-nos fora da tua herança, que nos fizeste herdar.'),
('acf','2cr',20,12,'Ah! nosso Deus, porventura não os julgarás? Porque em nós não há força perante esta grande multidão que vem contra nós, e não sabemos o que faremos; porém os nossos olhos estão postos em ti.'),
('acf','2cr',20,13,'E todo o Judá estava em pé perante o Senhor, como também as suas crianças, as suas mulheres, e os seus filhos.'),
('acf','2cr',20,14,'Então veio o Espírito do Senhor, no meio da congregação, sobre Jaaziel, filho de Zacarias, filho de Benaia, filho de Jeiel, filho de Matanias, levita, dos filhos de Asafe,'),
('acf','2cr',20,15,'E disse: Dai ouvidos todo o Judá, e vós, moradores de Jerusalém, e tu, ó rei Jeosafá; assim o Senhor vos diz: Não temais, nem vos assusteis por causa desta grande multidão; pois a peleja não é vossa, mas de Deus.'),
('acf','2cr',20,16,'Amanhã descereis contra eles; eis que sobem pela ladeira de Ziz, e os achareis no fim do vale, diante do deserto de Jeruel.'),
('acf','2cr',20,17,'Nesta batalha não tereis que pelejar; postai-vos, ficai parados, e vede a salvação do Senhor para convosco, ó Judá e Jerusalém. Não temais, nem vos assusteis; amanhã saí-lhes ao encontro, porque o Senhor será convosco.'),
('acf','2cr',20,18,'Então Jeosafá se prostrou com o rosto em terra, e todo o Judá e os moradores de Jerusalém se lançaram perante o Senhor, adorando-o.'),
('acf','2cr',20,19,'E levantaram-se os levitas, dos filhos dos coatitas, e dos filhos dos coratitas, para louvarem ao Senhor Deus de Israel, com voz muito alta.'),
('acf','2cr',20,20,'E pela manhã cedo se levantaram e saíram ao deserto de Tecoa; e, ao saírem, Jeosafá pôs-se em pé, e disse: Ouvi-me, ó Judá, e vós, moradores de Jerusalém: Crede no Senhor vosso Deus, e estareis seguros; crede nos seus profetas, e prosperareis;'),
('acf','2cr',20,21,'E aconselhou-se com o povo, e ordenou cantores para o Senhor, que louvassem à Majestade santa, saindo diante dos armados, e dizendo: Louvai ao Senhor porque a sua benignidade dura para sempre.'),
('acf','2cr',20,22,'E, quando começaram a cantar e a dar louvores, o Senhor pôs emboscadas contra os filhos de Amom e de Moabe e os das montanhas de Seir, que vieram contra Judá, e foram desbaratados.'),
('acf','2cr',20,23,'Porque os filhos de Amom e de Moabe se levantaram contra os moradores das montanhas de Seir, para os destruir e exterminar; e, acabando eles com os moradores de Seir, ajudaram uns aos outros a destruir-se.'),
('acf','2cr',20,24,'Nisso chegou Judá à atalaia do deserto; e olharam para a multidão, e eis que eram corpos mortos, que jaziam em terra, e nenhum escapou.'),
('acf','2cr',20,25,'E vieram Jeosafá e o seu povo para saquear os seus despojos, e acharam entre eles riquezas e cadáveres em abundância, assim como objetos preciosos; e tomaram para si tanto, que não podiam levar; e três dias saquearam o despojo, porque era muito.'),
('acf','2cr',20,26,'E ao quarto dia se ajuntaram no vale de Beraca; pois ali louvaram ao Senhor. Por isso chamaram aquele lugar o vale de Beraca, até ao dia de hoje.'),
('acf','2cr',20,27,'Então voltaram todos os homens de Judá e de Jerusalém, e Jeosafá à frente deles, e tornaram a Jerusalém com alegria; porque o Senhor os alegrara sobre os seus inimigos.'),
('acf','2cr',20,28,'E vieram a Jerusalém com saltérios, com harpas e com trombetas, para a casa do Senhor.'),
('acf','2cr',20,29,'E veio o temor de Deus sobre todos os reinos daquelas terras, ouvindo eles que o Senhor havia pelejado contra os inimigos de Israel.'),
('acf','2cr',20,30,'E o reino de Jeosafá ficou quieto; e o seu Deus lhe deu repouso ao redor.'),
('acf','2cr',20,31,'E Jeosafá reinou sobre Judá; era da idade de trinta e cinco anos quando começou a reinar e vinte e cinco anos reinou em Jerusalém; e o nome de sua mãe era Azuba, filha de Sili.'),
('acf','2cr',20,32,'E andou no caminho de Asa, seu pai, e não se desviou dele, fazendo o que era reto aos olhos do Senhor.'),
('acf','2cr',20,33,'Contudo os altos não foram tirados porque o povo não tinha ainda disposto o seu coração para com o Deus de seus pais.'),
('acf','2cr',20,34,'Ora, o restante dos atos de Jeosafá, assim, desde os primeiros até os últimos, eis que está escrito nas notas de Jeú, filho de Hanani, que as inseriu no livro dos reis de Israel.'),
('acf','2cr',20,35,'Porém, depois disto, Jeosafá, rei de Judá, se aliou com Acazias, rei de Israel, que procedeu com toda a impiedade.'),
('acf','2cr',20,36,'E aliou-se com ele, para fazerem navios que fossem a Társis; e fizeram os navios em Eziom-Geber.'),
('acf','2cr',20,37,'Porém Eliezer, filho de Dodava, de Maressa, profetizou contra Jeosafá, dizendo: Porquanto te aliaste com Acazias, o Senhor despedaçou as tuas obras. E os navios se quebraram, e não puderam ir a Társis.'),
('acf','2cr',21,1,'Depois Jeosafá dormiu com seus pais, e foi sepultado junto a eles na cidade de Davi; e Jeorão, seu filho, reinou em seu lugar.'),
('acf','2cr',21,2,'E teve irmãos, filhos de Jeosafá: Azarias, Jeiel, Zacarias, Asarias, Micael e Sefatias; todos estes foram filhos de Jeosafá, rei de Israel.'),
('acf','2cr',21,3,'E seu pai lhes deu muitos presentes de prata, de ouro e de coisas preciosíssimas, juntamente com cidades fortificadas em Judá; porém, o reino, deu a Jeorão, porquanto era o primogênito.'),
('acf','2cr',21,4,'E, subindo Jeorão ao reino de seu pai, e havendo-se fortificado, matou a todos os seus irmãos à espada, como também a alguns dos príncipes de Israel.'),
('acf','2cr',21,5,'Da idade de trinta e dois anos era Jeorão, quando começou a reinar; e reinou oito anos em Jerusalém.'),
('acf','2cr',21,6,'E andou no caminho dos reis de Israel, como fazia a casa de Acabe; porque tinha a filha de Acabe por mulher; e fazia o que era mau aos olhos do Senhor.'),
('acf','2cr',21,7,'Porém o Senhor não quis destruir a casa de Davi, em atenção à aliança que tinha feito com Davi; e porque também tinha falado que lhe daria por todos os dias uma lâmpada, a ele e a seus filhos.'),
('acf','2cr',21,8,'Nos seus dias se revoltaram os edomitas contra o mando de Judá, e constituíram para si um rei.'),
('acf','2cr',21,9,'Por isso Jeorão passou adiante com os seus príncipes, e todos os carros com ele; levantou-se de noite, e feriu aos edomeus, que o tinham cercado, como também aos capitães dos carros.'),
('acf','2cr',21,10,'Todavia os edomitas se revoltaram contra o mando de Judá até ao dia de hoje; então no mesmo tempo Libna se revoltou contra o seu mando; porque deixara ao Senhor Deus de seus pais.'),
('acf','2cr',21,11,'Ele também fez altos nos montes de Judá; e fez com que se corrompessem os moradores de Jerusalém, e até a Judá impeliu a isso.'),
('acf','2cr',21,12,'Então lhe veio um escrito da parte de Elias, o profeta, que dizia: Assim diz o Senhor Deus de Davi teu pai: Porquanto não andaste nos caminhos de Jeosafá, teu pai, e nos caminhos de Asa, rei de Judá,'),
('acf','2cr',21,13,'Mas andaste no caminho dos reis de Israel, e fizeste prostituir a Judá e aos moradores de Jerusalém, segundo a prostituição da casa de Acabe, e também mataste a teus irmãos da casa de teu pai, melhores do que tu;'),
('acf','2cr',21,14,'Eis que o Senhor ferirá com um grande flagelo ao teu povo, aos teus filhos, às tuas mulheres e a todas as tuas fazendas.'),
('acf','2cr',21,15,'Tu também terás grande enfermidade por causa de uma doença em tuas entranhas, até que elas saiam, de dia em dia, por causa do mal.'),
('acf','2cr',21,16,'Despertou, pois, o Senhor, contra Jeorão o espírito dos filisteus e dos árabes, que estavam do lado dos etíopes.'),
('acf','2cr',21,17,'Estes subiram a Judá, e deram sobre ela, e levaram todos os bens que se achou na casa do rei, como também a seus filhos e a suas mulheres; de modo que não lhe deixaram filho algum, senão a Jeoacaz, o mais moço de seus filhos.'),
('acf','2cr',21,18,'E depois de tudo isto o Senhor o feriu nas suas entranhas com uma enfermidade incurável.'),
('acf','2cr',21,19,'E sucedeu que, depois de muito tempo, ao fim de dois anos, saíram-lhe as entranhas por causa da doença; e morreu daquela grave enfermidade; e o seu povo não lhe queimou aroma como queimara a seus pais.'),
('acf','2cr',21,20,'Era da idade de trinta e dois anos quando começou a reinar, e reinou oito anos em Jerusalém; e foi sem deixar de si saudades; e sepultaram-no na cidade de Davi, porém não nos sepulcros dos reis.'),
('acf','2cr',22,1,'E os moradores de Jerusalém, em lugar de Jeorão, fizeram rei a Acazias, seu filho mais moço, porque a tropa, que viera com os árabes ao arraial, tinha matado a todos os mais velhos. Assim reinou Acazias, filho de Jeorão, rei de Judá.'),
('acf','2cr',22,2,'Era da idade de quarenta e dois anos, quando começou a reinar, e reinou um ano em Jerusalém; e era o nome de sua mãe Atalia, filha de Onri.'),
('acf','2cr',22,3,'Também ele andou nos caminhos da casa de Acabe, porque sua mãe era sua conselheira, para proceder impiamente.'),
('acf','2cr',22,4,'E fez o que era mau aos olhos do Senhor, como a casa de Acabe, porque eles eram seus conselheiros depois da morte de seu pai, para a sua perdição.'),
('acf','2cr',22,5,'Também andou nos conselhos deles, e foi com Jorão, filho de Acabe, rei de Israel, à peleja contra Hazael, rei da Síria, junto a Ramote de Gileade; e os sírios feriram a Jorão.'),
('acf','2cr',22,6,'E voltou para curar-se em Jizreel, das feridas que lhe fizeram em Ramá, pelejando contra Hazael, rei da Síria; e Acazias, filho de Jeorão, rei de Judá, desceu para ver a Jorão, filho de Acabe, em Jizreel, porque estava doente.'),
('acf','2cr',22,7,'Foi, pois, da vontade de Deus, que Acazias, para sua ruína, visitasse Jorão; porque chegando ele, saiu com Jorão contra Jeú, filho de Ninsi, a quem o Senhor tinha ungido para desarraigar a casa de Acabe.'),
('acf','2cr',22,8,'E sucedeu que, executando Jeú juízo contra a casa de Acabe, achou os príncipes de Judá e os filhos dos irmãos de Acazias, que serviam a Acazias, e os matou.'),
('acf','2cr',22,9,'Depois buscou a Acazias (porque se tinha escondido em Samaria), e o alcançaram, e o trouxeram a Jeú, e o mataram, e o sepultaram; porque disseram: Filho é de Jeosafá, que buscou ao Senhor com todo o seu coração. E já não tinha a casa de Acazias ninguém que tivesse força para o reino.'),
('acf','2cr',22,10,'Vendo, pois, Atalia, mãe de Acazias, que seu filho era morto, levantou-se e destruiu toda a descendência real da casa de Judá.'),
('acf','2cr',22,11,'Porém Jeosabeate, filha do rei, tomou a Joás, filho de Acazias, furtando-o dentre os filhos do rei, aos quais matavam, e o pôs com a sua ama na câmara dos leitos; assim Jeosabeate, filha do rei Jeorão, mulher do sacerdote Joiada (porque era irmã de Acazias), o escondeu de Atalia, de modo que ela não o matou.'),
('acf','2cr',22,12,'E esteve com eles seis anos escondido na casa de Deus; e Atalia reinou sobre a terra.'),
('acf','2cr',23,1,'Porém no sétimo ano Joiada se animou, e tomou consigo em aliança os chefes de cem, a Azarias, filho de Jeroão, a Ismael, filho de Joanã, a Azarias, filho de Obede, a Maaséias, filho de Adaías, e a Elisafate, filho de Zicri.'),
('acf','2cr',23,2,'Estes percorreram a Judá e ajuntaram os levitas de todas as cidades de Judá e os chefes dos pais de Israel, e vieram para Jerusalém.'),
('acf','2cr',23,3,'E toda aquela congregação fez aliança com o rei na casa de Deus; e Joiada lhes disse: Eis que o filho do rei reinará, como o Senhor falou a respeito dos filhos de Davi.'),
('acf','2cr',23,4,'Isto é o que haveis de fazer; uma terça parte de vós, ou seja, dos sacerdotes e dos levitas que entram no sábado, serão guardas das portas;'),
('acf','2cr',23,5,'E uma terça parte estará na casa do rei; e a outra terça parte à porta do fundamento; e todo o povo estará nos pátios da casa do Senhor.'),
('acf','2cr',23,6,'Porém ninguém entre na casa do Senhor, senão os sacerdotes e os levitas que ministram; estes entrarão, porque são santos; mas todo o povo fará a guarda diante do Senhor.'),
('acf','2cr',23,7,'E os levitas cercarão o rei de todos os lados, cada um com as suas armas na mão; e qualquer que entrar na casa será morto; porém vós estareis com o rei, quando entrar e quando sair.'),
('acf','2cr',23,8,'E fizeram os levitas e todo o Judá conforme a tudo o que ordenara o sacerdote Joiada; e tomou cada um os seus homens, tanto os que entravam no sábado como os que saíam no sábado; porque o sacerdote Joiada não tinha despedido as turmas.'),
('acf','2cr',23,9,'Também o sacerdote Joiada deu aos capitàes de cem as lanças, os escudos e as rodelas que foram do rei Davi, os quais estavam na casa de Deus.'),
('acf','2cr',23,10,'E dispôs todo o povo, a cada um com as suas armas na mão, desde o lado direito da casa até o lado esquerdo da casa, do lado do altar e da casa, em redor do rei.'),
('acf','2cr',23,11,'Então tiraram para fora ao filho do rei, e lhe puseram a coroa; deram-lhe o testemunho, e o fizeram rei; e Joiada e seus filhos o ungiram, e disseram: Viva o rei!'),
('acf','2cr',23,12,'Ouvindo, pois, Atalia a voz do povo que concorria e louvava o rei, veio ao povo, à casa do Senhor.'),
('acf','2cr',23,13,'E olhou, e eis que o rei estava junto à coluna, à entrada, e os priinsert into public.bible_verses (version, book_abbrev, chapter, verse, text) values
('acf','ed',1,1,'No primeiro ano de Ciro, rei da Pérsia (para que se cumprisse a palavra do SENHOR, pela boca de Jeremias), despertou o SENHOR o espírito de Ciro, rei da Pérsia, o qual fez passar pregão por todo o seu reino, como também por escrito, dizendo:'),
('acf','ed',1,2,'Assim diz Ciro, rei da Pérsia: O Senhor Deus dos céus me deu todos os reinos da terra, e me encarregou de lhe edificar uma casa em Jerusalém, que está em Judá.'),
('acf','ed',1,3,'Quem há entre vós, de todo o seu povo, seja seu Deus com ele, e suba a Jerusalém, que está em Judá, e edifique a casa do Senhor Deus de Israel (ele é o Deus) que está em Jerusalém.'),
('acf','ed',1,4,'E todo aquele que ficar atrás em algum lugar em que andar peregrinando, os homens do seu lugar o ajudarão com prata, com ouro, com bens, e com gados, além das dádivas voluntárias para a casa de Deus, que está em Jerusalém.'),
('acf','ed',1,5,'Então se levantaram os chefes dos pais de Judá e Benjamim, e os sacerdotes e os levitas, com todos aqueles cujo espírito Deus despertou, para subirem a edificar a casa do Senhor, que está em Jerusalém.'),
('acf','ed',1,6,'E todos os que habitavam nos arredores lhes firmaram as mãos com vasos de prata, com ouro, com bens e com gado, e com coisas preciosas; além de tudo o que voluntariamente se deu.'),
('acf','ed',1,7,'Também o rei Ciro tirou os utensílios da casa do Senhor, que Nabucodonosor tinha trazido de Jerusalém, e que tinha posto na casa de seus deuses.'),
('acf','ed',1,8,'Estes tirou Ciro, rei da Pérsia, pela mão de Mitredate, o tesoureiro, que os entregou contados a Sesbazar, príncipe de Judá.'),
('acf','ed',1,9,'E este é o número deles: trinta travessas de ouro, mil travessas de prata, vinte e nove facas,'),
('acf','ed',1,10,'Trinta bacias de ouro, mais outras quatrocentas e dez bacias de prata, e mil outros utensílios.'),
('acf','ed',1,11,'Todos os utensílios de ouro e de prata foram cinco mil e quatrocentos; todos estes levou Sesbazar, quando os do cativeiro subiram de babilônia para Jerusalém.'),
('acf','ed',2,1,'Estes são os filhos da província, que subiram do cativeiro, dentre os exilados, que Nabucodonosor, rei de babilônia, tinha transportado a babilônia, e tornaram a Jerusalém e a Judá, cada um para a sua cidade;'),
('acf','ed',2,2,'Os quais vieram com Zorobabel, Jesua, Neemias, Seraías, Reelaías, Mardoqueu, Bilsã, Mizpar, Bigvai, Reum e Baaná. O número dos homens do povo de Israel:'),
('acf','ed',2,3,'Os filhos de Parós, dois mil cento e setenta e dois.'),
('acf','ed',2,4,'Os filhos de Sefatias, trezentos e setenta e dois.'),
('acf','ed',2,5,'Os filhos de Ará, setecentos e setenta e cinco.'),
('acf','ed',2,6,'Os filhos de Paate-Moabe, dos filhos de Jesuá-Joabe, dois mil oitocentos e doze.'),
('acf','ed',2,7,'Os filhos de Elão, mil duzentos e cinqüenta e quatro.'),
('acf','ed',2,8,'Os filhos de Zatu, novecentos e quarenta e cinco.'),
('acf','ed',2,9,'Os filhos de Zacai, setecentos e sessenta.'),
('acf','ed',2,10,'Os filhos de Bani, seiscentos e quarenta e dois.'),
('acf','ed',2,11,'Os filhos de Bebai, seiscentos e vinte e três.'),
('acf','ed',2,12,'Os filhos de Azgade, mil duzentos e vinte e dois.'),
('acf','ed',2,13,'Os filhos de Adonicão, seiscentos e sessenta e seis.'),
('acf','ed',2,14,'Os filhos de Bigvai, dois mil e cinqüenta e seis.'),
('acf','ed',2,15,'Os filhos de Adim, quatrocentos e cinqüenta e quatro.'),
('acf','ed',2,16,'Os filhos de Ater, de Ezequias, noventa e oito.'),
('acf','ed',2,17,'Os filhos de Bezai, trezentos e vinte e três.'),
('acf','ed',2,18,'Os filhos de Jora, cento e doze.'),
('acf','ed',2,19,'Os filhos de Hasum, duzentos e vinte e três.'),
('acf','ed',2,20,'Os filhos de Gibar, noventa e cinco.'),
('acf','ed',2,21,'Os filhos de Belém, cento e vinte e três.'),
('acf','ed',2,22,'Os homens de Netofá, cinqüenta e seis.'),
('acf','ed',2,23,'Os homens de Anatote, cento e vinte e oito.'),
('acf','ed',2,24,'Os filhos de Azmavete, quarenta e dois.'),
('acf','ed',2,25,'Os filhos de Quiriate-Arim, Quefira e Beerote, setecentos e quarenta e três.'),
('acf','ed',2,26,'Os filhos de Ramá, e de Geba, seiscentos e vinte e um.'),
('acf','ed',2,27,'Os homens de Micmás, cento e vinte e dois.'),
('acf','ed',2,28,'Os homens de Betel e de Ai, duzentos e vinte e três.'),
('acf','ed',2,29,'Os filhos de Nebo, cinqüenta e dois.'),
('acf','ed',2,30,'Os filhos de Magbis, cento e cinqüenta e seis.'),
('acf','ed',2,31,'Os filhos do outro Elão, mil duzentos e cinqüenta e quatro.'),
('acf','ed',2,32,'Os filhos de Harim, trezentos e vinte.'),
('acf','ed',2,33,'Os filhos de Lode, de Hadide e de Ono, setecentos e vinte e cinco.'),
('acf','ed',2,34,'Os filhos de Jericó, trezentos e quarenta e cinco.'),
('acf','ed',2,35,'Os filhos de Senaá, três mil seiscentos e trinta.'),
('acf','ed',2,36,'Os sacerdotes: os filhos de Jedaías, da casa de Jesuá, novecentos e setenta e três.'),
('acf','ed',2,37,'Os filhos de Imer, mil e cinqüenta e dois.'),
('acf','ed',2,38,'Os filhos de Pasur, mil duzentos e quarenta e sete.'),
('acf','ed',2,39,'Os filhos de Harim, mil e dezessete.'),
('acf','ed',2,40,'Os levitas: os filhos de Jesuá e Cadmiel, dos filhos de Hodavias, setenta e quatro.'),
('acf','ed',2,41,'Os cantores: os filhos de Asafe, cento e vinte e oito.'),
('acf','ed',2,42,'Os filhos dos porteiros: os filhos de Salum, os filhos de Ater, os filhos de Talmom, os filhos de Acube, os filhos de Hatita, os filhos de Sobai; ao todo, cento e trinta e nove.'),
('acf','ed',2,43,'Os netinins: os filhos de Zia, os filhos de Hasufa, os filhos de Tabaote,'),
('acf','ed',2,44,'Os filhos de Querós, os filhos de Siá, os filhos de Padom,'),
('acf','ed',2,45,'Os filhos de Lebaná, os filhos de Hagaba, os filhos de Acube,'),
('acf','ed',2,46,'Os filhos de Hagabe, os filhos de Sanlai, os filhos de Hanã,'),
('acf','ed',2,47,'Os filhos de Gidel, os filhos de Gaar, os filhos de Reaías,'),
('acf','ed',2,48,'Os filhos de Rezim, os filhos de Necoda, os filhos de Gazão,'),
('acf','ed',2,49,'Os filhos de Uzá, os filhos de Paseá, os filhos de Besai,'),
('acf','ed',2,50,'Os filhos de Asna, os filhos de Meunim, os filhos de Nefussim,'),
('acf','ed',2,51,'Os filhos de Bacbuque, os filhos de Hacufa, os filhos de Harur,'),
('acf','ed',2,52,'Os filhos de Bazlute, os filhos de Meída, os filhos de Harsa,'),
('acf','ed',2,53,'Os filhos de Barcos, os filhos de Sísera, os filhos de Tama.'),
('acf','ed',2,54,'Os filhos de Neziá, os filhos de Hatifa.'),
('acf','ed',2,55,'Os filhos dos servos de Salomão; os filhos de Sotai, os filhos de Soferete, os filhos de Peruda,'),
('acf','ed',2,56,'Os filhos de Jaalá, os filhos de Darcom, os filhos de Gidel,'),
('acf','ed',2,57,'Os filhos de Sefatias, os filhos de Hatil, os filhos de PoquereteHazebaim, os filhos de Ami.'),
('acf','ed',2,58,'Todos os netinins, e os filhos dos servos de Salomão, trezentos e noventa e dois.'),
('acf','ed',2,59,'Também estes subiram de Tel-Melá e Tel-Harsa, Querube, Adã e Imer; porém não puderam provar que as suas famílias e a sua linhagem eram de Israel:'),
('acf','ed',2,60,'Os filhos de Delaías, os filhos de Tobias, os filhos de Necoda, seiscentos e cinqüenta e dois.'),
('acf','ed',2,61,'E dos filhos dos sacerdotes: os filhos de Habaías, os filhos de Coz, os filhos de Barzilai, que tomou mulher das filhas de Barzilai, o gileadita, e que foi chamado do seu nome.'),
('acf','ed',2,62,'Estes procuraram o seu registro entre os que estavam arrolados nas genealogias, mas não se acharam nelas; assim, por imundos, foram excluídos do sacerdócio.'),
('acf','ed',2,63,'E o governador lhes disse que não comessem das coisas consagradas, até que houvesse sacerdote com Urim e com Tumim.'),
('acf','ed',2,64,'Toda esta congregação junta foi de quarenta e dois mil trezentos e sessenta,'),
('acf','ed',2,65,'Afora os seus servos e as suas servas, que foram sete mil trezentos e trinta e sete; também tinha duzentos cantores e cantoras.'),
('acf','ed',2,66,'Os seus cavalos, setecentos e trinta e seis; os seus mulos, duzentos e quarenta e cinco;'),
('acf','ed',2,67,'Os seus camelos, quatrocentos e trinta e cinco; os jumentos, seis mil setecentos e vinte.'),
('acf','ed',2,68,'E alguns dos chefes dos pais, vindo à casa do Senhor, que habita em Jerusalém, deram ofertas voluntárias para a casa de Deus, para a estabelecerem no seu lugar.'),
('acf','ed',2,69,'Conforme as suas posses, deram para o tesouro da obra, em ouro, sessenta e uma mil dracmas, e em prata cinco mil libras, e cem vestes sacerdotais.'),
('acf','ed',2,70,'E habitaram os sacerdotes e os levitas, e alguns do povo, tanto os cantores, como os porteiros, e os netinins, nas suas cidades; como também todo o Israel nas suas cidades.'),
('acf','ed',3,1,'Chegando, pois, o sétimo mês, e estando os filhos de Israel já nas cidades, ajuntou-se o povo, como um só homem, em Jerusalém.'),
('acf','ed',3,2,'E levantou-se Jesuá, filho de Jozadaque, e seus irmãos, os sacerdotes, e Zorobabel, filho de Sealtiel, e seus irmãos, e edificaram o altar do Deus de Israel, para oferecerem sobre ele holocaustos, como está escrito na lei de Moisés, o homem de Deus.'),
('acf','ed',3,3,'E firmaram o altar sobre as suas bases, porque o terror estava sobre eles, por causa dos povos das terras; e ofereceram sobre ele holocaustos ao Senhor, holocaustos pela manhã e à tarde.'),
('acf','ed',3,4,'E celebraram a festa dos tabernáculos, como está escrito; ofereceram holocaustos cada dia, por ordem, conforme ao rito, cada coisa em seu dia.'),
('acf','ed',3,5,'E depois disto o holocausto contínuo, e os das luas novas e de todas as solenidades consagradas ao Senhor; como também de qualquer que oferecia oferta voluntária ao Senhor;'),
('acf','ed',3,6,'Desde o primeiro dia do sétimo mês começaram a oferecer holocaustos ao SENHOR; porém ainda não estavam postos os fundamentos do templo do SENHOR.'),
('acf','ed',3,7,'Deram, pois, o dinheiro aos pedreiros e carpinteiros, como também comida e bebida, e azeite aos sidônios, e aos tírios, para trazerem do Líbano madeira de cedro ao mar, para Jope, segundo a concessão que lhes tinha feito Ciro, rei da Pérsia.'),
('acf','ed',3,8,'E no segundo ano da sua vinda à casa de Deus em Jerusalém, no segundo mês, Zorobabel, filho de Sealtiel, e Jesuá, filho de Jozadaque, e os outros seus irmãos, os sacerdotes e os levitas, e todos os que vieram do cativeiro a Jerusalém, começaram a obra da casa do Senhor, e constituíram os levitas da idade de vinte anos para cima, para que a dirigissem.'),
('acf','ed',3,9,'Então se levantou Jesuá, seus filhos, e seus irmãos, Cadmiel e seus filhos, os filhos de Judá, como um só homem, para dirigirem os que faziam a obra na casa de Deus, bem como os filhos de Henadade, seus filhos e seus irmãos, os levitas.'),
('acf','ed',3,10,'Quando, pois, os edificadores lançaram os alicerces do templo do Senhor, então apresentaram-se os sacerdotes, já vestidos e com trombetas, e os levitas, filhos de Asafe, com címbalos, para louvarem ao Senhor conforme à instituição de Davi, rei de Israel.'),
('acf','ed',3,11,'E cantavam juntos por grupo, louvando e rendendo graças ao Senhor, dizendo: porque é bom; porque a sua benignidade dura para sempre sobre Israel. E todo o povo jubilou com altas vozes, quando louvaram ao Senhor, pela fundação da casa do Senhor.'),
('acf','ed',3,12,'Porém muitos dos sacerdotes, e levitas e chefes dos pais, já idosos, que viram a primeira casa, choraram em altas vozes quando à sua vista foram lançados os fundamentos desta casa; mas muitos levantaram as vozes com júbilo e com alegria.'),
('acf','ed',3,13,'De maneira que não discernia o povo as vozes do júbilo de alegria das vozes do choro do povo; porque o povo jubilava com tão altas vozes, que o som se ouvia de muito longe.'),
('acf','ed',4,1,'Ouvindo, pois, os adversários de Judá e Benjamim que os que voltaram do cativeiro edificavam o templo ao SENHOR Deus de Israel,'),
('acf','ed',4,2,'Chegaram-se a Zorobabel e aos chefes dos pais, e disseram-lhes: Deixai-nos edificar convosco, porque, como vós, buscaremos a vosso Deus; como também já lhe sacrificamos desde os dias de Esar-Hadom, rei da Assíria, que nos fez subir aqui.'),
('acf','ed',4,3,'Porém Zorobabel, e Jesuá, e os outros chefes dos pais de Israel lhes disseram: Não convém que nós e vós edifiquemos casa a nosso Deus; mas nós sozinhos a edificaremos ao Senhor Deus de Israel, como nos ordenou o rei Ciro, rei da Pérsia.'),
('acf','ed',4,4,'Todavia o povo da terra debilitava as mãos do povo de Judá, e inquietava-os no edificar.'),
('acf','ed',4,5,'E alugaram contra eles conselheiros, para frustrarem o seu plano, todos os dias de Ciro, rei da Pérsia, até ao reinado de Dario, rei da Pérsia.'),
('acf','ed',4,6,'No reinado de Assuero, no princípio do seu reinado, escreveram uma acusação contra os habitantes de Judá e de Jerusalém.'),
('acf','ed',4,7,'E nos dias de Artaxerxes escreveram Bislão, Mitredate, Tabeel, e os outros seus companheiros, a Artaxerxes, rei da Pérsia; e a carta estava escrita em caracteres siríacos, e na língua siríaca.'),
('acf','ed',4,8,'Escreveram, pois, Reum, o chanceler, e Sinsai, o escrivão, uma carta contra Jerusalém, ao rei Artaxerxes, do teor seguinte:'),
('acf','ed',4,9,'Então escreveu Reum, o chanceler, e Sinsai, o escrivão, e os outros seus companheiros, os dinaítas, afarsaquitas, tarpelitas, afarsitas, arquevitas, babilônios, susanquitas, deavitas, elamitas,'),
('acf','ed',4,10,'E os outros povos, que o grande e afamado Asnapar transportou, e que fez habitar na cidade de Samaria, e nas demais províncias dalém do rio, em tal tempo.'),
('acf','ed',4,11,'Este, pois, é o teor da carta que mandaram ao rei Artaxerxes: Teus servos, os homens dalém do rio, em tal tempo.'),
('acf','ed',4,12,'Saiba o rei que os judeus, que subiram de ti, vieram a nós em Jerusalém, e reedificam aquela rebelde e malvada cidade, e vão restaurando os seus muros, e reparando os seus fundamentos.'),
('acf','ed',4,13,'Agora saiba o rei que, se aquela cidade se reedificar, e os muros se restaurarem, eles não pagarão os direitos, os tributos e os pedágios; e assim se danificará a fazenda dos reis.'),
('acf','ed',4,14,'Agora, pois, porquanto somos assalariados do palácio, e não nos convém ver a desonra do rei, por isso mandamos avisar ao rei,'),
('acf','ed',4,15,'Para que se busque no livro das crônicas de teus pais. E acharás no livro das crônicas, e saberás que aquela foi uma cidade rebelde, e danosa aos reis e províncias, e que nela houve rebelião em tempos antigos; por isso foi aquela cidade destruída.'),
('acf','ed',4,16,'Nós, pois, fazemos notório ao rei que, se aquela cidade se reedificar, e os seus muros se restaurarem, sucederá que não terás porção alguma deste lado do rio.'),
('acf','ed',4,17,'E o rei enviou esta resposta a Reum, o chanceler, e a Sinsai, o escrivão, e aos demais seus companheiros, que habitavam em Samaria; como também aos demais que estavam dalém do rio: Paz! em tal tempo.'),
('acf','ed',4,18,'A carta que nos enviastes foi explicitamente lida diante de mim.'),
('acf','ed',4,19,'E, ordenando-o eu, buscaram e acharam, que de tempos antigos aquela cidade se levantou contra os reis, e nela se têm feito rebelião e sedição.'),
('acf','ed',4,20,'Também houve reis poderosos sobre Jerusalém que dalém do rio dominaram em todo o lugar, e se lhes pagaram direitos, tributos e pedágios.'),
('acf','ed',4,21,'Agora, pois, dai ordem para impedirdes aqueles homens, a fim de que não se edifique aquela cidade, até que eu dê uma ordem.'),
('acf','ed',4,22,'E guardai-vos de serdes remissos nisto; por que cresceria o dano para prejuízo dos reis?'),
('acf','ed',4,23,'Então, depois que a cópia da carta do rei Artaxerxes foi lida perante Reum, e Sinsai, o escrivão, e seus companheiros, apressadamente foram eles a Jerusalém, aos judeus, e os impediram à força e com violência.'),
('acf','ed',4,24,'Então cessou a obra da casa de Deus, que estava em Jerusalém; e cessou até ao ano segundo do reinado de Dario, rei da Pérsia.'),
('acf','ed',5,1,'E os profetas Ageu e Zacarias, filho de Ido, profetizaram aos judeus que estavam em Judá, e em Jerusalém; em nome do Deus de Israel lhes profetizaram.'),
('acf','ed',5,2,'Então se levantaram Zorobabel, filho de Sealtiel, e Jesuá, filho de Jozadaque, e começaram a edificar a casa de Deus, que está em Jerusalém; e com eles os profetas de Deus, que os ajudavam.'),
('acf','ed',5,3,'Naquele tempo vieram a eles Tatenai, governador dalém do rio, e Setar-Bozenai, e os seus companheiros, e disseram-lhes assim: Quem vos deu ordem para reedificardes esta casa, e restaurardes este muro?'),
('acf','ed',5,4,'Disseram-lhes, mais: E quais são os nomes dos homens que construíram este edifício?'),
('acf','ed',5,5,'Porém os olhos de Deus estavam sobre os anciãos dos judeus, e não os impediram, até que o negócio chegasse a Dario, e viesse resposta por carta sobre isso.'),
('acf','ed',5,6,'Cópia da carta que Tatenai, o governador dalém do rio, com Setar-Bozenai e os seus companheiros, os afarsaquitas, que estavam dalém do rio, enviaram ao rei Dario.'),
('acf','ed',5,7,'Enviaram-lhe uma carta, na qual estava escrito: Toda a paz ao rei Dario.'),
('acf','ed',5,8,'Seja notório ao rei, que nós fomos à província de Judá, à casa do grande Deus, a qual se edifica com grandes pedras, e a madeira já está sendo posta nas paredes; e esta obra vai sendo feita com diligência, e se adianta em suas mãos.'),
('acf','ed',5,9,'Então perguntamos aos anciãos, e assim lhes dissemos: Quem vos deu ordem para reedificardes esta casa, e restaurardes este muro?'),
('acf','ed',5,10,'Além disso, lhes perguntamos também pelos seus nomes, para tos declararmos; para que te pudéssemos escrever os nomes dos homens que entre eles são os chefes.'),
('acf','ed',5,11,'E esta foi a resposta que nos deram: Nós somos servos do Deus dos céus e da terra, e reedificamos a casa que há muitos anos foi edificada; porque um grande rei de Israel a edificou e a terminou.'),
('acf','ed',5,12,'Mas depois que nossos pais provocaram à ira o Deus dos céus, ele os entregou nas mãos de Nabucodonosor, rei de babilônia, o caldeu, o qual destruiu esta casa, e transportou o povo para babilônia.'),
('acf','ed',5,13,'Porém, no primeiro ano de Ciro, rei de babilônia, o rei Ciro deu ordem para que esta casa de Deus se reedificasse.'),
('acf','ed',5,14,'E até os utensílios de ouro e prata, da casa de Deus, que Nabucodonosor tomou do templo que estava em Jerusalém e os levou para o templo de babilônia, o rei Ciro os tirou do templo de babilônia, e foram dados a um homem cujo nome era Sesbazar, a quem nomeou governador.'),
('acf','ed',5,15,'E disse-lhe: Toma estes utensílios, vai e leva-os ao templo que está em Jerusalém, e faze reedificar a casa de Deus, no seu lugar.'),
('acf','ed',5,16,'Então veio este Sesbazar, e pôs os fundamentos da casa de Deus, que está em Jerusalém, e desde então para cá se está reedificando, e ainda não está acabada.'),
('acf','ed',5,17,'Agora, pois, se parece bem ao rei, busque-se na casa dos tesouros do rei, que está em babilônia, se é verdade que se deu uma ordem pelo rei Ciro para reedificar esta casa de Deus em Jerusalém; e sobre isto nos faça saber a vontade do rei.'),
('acf','ed',6,1,'Então o rei Dario deu ordem, e buscaram nos arquivos, onde se guardavam os tesouros em babilônia.'),
('acf','ed',6,2,'E em Acmeta, no palácio, que está na província de Média, se achou um rolo, e nele estava escrito um memorial que dizia assim:'),
('acf','ed',6,3,'No primeiro ano do rei Ciro, este baixou o seguinte decreto: A casa de Deus, em Jerusalém, se reedificará para lugar em que se ofereçam sacrifícios, e seus fundamentos serão firmes; a sua altura de sessenta côvados, e a sua largura de sessenta côvados;'),
('acf','ed',6,4,'Com três carreiras de grandes pedras, e uma carreira de madeira nova; e a despesa se fará da casa do rei.'),
('acf','ed',6,5,'Além disso, os utensílios de ouro e de prata da casa de Deus, que Nabucodonosor transportou do templo que estava em Jerusalém, e levou para babilônia, serão restituídos, para que voltem ao seu lugar, ao templo que está em Jerusalém, e serão postos na casa de Deus.'),
('acf','ed',6,6,'Agora, pois, Tatenai, governador dalém do rio, Setar-Bozenai, e os seus companheiros, os afarsaquitas, que habitais dalém do rio, apartai-vos dali.'),
('acf','ed',6,7,'Deixai que se faça a obra desta casa de Deus; que o governador dos judeus e os seus anciãos reedifiquem esta casa de Deus no seu lugar.'),
('acf','ed',6,8,'Também por mim se decreta o que haveis de fazer com os anciãos dos judeus, para a reedificação desta casa de Deus, a saber: que da fazenda do rei, dos tributos dalém do rio se pague prontamente a despesa a estes homens, para que não interrompam a obra.'),
('acf','ed',6,9,'E o que for necessário, como bezerros, carneiros, e cordeiros, para holocaustos ao Deus dos céus, trigo, sal, vinho e azeite, segundo o rito dos sacerdotes que estão em Jerusalém, dê-se-lhes, de dia em dia, para que não haja falta.'),
('acf','ed',6,10,'Para que ofereçam sacrifícios de cheiro suave ao Deus dos céus, e orem pela vida do rei e de seus filhos.'),
('acf','ed',6,11,'Também por mim se decreta que todo o homem que mudar este decreto, se arrancará um madeiro da sua casa, e, levantado, o pendurarão nele, e da sua casa se fará por isso um monturo.'),
('acf','ed',6,12,'O Deus, pois, que fez habitar ali o seu nome derrube a todos os reis e povos que estenderem a sua mão para mudar o decreto e para destruir esta casa de Deus, que está em Jerusalém. Eu, Dario, baixei o decreto; com diligência se faça.'),
('acf','ed',6,13,'Então Tatenai, o governador dalém do rio, Setar-Bozenai e os seus companheiros, assim fizeram diligentemente, conforme ao que decretara o rei Dario.'),
('acf','ed',6,14,'E os anciãos dos judeus iam edificando e prosperando pela profecia do profeta Ageu, e de Zacarias, filho de Ido. E edificaram e terminaram a obra conforme ao mandado do Deus de Israel, e conforme ao decreto de Ciro e Dario, e de Artaxerxes, rei da Pérsia.'),
('acf','ed',6,15,'E acabou-se esta casa no terceiro dia do mês de Adar, no sexto ano do reinado do rei Dario.'),
('acf','ed',6,16,'E os filhos de Israel, os sacerdotes, os levitas, e o restante dos filhos do cativeiro, fizeram a dedicação desta casa de Deus com alegria.'),
('acf','ed',6,17,'E ofereceram para a dedicação desta casa de Deus cem novilhos, duzentos carneiros, quatrocentos cordeiros, e doze cabritos por expiação do pecado de todo o Israel; segundo o número das tribos de Israel.'),
('acf','ed',6,18,'E puseram os sacerdotes nas suas turmas e os levitas nas suas divisões, para o ministério de Deus, em Jerusalém, conforme ao que está escrito no livro de Moisés.'),
('acf','ed',6,19,'E os filhos do cativeiro celebraram a páscoa no dia catorze do primeiro mês.'),
('acf','ed',6,20,'Porque os sacerdotes e levitas se purificaram como se fossem um só homem, todos estavam limpos; e mataram o cordeiro da páscoa para todos os filhos do cativeiro, e para seus irmãos, os sacerdotes, e para si mesmos.'),
('acf','ed',6,21,'Assim comeram a páscoa os filhos de Israel que tinham voltado do cativeiro, com todos os que com eles se apartaram da imundícia dos gentios da terra, para buscarem o Senhor Deus de Israel;'),
('acf','ed',6,22,'E celebraram a festa dos pães ázimos por sete dias com alegria; porque o Senhor os tinha alegrado, e tinha mudado o coração do rei da Assíria a favor deles, para lhes fortalecer as mãos na obra da casa de Deus, o Deus de Israel.'),
('acf','ed',7,1,'E passadas estas coisas no reinado de Artaxerxes, rei da Pérsia, Esdras, filho de Seraías, filho de Azarias, filho de Hilquias,'),
('acf','ed',7,2,'Filho de Salum, filho de Zadoque, filho de Aitube,'),
('acf','ed',7,3,'Filho de Amarias, filho de Azarias, filho de Meraiote,'),
('acf','ed',7,4,'Filho de Zeraquias, filho de Uzi, filho de Buqui,'),
('acf','ed',7,5,'Filho de Abisua, filho de Finéias, filho de Eleazar, filho de Arão, o sumo sacerdote;'),
('acf','ed',7,6,'Este Esdras subiu de babilônia; e era escriba hábil na lei de Moisés, que o SENHOR Deus de Israel tinha dado; e, segundo a mão do SENHOR seu Deus, que estava sobre ele, o rei lhe deu tudo quanto lhe pedira.'),
('acf','ed',7,7,'Também subiram a Jerusalém alguns dos filhos de Israel, dos sacerdotes, dos levitas, dos cantores, dos porteiros e dos servidores do templo, no sétimo ano do rei Artaxerxes.'),
('acf','ed',7,8,'E no quinto mês chegou a Jerusalém, no sétimo ano deste rei.'),
('acf','ed',7,9,'Pois no primeiro dia do primeiro mês foi o princípio da partida de babilônia; e no primeiro dia do quinto mês chegou a Jerusalém, segundo a boa mão do seu Deus sobre ele.'),
('acf','ed',7,10,'Porque Esdras tinha preparado o seu coração para buscar a lei do Senhor e para cumpri-la e para ensinar em Israel os seus estatutos e os seus juízos.'),
('acf','ed',7,11,'Esta é, pois, a cópia da carta que o rei Artaxerxes deu ao sacerdote Esdras, o escriba das palavras dos mandamentos do Senhor, e dos seus estatutos sobre Israel:'),
('acf','ed',7,12,'Artaxerxes, rei dos reis, ao sacerdote Esdras, escriba da lei do Deus do céu, paz perfeita, em tal tempo.'),
('acf','ed',7,13,'Por mim se decreta que no meu reino todo aquele do povo de Israel, e dos seus sacerdotes e levitas, que quiser ir contigo a Jerusalém, vá.'),
('acf','ed',7,14,'Porquanto és enviado da parte do rei e dos seus sete conselheiros para fazeres inquirição a respeito de Judá e de Jerusalém, conforme à lei do teu Deus, que está na tua mão;'),
('acf','ed',7,15,'E para levares a prata e o ouro que o rei e os seus conselheiros voluntariamente deram ao Deus de Israel, cuja habitação está em Jerusalém;'),
('acf','ed',7,16,'E toda a prata e o ouro que achares em toda a província de babilônia, com as ofertas voluntárias do povo e dos sacerdotes, que voluntariamente oferecerem, para a casa de seu Deus, que está em Jerusalém.'),
('acf','ed',7,17,'Portanto diligentemente comprarás com este dinheiro novilhos, carneiros, cordeiros, com as suas ofertas de alimentos, e as suas libações, e as oferecerás sobre o altar da casa de vosso Deus, que está em Jerusalém.'),
('acf','ed',7,18,'Também o que a ti e a teus irmãos bem parecer fazerdes do restante da prata e do ouro, o fareis conforme a vontade do vosso Deus.'),
('acf','ed',7,19,'E os utensílios que te foram dados para o serviço da casa de teu Deus, restitui-os perante o Deus de Jerusalém.'),
('acf','ed',7,20,'E tudo mais que for necessário para a casa de teu Deus, que te convenha dar, dá-lo-ás da casa dos tesouros do rei.'),
('acf','ed',7,21,'E por mim mesmo, o rei Artaxerxes, se decreta a todos os tesoureiros que estão dalém do rio que tudo quanto vos pedir o sacerdote Esdras, escriba da lei do Deus dos céus, prontamente se faça.'),
('acf','ed',7,22,'Até cem talentos de prata, e até cem coros de trigo, e até cem batos de vinho, e até cem batos de azeite; e sal à vontade.'),
('acf','ed',7,23,'Tudo quanto se ordenar, segundo o mandado do Deus do céu, prontamente se faça para a casa do Deus dos céus; pois, para que haveria grande ira sobre o reino do rei e de seus filhos?'),
('acf','ed',7,24,'Também vos fazemos saber acerca de todos os sacerdotes e levitas, cantores, porteiros, servidores do templo e ministros desta casa de Deus, que não será lícito impor-lhes, nem tributo, nem contribuição, nem renda.'),
('acf','ed',7,25,'E tu, Esdras, conforme a sabedoria do teu Deus, que possues, nomeia magistrados e juízes, que julguem a todo o povo que está dalém do rio, a todos os que sabem as leis do teu Deus; e ao que não as sabe, lhe ensinarás.'),
('acf','ed',7,26,'E todo aquele que não observar a lei do teu Deus e a lei do rei, seja julgado prontamente; quer seja morte, quer desterro, quer multa sobre os seus bens, quer prisão.'),
('acf','ed',7,27,'Bendito seja o Senhor Deus de nossos pais, que tal inspirou ao coração do rei, para ornar a casa do Senhor, que está em Jerusalém.'),
('acf','ed',7,28,'E que estendeu para mim a sua benignidade perante o rei e os seus conselheiros e todos os príncipes poderosos do rei. Assim me animei, segundo a mão do Senhor meu Deus sobre mim, e ajuntei dentre Israel alguns chefes para subirem comigo.'),
('acf','ed',8,1,'Estes, pois, são os chefes das casas paternas e esta a genealogia dos que subiram comigo de babilônia no reinado do rei Artaxerxes:'),
('acf','ed',8,2,'Dos filhos de Finéias, Gérson; dos filhos de Itamar, Daniel; dos filhos de Davi, Hatus;'),
('acf','ed',8,3,'Dos filhos de Secanias, e dos filhos de Parós, Zacarias, e com ele, segundo a genealogia, se contaram até cento e cinqüenta homens.'),
('acf','ed',8,4,'Dos filhos de Paate-Moabe, Elioenai, filho de Zacarias, e com ele duzentos homens.'),
('acf','ed',8,5,'Dos filhos de Secanias, o filho de Jeaziel, e com ele trezentos homens.'),
('acf','ed',8,6,'E dos filhos de Adim, Ebede, filho de Jônatas, e com ele cinqüenta homens.'),
('acf','ed',8,7,'E dos filhos de Elão, Jesaías, filho de Atalias, e com ele setenta homens.'),
('acf','ed',8,8,'E dos filhos de Sefatias, Zebadias, filho de Micael, e com ele oitenta homens.'),
('acf','ed',8,9,'Dos filhos de Joabe, Obadias, filho de Jeiel, e com ele duzentos e dezoito homens.'),
('acf','ed',8,10,'E dos filhos de Selomite, o filho de Josifias, e com ele cento e sessenta homens.'),
('acf','ed',8,11,'E dos filhos de Bebai, Zacarias, o filho de Bebai, e com ele vinte e oito homens.'),
('acf','ed',8,12,'E dos filhos de Azgade, Joanã, o filho de Hacatã, e com ele cento e dez homens.'),
('acf','ed',8,13,'E dos últimos filhos de Adonicão, cujos nomes eram estes: Elifelete, Jeiel e Semaías, e com eles sessenta homens.'),
('acf','ed',8,14,'E dos filhos de Bigvai, Utai e Zabude, e com eles setenta homens.'),
('acf','ed',8,15,'E ajuntei-os perto do rio que vai a Aava, e ficamos ali acampados três dias. Então atentei para o povo e para os sacerdotes, e não achei ali nenhum dos filhos de Levi.'),
('acf','ed',8,16,'Enviei, pois, Eliezer, Ariel, Semaías, Elnatã, Jaribe, Elnatã, Natã, Zacarias e Mesulão, os chefes; como também a Joiaribe, e a Elnatã, que eram entendidos.'),
('acf','ed',8,17,'E enviei-os com mandado a Ido, chefe em Casifia; e falei a eles o que deveriam dizer a Ido e aos seus irmãos, servidores do templo, em Casifia, que nos trouxessem ministros para a casa do nosso Deus.'),
('acf','ed',8,18,'E trouxeram-nos, segundo a boa mão de Deus sobre nós, um homem entendido, dos filhos de Mali, filho de Levi, filho de Israel, a saber: Serebias, com os seus filhos e irmãos, dezoito;'),
('acf','ed',8,19,'E a Hasabias, e com ele Jesaías, dos filhos de Merari, com seus irmãos e os filhos deles, vinte;'),
('acf','ed',8,20,'E dos servidores do templo que Davi e os príncipes deram para o ministério dos levitas, duzentos e vinte servidores do templo; que foram todos mencionados por seus nomes.'),
('acf','ed',8,21,'Então apregoei ali um jejum junto ao rio Aava, para nos humilharmos diante da face de nosso Deus, para lhe pedirmos caminho seguro para nós, para nossos filhos e para todos os nossos bens.'),
('acf','ed',8,22,'Porque tive vergonha de pedir ao rei exército e cavaleiros para nos defenderem do inimigo pelo caminho; porquanto tínhamos falado ao rei, dizendo: A mão do nosso Deus é sobre todos os que o buscam, para o bem deles; mas o seu poder e a sua ira contra todos os que o deixam.'),
('acf','ed',8,23,'Nós, pois, jejuamos, e pedimos isto ao nosso Deus, e moveu-se pelas nossas orações.'),
('acf','ed',8,24,'Então separei doze dos chefes dos sacerdotes: Serebias, Hasabias, e com eles dez dos seus irmãos.'),
('acf','ed',8,25,'E pesei-lhes a prata, o ouro e os vasos; que eram a oferta para a casa de nosso Deus, que ofereceram o rei, os seus conselheiros, os seus príncipes e todo o Israel que ali se achou.'),
('acf','ed',8,26,'E pesei em suas mãos seiscentos e cinqüenta talentos de prata, e em vasos de prata cem talentos, e cem talentos de ouro,'),
('acf','ed',8,27,'E vinte bacias de ouro, de mil dracmas, e dois vasos de bom metal lustroso, tão precioso como ouro.'),
('acf','ed',8,28,'E disse-lhes: Vós sois santos ao Senhor, e são santos estes utensílios, como também esta prata e este ouro, oferta voluntária, oferecida ao Senhor Deus de vossos pais.'),
('acf','ed',8,29,'Vigiai, pois, e guardai-os até que os peseis na presença dos chefes dos sacerdotes e dos levitas, e dos chefes dos pais de Israel, em Jerusalém, nas câmaras da casa do Senhor.'),
('acf','ed',8,30,'Então os sacerdotes e os levitas receberam o peso da prata, do ouro e dos utensílios, para os trazerem a Jerusalém, à casa de nosso Deus.'),
('acf','ed',8,31,'E partimos do rio Aava, no dia doze do primeiro mês, para irmos a Jerusalém; e a mão do nosso Deus estava sobre nós, e livrou-nos da mão dos inimigos, e dos que nos armavam ciladas pelo caminho.'),
('acf','ed',8,32,'E chegamos a Jerusalém, e repousamos ali três dias.'),
('acf','ed',8,33,'E no quarto dia se pesou a prata, o ouro e os utensílios, na casa do nosso Deus, por mão de Meremote, filho do sacerdote Urias; e com ele Eleazar, filho de Finéias, e com eles Jozabade, filho de Jesuá, e Noadias, filho de Binui, levitas.'),
('acf','ed',8,34,'Tudo foi contado e pesado; e todo o peso foi registrado na mesma ocasião.'),
('acf','ed',8,35,'E os exilados, que vieram do cativeiro, ofereceram holocaustos ao Deus de Israel: doze novilhos por todo o Israel, noventa e seis carneiros, setenta e sete cordeiros, e doze bodes em sacrifício pelo pecado; tudo em holocausto ao Senhor.'),
('acf','ed',8,36,'Então deram as ordens do rei aos seus sátrapas, e aos governadores dalém do rio; e estes ajudaram o povo e a casa de Deus.'),
('acf','ed',9,1,'Acabadas, pois, estas coisas, chegaram-se a mim os príncipes, dizendo: O povo de Israel, os sacerdotes e os levitas, não se têm separado dos povos destas terras, seguindo as abominações dos cananeus, dos heteus, dos perizeus, dos jebuseus, dos amonitas, dos moabitas, dos egípcios, e dos amorreus.'),
('acf','ed',9,2,'Porque tomaram das suas filhas para si e para seus filhos, e assim se misturou a linhagem santa com os povos dessas terras; e até os príncipes e magistrados foram os primeiros nesta transgressão.'),
('acf','ed',9,3,'E, ouvindo eu tal coisa, rasguei as minhas vestes e o meu manto, e arranquei os cabelos da minha cabeça e da minha barba, e sentei-me atônito.'),
('acf','ed',9,4,'Então se ajuntaram a mim todos os que tremiam das palavras do Deus de Israel por causa da transgressão dos do cativeiro; porém eu permaneci sentado atônito até ao sacrifício da tarde.'),
('acf','ed',9,5,'E perto do sacrifício da tarde me levantei da minha aflição, havendo já rasgado as minhas vestes e o meu manto, e me pus de joelhos, e estendi as minhas mãos para o Senhor meu Deus;'),
('acf','ed',9,6,'E disse: Meu Deus! Estou confuso e envergonhado, para levantar a ti a minha face, meu Deus; porque as nossas iniqüidades se multiplicaram sobre a nossa cabeça, e a nossa culpa tem crescido até aos céus.'),
('acf','ed',9,7,'Desde os dias de nossos pais até ao dia de hoje estamos em grande culpa, e por causa das nossas iniqüidades somos entregues, nós e nossos reis e os nossos sacerdotes, na mão dos reis das terras, à espada, ao cativeiro, e ao roubo, e à confusão do rosto, como hoje se vê.'),
('acf','ed',9,8,'E agora, por um pequeno momento, se manifestou a graça da parte do Senhor, nosso Deus, para nos deixar alguns que escapem, e para dar-nos uma estaca no seu santo lugar; para nos iluminar os olhos, ó Deus nosso, e para nos dar um pouco de vida na nossa servidão.'),
('acf','ed',9,9,'Porque somos servos; porém na nossa servidão não nos desamparou o nosso Deus; antes estendeu sobre nós a sua benignidade perante os reis da Pérsia, para que nos desse vida, para levantarmos a casa do nosso Deus, e para restaurarmos as suas assolações; e para que nos desse uma parede de proteção em Judá e em Jerusalém.'),
('acf','ed',9,10,'Agora, pois, ó nosso Deus, que diremos depois disto? Pois deixamos os teus mandamentos,'),
('acf','ed',9,11,'Os quais mandaste pelo ministério de teus servos, os profetas, dizendo: A terra em que entrais para a possuir, terra imunda é pelas imundícias dos povos das terras, pelas suas abominações com que, na sua corrupção a encheram, de uma extremidade à outra.'),
('acf','ed',9,12,'Agora, pois, vossas filhas não dareis a seus filhos, e suas filhas não tomareis para vossos filhos, e nunca procurareis a sua paz e o seu bem; para que sejais fortes, e comais o bem da terra, e a deixeis por herança a vossos filhos para sempre.'),
('acf','ed',9,13,'E depois de tudo o que nos tem sucedido por causa das nossas más obras, e da nossa grande culpa, porquanto tu, ó nosso Deus, impediste que fôssemos destruídos, por causa da nossa iniqüidade, e ainda nos deste um remanescente como este;'),
('acf','ed',9,14,'Tornaremos, pois, agora a violar os teus mandamentos e a aparentar-nos com os povos destas abominações? Não te indignarias tu assim contra nós até de todo nos consumir, até que não ficasse remanescente nem quem escapasse?'),
('acf','ed',9,15,'Ah! Senhor Deus de Israel, justo és, pois ficamos qual um remanescente que escapou, como hoje se vê; eis que estamos diante de ti, na nossa culpa, porque ninguém há que possa estar na tua presença, por causa disto.'),
('acf','ed',10,1,'E enquanto Esdras orava, e fazia confissão, chorando e prostrando-se diante da casa de Deus, ajuntou-se a ele, de Israel, uma grande congregação de homens, mulheres e crianças; pois o povo chorava com grande choro.'),
('acf','ed',10,2,'Então Secanias, filho de Jeiel, um dos filhos de Elão, tomou a palavra e disse a Esdras: Nós temos transgredido contra o nosso Deus, e casamos com mulheres estrangeiras dentre os povos da terra, mas, no tocante a isto, ainda há esperança para Israel.'),
('acf','ed',10,3,'Agora, pois, façamos aliança com o nosso Deus de que despediremos todas as mulheres, e os que delas são nascidos, conforme ao conselho do meu senhor, e dos que tremem ao mandado do nosso Deus; e faça-se conforme a lei.'),
('acf','ed',10,4,'Levanta-te, pois, porque te pertence este negócio, e nós seremos contigo; esforça-te, e age.'),
('acf','ed',10,5,'Então Esdras se levantou, e ajuramentou os chefes dos sacerdotes e dos levitas, e a todo o Israel, de que fariam conforme a esta palavra; e eles juraram.'),
('acf','ed',10,6,'E Esdras se levantou de diante da casa de Deus, e entrou na câmara de Joanã, filho de Eliasibe; e, chegando lá, não comeu pão, e nem bebeu água; porque lamentava pela transgressão dos do cativeiro.'),
('acf','ed',10,7,'E fizeram passar pregão por Judá e Jerusalém, a todos os que vieram do cativeiro, para que se ajuntassem em Jerusalém.'),
('acf','ed',10,8,'E que todo aquele que em três dias não viesse, segundo o conselho dos príncipes e dos anciãos, toda a sua fazenda se poria em interdito, e ele seria separado da congregação dos do cativeiro.'),
('acf','ed',10,9,'Então todos os homens de Judá e Benjamim em três dias se ajuntaram em Jerusalém; era o nono mês, aos vinte dias do mês; e todo o povo se assentou na praça da casa de Deus, tremendo por este negócio e por causa das grandes chuvas.'),
('acf','ed',10,10,'Então se levantou Esdras, o sacerdote, e disse-lhes: Vós tendes transgredido, e casastes com mulheres estrangeiras, aumentando a culpa de Israel.'),
('acf','ed',10,11,'Agora, pois, fazei confissão ao Senhor Deus de vossos pais, e fazei a sua vontade; e apartai-vos dos povos das terras, e das mulheres estrangeiras.'),
('acf','ed',10,12,'E respondeu toda a congregação, e disse em altas vozes: Assim seja, conforme às tuas palavras nos convém fazer.'),
('acf','ed',10,13,'Porém o povo é muito, e também é tempo de grandes chuvas, e não se pode estar aqui fora; nem é obra de um dia nem de dois, porque somos muitos os que transgredimos neste negócio.'),
('acf','ed',10,14,'Ora, ponham-se os nossos líderes, por toda a congregação sobre este negócio; e todos os que em nossas cidades casaram com mulheres estrangeiras venham em tempos apontados, e com eles os anciãos de cada cidade, e os seus juízes, até que desviemos de nós o ardor da ira do nosso Deus, por esta causa.'),
('acf','ed',10,15,'Porém, somente Jônatas, filho de Asael, e Jaseías, filho de Ticva, se opuseram a isto; e Mesulão, e Sabetai, levita, os ajudaram.'),
('acf','ed',10,16,'E assim o fizeram os que voltaram do cativeiro; e o sacerdote Esdras e os homens, chefes dos pais, segundo a casa de seus pais, e todos pelos seus nomes, foram apontados; e assentaram-se no primeiro dia do décimo mês, para inquirirem neste negócio.'),
('acf','ed',10,17,'E no primeiro dia do primeiro mês acabaram de tratar com todos os homens que casaram com mulheres estrangeiras.'),
('acf','ed',10,18,'E acharam-se dos filhos dos sacerdotes que casaram com mulheres estrangeiras: Dos filhos de Jesuá, filho de Jozadaque, e seus irmãos, Maaséias, e Eliezer, e Jaribe, e Gedalias.'),
('acf','ed',10,19,'E deram as suas mãos prometendo que despediriam suas mulheres; e, achando-se culpados, ofereceram um carneiro do rebanho pelo seu delito.'),
('acf','ed',10,20,'E dos filhos de Imer: Hanani e Zebadias.'),
('acf','ed',10,21,'E dos filhos de Harim: Maaséias, Elias, Semaías, Jeiel e Uzias.'),
('acf','ed',10,22,'E dos filhos de Pasur: Elioenai, Maaséias, Ismael, Netanel, Jozabade e Eleasa.'),
('acf','ed',10,23,'E dos levitas: Jozabade, Simei, Quelaías (este é Quelita), Petaías, Judá e Eliezer.'),
('acf','ed',10,24,'E dos cantores: Eliasibe; e dos porteiros: Salum, Telém e Uri.'),
('acf','ed',10,25,'E de Israel, dos filhos de Parós: Ramias, Jezias, Malquias, Miamim, Eleazar, Malquias e Benaia.'),
('acf','ed',10,26,'E dos filhos de Elão: Matanias, Zacarias, Jeiel, Abdi, Jeremote e Elias.'),
('acf','ed',10,27,'E dos filhos de Zatu: Elioenai, Eliasibe, Matanias, Jeremote, Zabade e Aziza.'),
('acf','ed',10,28,'E dos filhos de Bebai: Joanã, Hananias, Zabai e Atlai.'),
('acf','ed',10,29,'E dos filhos de Bani: Mesulão, Maluque, Adaías, Jasube, Seal, Jeremote.'),
('acf','ed',10,30,'E dos filhos de Paate-Moabe: Adna, Quelal, Benaia, Maséias, Matanias, Bezalel, Binui e Manassés.'),
('acf','ed',10,31,'E dos filhos de Harim: Eliezer, Josias, Malquias, Semaías, Simeão,'),
('acf','ed',10,32,'Benjamim, Maluque, Semarias.'),
('acf','ed',10,33,'Dos filhos de Hasum: Matenai, Matatá, Zabade, Elifelete, Jeremai, Manassés e Simei.'),
('acf','ed',10,34,'Dos filhos de Bani: Maadai, Anrão, e Uel,'),
('acf','ed',10,35,'Benaia, Bedias, Queluí,'),
('acf','ed',10,36,'Vanias, Meremote, Eliasibe,'),
('acf','ed',10,37,'Matanias, Matnai e Jaasai,'),
('acf','ed',10,38,'E Bani, Binui, Simei,'),
('acf','ed',10,39,'E Selemias, Natã e Adaías,'),
('acf','ed',10,40,'Macnadbai, Sasai, Sarai,'),
('acf','ed',10,41,'Azareel, Selemias, Semarias,'),
('acf','ed',10,42,'Salum, Amarias e José.'),
('acf','ed',10,43,'Dos filhos de Nebo: Jeiel, Matitias, Zabade, Zebina, Jadai, Joel e Benaia.'),
('acf','ed',10,44,'Todos estes tomaram mulheres estrangeiras; e alguns deles tinham mulheres de quem tiveram filhos.')
insert into public.bible_verses (version, book_abbrev, chapter, verse, text) values
('acf','ne',1,1,'As palavras de Neemias, filho de Hacalias. E sucedeu no mês de Quislev, no ano vigésimo, estando eu em Susã, a fortaleza,'),
('acf','ne',1,2,'Que veio Hanani, um de meus irmãos, ele e alguns de Judá; e perguntei-lhes pelos judeus que escaparam, e que restaram do cativeiro, e acerca de Jerusalém.'),
('acf','ne',1,3,'E disseram-me: Os restantes, que ficaram do cativeiro, lá na província estão em grande miséria e desprezo; e o muro de Jerusalém fendido e as suas portas queimadas a fogo.'),
('acf','ne',1,4,'E sucedeu que, ouvindo eu estas palavras, assentei-me e chorei, e lamentei por alguns dias; e estive jejuando e orando perante o Deus dos céus.'),
('acf','ne',1,5,'E disse: Ah! Senhor Deus dos céus, Deus grande e terrível! Que guarda a aliança e a benignidade para com aqueles que o amam e guardam os seus mandamentos;'),
('acf','ne',1,6,'Estejam, pois, atentos os teus ouvidos e os teus olhos abertos, para ouvires a oração do teu servo, que eu hoje faço perante ti, dia e noite, pelos filhos de Israel, teus servos; e faço confissão pelos pecados dos filhos de Israel, que temos cometido contra ti; também eu e a casa de meu pai temos pecado.'),
('acf','ne',1,7,'De todo nos corrompemos contra ti, e não guardamos os mandamentos, nem os estatutos, nem os juízos, que ordenaste a Moisés, teu servo.'),
('acf','ne',1,8,'Lembra-te, pois, da palavra que ordenaste a Moisés, teu servo, dizendo: Vós transgredireis, e eu vos espalharei entre os povos.'),
('acf','ne',1,9,'E vós vos convertereis a mim, e guardareis os meus mandamentos, e os cumprireis; então, ainda que os vossos rejeitados estejam na extremidade do céu, de lá os ajuntarei e os trarei ao lugar que tenho escolhido para ali fazer habitar o meu nome.'),
('acf','ne',1,10,'Eles são teus servos e o teu povo que resgataste com a tua grande força e com a tua forte mão.'),
('acf','ne',1,11,'Ah! Senhor, estejam, pois, atentos os teus ouvidos à oração do teu servo, e à oração dos teus servos que desejam temer o teu nome; e faze prosperar hoje o teu servo, e dá-lhe graça perante este homem. Então era eu copeiro do rei.'),
('acf','ne',2,1,'Sucedeu, pois, no mês de Nisã, no ano vigésimo do rei Artaxerxes, que estava posto vinho diante dele, e eu peguei o vinho e o dei ao rei; porém eu nunca estivera triste diante dele.'),
('acf','ne',2,2,'E o rei me disse: Por que está triste o teu rosto, pois não estás doente? Não é isto senão tristeza de coração; então temi sobremaneira.'),
('acf','ne',2,3,'E disse ao rei: Viva o rei para sempre! Como não estaria triste o meu rosto, estando a cidade, o lugar dos sepulcros de meus pais, assolada, e tendo sido consumidas as suas portas a fogo?'),
('acf','ne',2,4,'E o rei me disse: Que me pedes agora? Então orei ao Deus dos céus,'),
('acf','ne',2,5,'E disse ao rei: Se é do agrado do rei, e se o teu servo é aceito em tua presença, peço-te que me envies a Judá, à cidade dos sepulcros de meus pais, para que eu a reedifique.'),
('acf','ne',2,6,'Então o rei me disse, estando a rainha assentada junto a ele: Quanto durará a tua viagem, e quando voltarás? E aprouve ao rei enviar-me, apontando-lhe eu um certo tempo.'),
('acf','ne',2,7,'Disse mais ao rei: Se ao rei parece bem, dêem-se-me cartas para os governadores dalém do rio, para que me permitam passar até que chegue a Judá.'),
('acf','ne',2,8,'Como também uma carta para Asafe, guarda da floresta do rei, para que me dê madeira para cobrir as portas do paço da casa, para o muro da cidade e para a casa em que eu houver de entrar. E o rei mas deu, segundo a boa mão de Deus sobre mim.'),
('acf','ne',2,9,'Então fui aos governadores dalém do rio, e dei-lhes as cartas do rei; e o rei tinha enviado comigo capitàes do exército e cavaleiros.'),
('acf','ne',2,10,'O que ouvindo Sambalate, o horonita, e Tobias, o servo amonita, lhes desagradou extremamente que alguém viesse a procurar o bem dos filhos de Israel.'),
('acf','ne',2,11,'E cheguei a Jerusalém, e estive ali três dias.'),
('acf','ne',2,12,'E de noite me levantei, eu e poucos homens comigo, e não declarei a ninguém o que o meu Deus me pôs no coração para fazer em Jerusalém; e não havia comigo animal algum, senão aquele em que estava montado.'),
('acf','ne',2,13,'E de noite saí pela porta do vale, e para o lado da fonte do dragão, e para a porta do monturo, e contemplei os muros de Jerusalém, que estavam fendidos, e as suas portas, que tinham sido consumidas pelo fogo.'),
('acf','ne',2,14,'E passei à porta da fonte, e ao tanque do rei; e não havia lugar por onde pudesse passar o animal em que estava montado.'),
('acf','ne',2,15,'Ainda, de noite subi pelo ribeiro e contemplei o muro; e, virando entrei pela porta do vale; assim voltei.'),
('acf','ne',2,16,'E não souberam os magistrados aonde eu fora nem o que eu fazia; porque ainda nem aos judeus, nem aos sacerdotes, nem aos nobres, nem aos magistrados, nem aos mais que faziam a obra, até então tinha declarado coisa alguma.'),
('acf','ne',2,17,'Então lhes disse: Bem vedes vós a miséria em que estamos, que Jerusalém está assolada, e que as suas portas têm sido queimadas a fogo; vinde, pois, e reedifiquemos o muro de Jerusalém, e não sejamos mais um opróbrio.'),
('acf','ne',2,18,'Então lhes declarei como a mão do meu Deus me fora favorável, como também as palavras do rei, que ele me tinha dito; então disseram: Levantemo-nos, e edifiquemos. E esforçaram as suas mãos para o bem.'),
('acf','ne',2,19,'O que ouvindo Sambalate, o horonita, e Tobias, o servo amonita, e Gesém, o árabe, zombaram de nós, e desprezaram-nos, e disseram: Que é isto que fazeis? Quereis rebelar-vos contra o rei?'),
('acf','ne',2,20,'Então lhes respondi, e disse: O Deus dos céus é o que nos fará prosperar: e nós, seus servos, nos levantaremos e edificaremos; mas vós não tendes parte, nem justiça, nem memória em Jerusalém.'),
('acf','ne',3,1,'E levantou-se Eliasibe, o sumo sacerdote, com os seus irmãos, os sacerdotes, e reedificaram a porta do gado, a qual consagraram; e levantaram as suas portas, e até à torre de Meá consagraram, e até à torre de Hananel.'),
('acf','ne',3,2,'E junto a ele edificaram os homens de Jericó; também ao seu lado edificou Zacur, filho de Imri.'),
('acf','ne',3,3,'E à porta do peixe edificaram os filhos de Hassenaá; a qual emadeiraram, e levantaram as suas portas com as suas fechaduras e os seus ferrolhos.'),
('acf','ne',3,4,'E ao seu lado reparou Meremote, filho de Urias, o filho de Coz; e ao seu lado reparou Mesulão, filho de Berequias, o filho de Mesezabeel; e ao seu lado reparou Zadoque, filho de Baana.'),
('acf','ne',3,5,'E ao seu lado repararam os tecoítas; porém os seus nobres não submeteram a cerviz ao serviço de seu Senhor.'),
('acf','ne',3,6,'E a porta velha repararam-na Joiada, filho de Paséia, e Mesulão, filho de Besodias; estes a emadeiraram, e levantaram as suas portas com as suas fechaduras e os seus ferrolhos.'),
('acf','ne',3,7,'E ao seu lado repararam Melatias, o gibeonita, e Jadom, meronotita, homens de Gibeom e Mizpá, que pertenciam ao domínio do governador dalém do rio.'),
('acf','ne',3,8,'Ao seu lado reparou Uziel, filho de Haraías, um dos ourives; e ao seu lado reparou Hananias, filho de um dos boticários; e fortificaram a Jerusalém até ao muro largo.'),
('acf','ne',3,9,'E ao seu lado reparou Refaías, filho de Hur, líder da metade de Jerusalém.'),
('acf','ne',3,10,'E ao seu lado reparou Jedaías, filho de Harumafe, e defronte de sua casa e ao seu lado reparou Hatus, filho de Hasabnéias.'),
('acf','ne',3,11,'A outra porção reparou Malquias, filho de Harim, e Hasube, filho de Paate-Moabe; como também a torre dos fornos.'),
('acf','ne',3,12,'E ao seu lado reparou Salum, filho de Haloés, líder da outra meia parte de Jerusalém, ele e suas filhas.'),
('acf','ne',3,13,'A porta do vale reparou-a Hanum e os moradores de Zanoa; estes a edificaram, e lhe levantaram as portas com as suas fechaduras e os seus ferrolhos, como também mil côvados do muro, até a porta do monturo.'),
('acf','ne',3,14,'E a porta do monturo reparou-a Malquias, filho de Recabe, líder do distrito de Bete-Haquerém; este a edificou, e lhe levantou as portas com as suas fechaduras e os seus ferrolhos.'),
('acf','ne',3,15,'E a porta da fonte reparou-a Salum, filho de Col-Hoze, líder do distrito de Mizpá; este a edificou, e a cobriu, e lhe levantou as portas com as suas fechaduras e os seus ferrolhos, como também o muro do tanque de Hasselá, ao pé do jardim do rei, e até aos degraus que descem da cidade de Davi.'),
('acf','ne',3,16,'Depois dele edificou Neemias, filho de Azbuque, líder da metade de Bete-Zur, até defronte dos sepulcros de Davi, até ao tanque artificial e até à casa dos valentes.'),
('acf','ne',3,17,'Depois dele repararam os levitas, Reum, filho de Bani; ao seu lado reparou Hasabias, líder da metade de Queila, no seu distrito.'),
('acf','ne',3,18,'Depois dele repararam seus irmãos, Bavai, filho de Henadade, líder da outra meia parte de Queila.'),
('acf','ne',3,19,'Ao seu lado reparou Ezer, filho de Jesuá, líder de Mizpá, outra porção, defronte da subida à casa das armas, à esquina.'),
('acf','ne',3,20,'Depois dele reparou com grande ardor Baruque, filho de Zabai, outra medida, desde a esquina até à porta da casa de Eliasibe, o sumo sacerdote.'),
('acf','ne',3,21,'Depois dele reparou Meremote, filho de Urias, o filho de Coz, outra porção, desde a porta da casa de Eliasibe, até à extremidade da casa de Eliasibe.'),
('acf','ne',3,22,'E depois dele repararam os sacerdotes que habitavam na campina.'),
('acf','ne',3,23,'Depois reparou Benjamim e Hasube, defronte da sua casa; depois dele reparou Azarias, filho de Maaséias, o filho de Ananias, junto à sua casa.'),
('acf','ne',3,24,'Depois dele reparou Binui, filho de Henadade, outra porção, desde a casa de Azarias até à esquina, e até ao canto.'),
('acf','ne',3,25,'Palal, filho de Uzai, reparou defronte da esquina, e a torre que sai da casa real superior, que está junto ao pátio da prisão; depois dele Pedaías, filho de Parós.'),
('acf','ne',3,26,'E os servidores do templo que habitavam em Ofel, até defronte da porta das águas, para o oriente, e até à torre alta.'),
('acf','ne',3,27,'Depois repararam os tecoítas outra porção, defronte da torre grande e alta, e até ao muro de Ofel.'),
('acf','ne',3,28,'Desde acima da porta dos cavalos repararam os sacerdotes, cada um defronte da sua casa.'),
('acf','ne',3,29,'Depois deles reparou Zadoque, filho de Imer, defronte da sua casa; e depois dele reparou Semaías, filho de Secanias, guarda da porta oriental.'),
('acf','ne',3,30,'Depois dele reparou Hananias, filho de Selemias, e Hanum, filho de Zalafe, o sexto, outra porção; depois dele reparou Mesulão, filho de Berequias, defronte da sua câmara.'),
('acf','ne',3,31,'Depois dele reparou Malquias, filho de um ourives, até à casa dos servidores do templo e mercadores, defronte da porta de Mifcade, e até à câmara do canto.'),
('acf','ne',3,32,'E entre a câmara do canto e a porta do gado, repararam os ourives e os mercadores.'),
('acf','ne',4,1,'E sucedeu que, ouvindo Sambalate que edificávamos o muro, ardeu em ira, e se indignou muito; e escarneceu dos judeus.'),
('acf','ne',4,2,'E falou na presença de seus irmãos, e do exército de Samaria, e disse: Que fazem estes fracos judeus? Permitir-se-lhes-á isto? Sacrificarão? Acabá-lo-ão num só dia? Vivificarão dos montões do pó as pedras que foram queimadas?'),
('acf','ne',4,3,'E estava com ele Tobias, o amonita, e disse: Ainda que edifiquem, contudo, vindo uma raposa, derrubará facilmente o seu muro de pedra.'),
('acf','ne',4,4,'Ouve, ó nosso Deus, que somos tão desprezados, e torna o seu opróbrio sobre a sua cabeça, e dá-os por presa, na terra do cativeiro.'),
('acf','ne',4,5,'E não cubras a sua iniqüidade, e não se risque de diante de ti o seu pecado, pois que te irritaram na presença dos edificadores.'),
('acf','ne',4,6,'Porém edificamos o muro, e todo o muro se fechou até sua metade; porque o coração do povo se inclinava a trabalhar.'),
('acf','ne',4,7,'E sucedeu que, ouvindo Sambalate e Tobias, e os árabes, os amonitas, e os asdoditas, que tanto ia crescendo a reparação dos muros de Jerusalém, que já as roturas se começavam a tapar, iraram-se sobremodo,'),
('acf','ne',4,8,'E ligaram-se entre si todos, para virem guerrear contra Jerusalém, e para os desviarem do seu intento.'),
('acf','ne',4,9,'Porém nós oramos ao nosso Deus e pusemos uma guarda contra eles, de dia e de noite, por causa deles.'),
('acf','ne',4,10,'Então disse Judá: Já desfaleceram as forças dos carregadores, e o pó é muito, e nós não poderemos edificar o muro.'),
('acf','ne',4,11,'Disseram, porém, os nossos inimigos: Nada saberão disto, nem verão, até que entremos no meio deles, e os matemos; assim faremos cessar a obra.'),
('acf','ne',4,12,'E sucedeu que, vindo os judeus que habitavam entre eles, dez vezes nos disseram: De todos os lugares, tornarão contra nós.'),
('acf','ne',4,13,'Então pus guardas nos lugares baixos por detrás do muro e nos altos; e pus ao povo pelas suas famílias com as suas espadas, com as suas lanças, e com os seus arcos.'),
('acf','ne',4,14,'E olhei, e levantei-me, e disse aos nobres, aos magistrados, e ao restante do povo: Não os temais; lembrai-vos do grande e terrível Senhor, e pelejai pelos vossos irmãos, vossos filhos, vossas mulheres e vossas casas.'),
('acf','ne',4,15,'E sucedeu que, ouvindo os nossos inimigos que já o sabíamos, e que Deus tinha dissipado o conselho deles, todos voltamos ao muro, cada um à sua obra.'),
('acf','ne',4,16,'E sucedeu que, desde aquele dia, metade dos meus servos trabalhava na obra, e metade deles tinha as lanças, os escudos, os arcos e as couraças; e os líderes estavam por detrás de toda a casa de Judá.'),
('acf','ne',4,17,'Os que edificavam o muro, os que traziam as cargas e os que carregavam, cada um com uma das mãos fazia a obra e na outra tinha as armas.'),
('acf','ne',4,18,'E os edificadores cada um trazia a sua espada cingida aos lombos, e edificavam; e o que tocava a trombeta estava junto comigo.'),
('acf','ne',4,19,'E disse eu aos nobres, aos magistrados e ao restante do povo: Grande e extensa é a obra, e nós estamos apartados do muro, longe uns dos outros.'),
('acf','ne',4,20,'No lugar onde ouvirdes o som da buzina, ali vos ajuntareis conosco; o nosso Deus pelejará por nós.'),
('acf','ne',4,21,'Assim trabalhávamos na obra; e metade deles tinha as lanças desde a subida da alva até ao sair das estrelas.'),
('acf','ne',4,22,'Também naquele tempo disse ao povo: Cada um com o seu servo fique em Jerusalém, para que à noite nos sirvam de guarda, e de dia na obra.'),
('acf','ne',4,23,'E nem eu, nem meus irmãos, nem meus servos, nem os homens da guarda que me seguiam largávamos as nossas vestes; cada um tinha suas armas e água.'),
('acf','ne',5,1,'Foi, porém, grande o clamor do povo e de suas mulheres, contra os judeus, seus irmãos.'),
('acf','ne',5,2,'Porque havia quem dizia: Nós, nossos filhos e nossas filhas, somos muitos; então tomemos trigo, para que comamos e vivamos.'),
('acf','ne',5,3,'Também havia quem dizia: As nossas terras, as nossas vinhas e as nossas casas empenhamos, para tomarmos trigo nesta fome.'),
('acf','ne',5,4,'Também havia quem dizia: Tomamos emprestado dinheiro até para o tributo do rei, sobre as nossas terras e as nossas vinhas.'),
('acf','ne',5,5,'Agora, pois, a nossa carne é como a carne de nossos irmãos, e nossos filhos como seus filhos; e eis que sujeitamos nossos filhos e nossas filhas para serem servos; e até algumas de nossas filhas são tão sujeitas, que já não estão no poder de nossas mãos; e outros têm as nossas terras e as nossas vinhas.'),
('acf','ne',5,6,'Ouvindo eu, pois, o seu clamor, e estas palavras, muito me indignei.'),
('acf','ne',5,7,'E considerei comigo mesmo no meu coração; depois pelejei com os nobres e com os magistrados, e disse-lhes: Sois usurários cada um para com seu irmão. E convoquei contra eles uma grande assembléia.'),
('acf','ne',5,8,'E disse-lhes: Nós resgatamos os judeus, nossos irmãos, que foram vendidos às nações, segundo nossas posses; e vós outra vez venderíeis a vossos irmãos, ou vender-se-iam a nós? Então se calaram, e não acharam que responder.'),
('acf','ne',5,9,'Disse mais: Não é bom o que fazeis; porventura não andaríeis no temor do nosso Deus, por causa do opróbrio das nações, os nossos inimigos?'),
('acf','ne',5,10,'Também eu, meus irmãos e meus servos, a juros lhes temos emprestado dinheiro e trigo. Deixemos este ganho.'),
('acf','ne',5,11,'Restituí-lhes hoje, vos peço, as suas terras, as suas vinhas, os seus olivais e as suas casas; como também a centésima parte do dinheiro, do trigo, do mosto e do azeite, que vós exigis deles.'),
('acf','ne',5,12,'Então disseram: Restituir-lhes-emos, e nada procuraremos deles; faremos assim como dizes. Então chamei os sacerdotes, e os fiz jurar que fariam conforme a esta palavra.'),
('acf','ne',5,13,'Também sacudi as minhas vestes, e disse: Assim sacuda Deus todo o homem da sua casa e do seu trabalho que não confirmar esta palavra, e assim seja sacudido e vazio. E toda a congregação disse: Amém! E louvaram ao Senhor; e o povo fez conforme a esta palavra.'),
('acf','ne',5,14,'Também desde o dia em que me mandou que eu fosse seu governador na terra de Judá, desde o ano vinte, até ao ano trinta e dois do rei Artaxerxes, doze anos, nem eu nem meus irmãos comemos o pão do governador.'),
('acf','ne',5,15,'Mas os primeiros governadores, que foram antes de mim, oprimiram o povo, e tomaram-lhe pão e vinho e, além disso, quarenta siclos de prata, como também os seus servos dominavam sobre o povo; porém eu assim não fiz, por causa do temor de Deus.'),
('acf','ne',5,16,'Como também na obra deste muro fiz reparação, e terra nenhuma compramos; e todos os meus servos se ajuntaram ali à obra.'),
('acf','ne',5,17,'Também dos judeus e dos magistrados, cento e cinqüenta homens, e os que vinham a nós dentre as nações que estão ao redor de nós, se punham à minha mesa.'),
('acf','ne',5,18,'E o que se preparava para cada dia era um boi e seis ovelhas escolhidas; também aves se me preparavam e, de dez em dez dias, muito vinho de todas as espécies; e nem por isso exigi o pão do governador, porquanto a servidão deste povo era grande.'),
('acf','ne',5,19,'Lembra-te de mim para bem, ó meu Deus, e de tudo quanto fiz a este povo.'),
('acf','ne',6,1,'Sucedeu que, ouvindo Sambalate, Tobias, Gesém, o árabe, e o resto dos nossos inimigos, que eu tinha edificado o muro, e que nele já não havia brecha alguma, ainda que até este tempo não tinha posto as portas nos portais,'),
('acf','ne',6,2,'Sambalate e Gesém mandaram dizer-me: Vem, e congreguemo-nos juntamente nas aldeias, no vale de Ono. Porém intentavam fazer-me mal.'),
('acf','ne',6,3,'E enviei-lhes mensageiros a dizer: Faço uma grande obra, de modo que não poderei descer; por que cessaria esta obra, enquanto eu a deixasse, e fosse ter convosco?'),
('acf','ne',6,4,'E do mesmo modo enviaram a mim quatro vezes; e da mesma forma lhes respondi.'),
('acf','ne',6,5,'Então Sambalate ainda pela quinta vez me enviou seu servo com uma carta aberta na sua mão;'),
('acf','ne',6,6,'E na qual estava escrito: Entre os gentios se ouviu, e Gasmu diz: Tu e os judeus intentais rebelar-vos, então edificas o muro; e tu te farás rei deles segundo estas palavras;'),
('acf','ne',6,7,'E que puseste profetas, para pregarem de ti em Jerusalém, dizendo: Este é rei em Judá; de modo que o rei o ouvirá, segundo estas palavras; vem, pois, agora, e consultemos juntamente.'),
('acf','ne',6,8,'Porém eu mandei dizer-lhe: De tudo o que dizes coisa nenhuma sucedeu; mas tu, do teu coração, o inventas.'),
('acf','ne',6,9,'Porque todos eles procuravam atemorizar-nos, dizendo: As suas mãos largarão a obra, e não se efetuará. Agora, pois, ó Deus, fortalece as minhas mãos.'),
('acf','ne',6,10,'E, entrando eu em casa de Semaías, filho de Delaías, o filho de Meetabel (que estava encerrado), disse ele: Vamos juntamente à casa de Deus, ao meio do templo, e fechemos as portas do templo; porque virão matar-te; sim, de noite virão matar-te.'),
('acf','ne',6,11,'Porém eu disse: Um homem como eu fugiria? E quem há, como eu, que entre no templo para que viva? De maneira nenhuma entrarei.'),
('acf','ne',6,12,'E percebi que não era Deus quem o enviara; mas esta profecia falou contra mim, porquanto Tobias e Sambalate o subornaram.'),
('acf','ne',6,13,'Para isto o subornaram, para me atemorizar, e para que assim fizesse, e pecasse, para que tivessem alguma causa para me infamarem, e assim me vituperarem.'),
('acf','ne',6,14,'Lembra-te, meu Deus, de Tobias e de Sambalate, conforme a estas suas obras, e também da profetisa Noadia, e dos mais profetas que procuraram atemorizar-me.'),
('acf','ne',6,15,'Acabou-se, pois, o muro aos vinte e cinco do mês de Elul; em cinqüenta e dois dias.'),
('acf','ne',6,16,'E sucedeu que, ouvindo-o todos os nossos inimigos, todos os povos que havia em redor de nós temeram, e abateram-se muito a seus próprios olhos; porque reconheceram que o nosso Deus fizera esta obra.'),
('acf','ne',6,17,'Também naqueles dias alguns nobres de Judá escreveram muitas cartas que iam para Tobias; e as cartas de Tobias vinham para eles.'),
('acf','ne',6,18,'Porque muitos em Judá lhe eram ajuramentados, porque era genro de Secanias filho de Ará; e seu filho Joanã se casara com a filha de Mesulão, filho de Berequias.'),
('acf','ne',6,19,'Também as suas boas ações contavam perante mim, e as minhas palavras transmitiam a ele; portanto Tobias escrevia cartas para me atemorizar.'),
('acf','ne',7,1,'Sucedeu que, depois que o muro foi edificado, eu levantei as portas; e foram estabelecidos os porteiros, os cantores e os levitas.'),
('acf','ne',7,2,'Eu nomeei a Hanani, meu irmão, e a Hananias, líder da fortaleza, sobre Jerusalém; porque ele era homem fiel e temente a Deus, mais do que muitos.'),
('acf','ne',7,3,'E disse-lhes: Não se abram as portas de Jerusalém até que o sol aqueça, e enquanto os que assisti-rem ali permanecerem, fechem as portas, e vós trancai-as; e ponhamse guardas dos moradores de Jerusalém, cada um na sua guarda, e cada um diante da sua casa.'),
('acf','ne',7,4,'E era a cidade larga de espaço, e grande, porém pouco povo havia dentro dela; e ainda as casas não estavam edificadas.'),
('acf','ne',7,5,'Então o meu Deus me pôs no coração que ajuntasse os nobres, os magistrados e o povo, para registrar as genealogias; e achei o livro da genealogia dos que subiram primeiro e nele estava escrito o seguinte:'),
('acf','ne',7,6,'Estes são os filhos da província, que subiram do cativeiro dos exilados, que transportara Nabucodonosor, rei de Babilônia; e voltaram para Jerusalém e para Judá, cada um para a sua cidade;'),
('acf','ne',7,7,'Os quais vieram com Zorobabel, Jesuá, Neemias, Azarias, Raamias, Naamani, Mordecai, Bilsã, Misperete, Bigvai, Neum, e Baaná; este é o número dos homens do povo de Israel.'),
('acf','ne',7,8,'Foram os filhos de Parós, dois mil, cento e setenta e dois.'),
('acf','ne',7,9,'Os filhos de Sefatias, trezentos e setenta e dois.'),
('acf','ne',7,10,'Os filhos de Ará, seiscentos e cinqüenta e dois.'),
('acf','ne',7,11,'Os filhos de Paate-Moabe, dos filhos de Jesuá e de Joabe, dois mil, oitocentos e dezoito.'),
('acf','ne',7,12,'Os filhos de Elão, mil, duzentos e cinqüenta e quatro.'),
('acf','ne',7,13,'Os filhos de Zatu, oitocentos e quarenta e cinco.'),
('acf','ne',7,14,'Os filhos de Zacai, setecentos e sessenta.'),
('acf','ne',7,15,'Os filhos de Binui, seiscentos e quarenta e oito.'),
('acf','ne',7,16,'Os filhos de Bebai, seiscentos e vinte e oito.'),
('acf','ne',7,17,'Os filhos de Azgade, dois mil, trezentos e vinte e dois.'),
('acf','ne',7,18,'Os filhos de Adonicão, seiscentos e sessenta e sete.'),
('acf','ne',7,19,'Os filhos de Bigvai, dois mil e sessenta e sete.'),
('acf','ne',7,20,'Os filhos de Adim, seiscentos e cinqüenta e cinco.'),
('acf','ne',7,21,'Os filhos de Ater, de Ezequias, noventa e oito.'),
('acf','ne',7,22,'Os filhos de Hassum, trezentos e vinte e oito.'),
('acf','ne',7,23,'Os filhos de Bezai, trezentos e vinte e quatro.'),
('acf','ne',7,24,'Os filhos de Harife, cento e doze.'),
('acf','ne',7,25,'Os filhos de Gibeom, noventa e cinco.'),
('acf','ne',7,26,'Os homens de Belém e de Netofa, cento e oitenta e oito.'),
('acf','ne',7,27,'Os homens de Anatote, cento e vinte e oito.'),
('acf','ne',7,28,'Os homens de Bete-Azmavete, quarenta e dois.'),
('acf','ne',7,29,'Os homens de Quiriate-Jearim, Quefira e Beerote, setecentos e quarenta e três.'),
('acf','ne',7,30,'Os homens de Ramá e Geba, seiscentos e vinte e um.'),
('acf','ne',7,31,'Os homens de Micmás, cento e vinte e dois.'),
('acf','ne',7,32,'Os homens de Betel e Ai, cento e vinte e três.'),
('acf','ne',7,33,'Os homens do outro Nebo, cinqüenta e dois.'),
('acf','ne',7,34,'Os filhos do outro Elão, mil, duzentos e cinqüenta e quatro:'),
('acf','ne',7,35,'Os filhos de Harim, trezentos e vinte.'),
('acf','ne',7,36,'Os filhos de Jericó, trezentos e quarenta e cinco.'),
('acf','ne',7,37,'Os filhos de Lode, Hadide e Ono, setecentos e vinte e um.'),
('acf','ne',7,38,'Os filhos de Senaá, três mil, novecentos e trinta.'),
('acf','ne',7,39,'Os sacerdotes: Os filhos de Jedaías, da casa de Jesuá, novecentos e setenta e três.'),
('acf','ne',7,40,'Os filhos de Imer, mil e cinqüenta e dois.'),
('acf','ne',7,41,'Os filhos de Pasur, mil, duzentos e quarenta e sete.'),
('acf','ne',7,42,'Os filhos de Harim, mil e dezessete.'),
('acf','ne',7,43,'Os levitas: Os filhos de Jesuá, de Cadmiel, dos filhos de Hodeva, setenta e quatro.'),
('acf','ne',7,44,'Os cantores: Os filhos de Asafe, cento e quarenta e oito.'),
('acf','ne',7,45,'Os porteiros: Os filhos de Salum, os filhos de Ater, os filhos de Talmom, os filhos de Acube, os filhos de Hatita, os filhos de Sobai, cento e trinta e oito.'),
('acf','ne',7,46,'Os servidores do templo: Os filhos de Zia, os filhos de Hasufa, os filhos de Tabaote,'),
('acf','ne',7,47,'Os filhos de Queros, os filhos de Sia, os filhos de Padom,'),
('acf','ne',7,48,'Os filhos de Lebana, os filhos de Hagaba, os filhos de Salmai,'),
('acf','ne',7,49,'Os filhos de Hanã, os filhos de Gidel, os filhos de Gaar,'),
('acf','ne',7,50,'Os filhos de Reaías, os filhos de Rezim, os filhos de Necoda,'),
('acf','ne',7,51,'Os filhos de Gazão, os filhos de Uzá, os filhos de Paseá,'),
('acf','ne',7,52,'Os filhos de Besai, os filhos de Meunim, os filhos de Nefussim,'),
('acf','ne',7,53,'Os filhos de Bacbuque, os filhos de Hacufa, os filhos de Harur,'),
('acf','ne',7,54,'Os filhos de Bazlite, os filhos de Meída, os filhos de Harsa,'),
('acf','ne',7,55,'Os filhos de Barcos, os filhos de Sísera, os filhos de Tamá,'),
('acf','ne',7,56,'Os filhos de Neziá, os filhos de Hatifa.'),
('acf','ne',7,57,'Os filhos dos servos de Salomão, os filhos de Sotai, os filhos de Soferete, os filhos de Perida,'),
('acf','ne',7,58,'Os filhos de Jaala, os filhos de Darcom, os filhos de Gidel,'),
('acf','ne',7,59,'Os filhos de Sefatias, os filhos de Hatil, os filhos de Poquerete-Hazebaim, os filhos de Amom.'),
('acf','ne',7,60,'Todos os servidores do templo e os filhos dos servos de Salomão, trezentos e noventa e dois.'),
('acf','ne',7,61,'Também estes subiram de Tel-Melá, e Tel-Harsa, Querube, Adom, Imer; porém não puderam provar que a casa de seus pais e a sua linhagem, eram de Israel.'),
('acf','ne',7,62,'Os filhos de Delaías, os filhos de Tobias, os filhos de Necoda, seiscentos e quarenta e dois.'),
('acf','ne',7,63,'E dos sacerdotes: os filhos de Habaías, os filhos de Coz, os filhos de Barzilai, que tomara uma mulher das filhas de Barzilai, o gileadita, e que foi chamado do seu nome.'),
('acf','ne',7,64,'Estes buscaram o seu registro nos livros genealógicos, porém não se achou; então, como imundos, foram excluídos do sacerdócio.'),
('acf','ne',7,65,'E o governador lhes disse que não comessem das coisas sagradas, até que se apresentasse o sacerdote com Urim e Tumim.'),
('acf','ne',7,66,'Toda esta congregação junta foi de quarenta e dois mil, trezentos e sessenta,'),
('acf','ne',7,67,'Afora os seus servos e as suas servas, que foram sete mil, trezentos e trinta e sete; e tinham duzentos e quarenta e cinco cantores e cantoras.'),
('acf','ne',7,68,'Os seus cavalos, setecentos e trinta e seis; os seus mulos, duzentos e quarenta e cinco.'),
('acf','ne',7,69,'Camelos, quatrocentos e trinta e cinco; jumentos, seis mil, setecentos e vinte.'),
('acf','ne',7,70,'E uma parte dos chefes dos pais contribuíram para a obra. O governador deu para o tesouro, em ouro, mil dracmas, cinqüenta bacias, e quinhentas e trinta vestes sacerdotais.'),
('acf','ne',7,71,'E alguns mais dos chefes dos pais contribuíram para o tesouro da obra, em ouro, vinte mil dracmas, e em prata, duas mil e duzentas libras.'),
('acf','ne',7,72,'E o que deu o restante do povo foi, em ouro, vinte mil dracmas, e em prata, duas mil libras; e sessenta e sete vestes sacerdotais.'),
('acf','ne',7,73,'E habitaram os sacerdotes, os levitas, os porteiros, os cantores, alguns do povo, os servidores do templo, e todo o Israel nas suas cidades.'),
('acf','ne',8,1,'E chegado o sétimo mês, e estando os filhos de Israel nas suas cidades, todo o povo se ajuntou como um só homem, na praça, diante da porta das águas; e disseram a Esdras, o escriba, que trouxesse o livro da lei de Moisés, que o SENHOR tinha ordenado a Israel.'),
('acf','ne',8,2,'E Esdras, o sacerdote, trouxe a lei perante a congregação, tanto de homens como de mulheres, e todos os que podiam ouvir com entendimento, no primeiro dia do sétimo mês.'),
('acf','ne',8,3,'E leu no livro diante da praça, que está diante da porta das águas, desde a alva até ao meio-dia, perante homens e mulheres, e os que podiam entender; e os ouvidos de todo o povo estavam atentos ao livro da lei.'),
('acf','ne',8,4,'E Esdras, o escriba, estava sobre um púlpito de madeira, que fizeram para aquele fim; e estava em pé junto a ele, à sua mão direita, Matitias, Sema, Anaías, Urias, Hilquias e Maaséias; e à sua mão esquerda, Pedaías, Misael, Melquias, Hasum, Hasbadana, Zacarias e Mesulão.'),
('acf','ne',8,5,'E Esdras abriu o livro perante à vista de todo o povo; porque estava acima de todo o povo; e, abrindo-o ele, todo o povo se pôs em pé.'),
('acf','ne',8,6,'E Esdras louvou ao Senhor, o grande Deus; e todo o povo respondeu: Amém, Amém! levantando as suas mãos; e inclinaram suas cabeças, e adoraram ao Senhor, com os rostos em terra.'),
('acf','ne',8,7,'E Jesuá, Bani, Serebias, Jamim, Acube, Sabetai, Hodias, Maaséias, Quelita, Azarias, Jozabade, Hanã, Pelaías, e os levitas ensinavam o povo na lei; e o povo estava no seu lugar.'),
('acf','ne',8,8,'E leram no livro, na lei de Deus; e declarando, e explicando o sentido, faziam que, lendo, se entendesse.'),
('acf','ne',8,9,'E Neemias, que era o governador, e o sacerdote Esdras, o escriba, e os levitas que ensinavam ao povo, disseram a todo o povo: Este dia é consagrado ao Senhor vosso Deus, então não vos lamenteis, nem choreis. Porque todo o povo chorava, ouvindo as palavras da lei.'),
('acf','ne',8,10,'Disse-lhes mais: Ide, comei as gorduras, e bebei as doçuras, e enviai porções aos que não têm nada preparado para si; porque este dia é consagrado ao nosso Senhor; portanto não vos entristeçais; porque a alegria do Senhor é a vossa força.'),
('acf','ne',8,11,'E os levitas fizeram calar a todo o povo, dizendo: Calai-vos; porque este dia é santo; por isso não vos entristeçais.'),
('acf','ne',8,12,'Então todo o povo se foi a comer, a beber, a enviar porções e a fazer grande regozijo; porque entenderam as palavras que lhes fizeram saber.'),
('acf','ne',8,13,'E no dia seguinte ajuntaram-se os chefes dos pais de todo o povo, os sacerdotes e os levitas, a Esdras, o escriba; e isto para atentarem nas palavras da lei.'),
('acf','ne',8,14,'E acharam escrito na lei que o Senhor ordenara, pelo ministério de Moisés, que os filhos de Israel habitassem em cabanas, na solenidade da festa, no sétimo mês.'),
('acf','ne',8,15,'Assim publicaram, e fizeram passar pregão por todas as suas cidades, e em Jerusalém, dizendo: Saí ao monte, e trazei ramos de oliveiras, e ramos de zambujeiros, e ramos de murtas, e ramos de palmeiras, e ramos de árvores espessas, para fazer cabanas, como está escrito.'),
('acf','ne',8,16,'Saiu, pois, o povo, e os trouxeram, e fizeram para si cabanas, cada um no seu terraço, nos seus pátios, e nos átrios da casa de Deus, na praça da porta das águas, e na praça da porta de Efraim.'),
('acf','ne',8,17,'E toda a congregação dos que voltaram do cativeiro fizeram cabanas, e habitaram nas cabanas, porque nunca fizeram assim os filhos de Israel, desde os dias de Jesua, filho de Num, até àquele dia; e houve mui grande alegria.'),
('acf','ne',8,18,'E, de dia em dia, Esdras leu no livro da lei de Deus, desde o primeiro dia até ao derradeiro; e celebraram a solenidade da festa sete dias, e no oitavo dia, houve uma assembléia solene, segundo o rito.'),
('acf','ne',9,1,'E, no dia vinte e quatro deste mês, ajuntaram-se os filhos de Israel com jejum e com sacos, e traziam terra sobre si.'),
('acf','ne',9,2,'E a descendência de Israel se apartou de todos os estrangeiros, e puseram-se em pé, e fizeram confissão pelos seus pecados e pelas iniqüidades de seus pais.'),
('acf','ne',9,3,'E, levantando-se no seu lugar, leram no livro da lei do Senhor seu Deus uma quarta parte do dia; e na outra quarta parte fizeram confissão, e adoraram ao Senhor seu Deus.'),
('acf','ne',9,4,'E Jesuá, Bani, Cadmiel, Sebanias, Buni, Serebias, Bani e Quenani se puseram em pé no lugar alto dos levitas, e clamaram em alta voz ao Senhor seu Deus.'),
('acf','ne',9,5,'E os levitas, Jesuá, Cadmiel, Bani, Hasabnéias, Serebias, Hodias, Sebanias e Petaías, disseram: Levantai-vos, bendizei ao Senhor vosso Deus de eternidade em eternidade; e bendigam o teu glorioso nome, que está exaltado sobre toda a bênção e louvor.'),
('acf','ne',9,6,'Só tu és Senhor; tu fizeste o céu, o céu dos céus, e todo o seu exército, a terra e tudo quanto nela há, os mares e tudo quanto neles há, e tu os guardas com vida a todos; e o exército dos céus te adora.'),
('acf','ne',9,7,'Tu és o Senhor, o Deus, que elegeste a Abrão, e o tiraste de Ur dos caldeus, e lhe puseste por nome Abraão.'),
('acf','ne',9,8,'E achaste o seu coração fiel perante ti, e fizeste com ele a aliança, de que darias à sua descendência a terra dos cananeus, dos heteus, dos amorreus, dos perizeus, dos jebuseus e dos girgaseus; e confirmaste as tuas palavras, porquanto és justo.'),
('acf','ne',9,9,'E viste a aflição de nossos pais no Egito, e ouviste o seu clamor junto ao Mar Vermelho.'),
('acf','ne',9,10,'E mostraste sinais e prodígios a Faraó, e a todos os seus servos, e a todo o povo da sua terra, porque soubeste que soberbamente os trataram; e assim adquiriste para ti nome, como hoje se vê.'),
('acf','ne',9,11,'E o mar fendeste perante eles, e passaram pelo meio do mar, em seco; e lançaste os seus perseguidores nas profundezas, como uma pedra nas águas violentas.'),
('acf','ne',9,12,'E guiaste-os de dia por uma coluna de nuvem, e de noite por uma coluna de fogo, para lhes iluminar o caminho por onde haviam de ir.'),
('acf','ne',9,13,'E sobre o monte Sinai desceste, e dos céus falaste com eles, e deste-lhes juízos retos e leis verdadeiras, estatutos e mandamentos bons.'),
('acf','ne',9,14,'E o teu santo sábado lhes fizeste conhecer; e preceitos, estatutos e lei lhes mandaste pelo ministério de Moisés, teu servo.'),
('acf','ne',9,15,'E pão dos céus lhes deste na sua fome, e água da penha lhes produziste na sua sede; e lhes disseste que entrassem para possuírem a terra pela qual alçaste a tua mão, que lhes havias de dar.'),
('acf','ne',9,16,'Porém eles e nossos pais se houveram soberbamente, e endureceram a sua cerviz, e não deram ouvidos aos teus mandamentos.'),
('acf','ne',9,17,'E recusaram ouvir-te, e não se lembraram das tuas maravilhas, que lhes fizeste, e endureceram a sua cerviz e, na sua rebelião, levantaram um capitão, a fim de voltarem para a sua servidão; porém tu, ó Deus perdoador, clemente e misericordioso, tardio em irar-te, e grande em beneficência, tu não os desamparaste.'),
('acf','ne',9,18,'Ainda mesmo quando eles fizeram para si um bezerro de fundição, e disseram: Este é o teu Deus, que te tirou do Egito; e cometeram grandes blasfêmias;'),
('acf','ne',9,19,'Todavia tu, pela multidão das tuas misericórdias, não os deixaste no deserto. A coluna de nuvem nunca se apartou deles de dia, para os guiar pelo caminho, nem a coluna de fogo de noite, para lhes iluminar; e isto pelo caminho por onde haviam de ir.'),
('acf','ne',9,20,'E deste o teu bom espírito, para os ensinar; e o teu maná não retiraste da sua boca; e água lhes deste na sua sede.'),
('acf','ne',9,21,'De tal modo os sustentaste quarenta anos no deserto; nada lhes faltou; as suas roupas não se envelheceram, e os seus pés não se incharam.'),
('acf','ne',9,22,'Também lhes deste reinos e povos, e os repartiste em porções; e eles possuíram a terra de Siom, a saber, a terra do rei de Hesbom, e a terra de Ogue, rei de Basã.'),
('acf','ne',9,23,'E multiplicaste os seus filhos como as estrelas do céu, e trouxeste-os à terra de que tinhas falado a seus pais que nela entrariam para a possuírem.'),
('acf','ne',9,24,'Assim os filhos entraram e possuíram aquela terra; e abateste perante eles os moradores da terra, os cananeus, e lhos entregaste na mão, como também os reis e os povos da terra, para fazerem deles conforme a sua vontade.'),
('acf','ne',9,25,'E tomaram cidades fortificadas e terra fértil, e possuíram casas cheias de toda a fartura, cisternas cavadas, vinhas e olivais, e árvores frutíferas, em abundância; e comeram e se fartaram e engordaram e viveram em delícias, pela tua grande bondade.'),
('acf','ne',9,26,'Porém se obstinaram, e se rebelaram contra ti, e lançaram a tua lei para trás das suas costas, e mataram os teus profetas, que protestavam contra eles, para que voltassem para ti; assim fizeram grandes abominações.'),
('acf','ne',9,27,'Por isso os entregaste na mão dos seus adversários, que os angustiaram; mas no tempo de sua angústia, clamando a ti, desde os céus tu ouviste; e segundo a tua grande misericórdia lhes deste libertadores que os libertaram da mão de seus adversários.'),
('acf','ne',9,28,'Porém, em tendo repouso, tornavam a fazer o mal diante de ti; e tu os deixavas na mão dos seus inimigos, para que dominassem sobre eles; e convertendo-se eles, e clamando a ti, tu os ouviste desde os céus, e segundo a tua misericórdia os livraste muitas vezes.'),
('acf','ne',9,29,'E testificaste contra eles, para que voltassem para a tua lei; porém eles se houveram soberbamente, e não deram ouvidos aos teus mandamentos, mas pecaram contra os teus juízos, pelos quais o homem que os cumprir viverá; viraram o ombro, endureceram a sua cerviz, e não quiseram ouvir.'),
('acf','ne',9,30,'Porém estendeste a tua benignidade sobre eles por muitos anos, e testificaste contra eles pelo teu Espírito, pelo ministério dos teus profetas; porém eles não deram ouvidos; por isso os entregaste nas mãos dos povos das terras.'),
('acf','ne',9,31,'Mas pela tua grande misericórdia os não destruíste nem desamparaste, porque és um Deus clemente e misericordioso.'),
('acf','ne',9,32,'Agora, pois, nosso Deus, o grande, poderoso e terrível Deus, que guardas a aliança e a beneficência, não tenhas em pouca conta toda a aflição que nos alcançou a nós, aos nossos reis, aos nossos príncipes, aos nossos sacerdotes, aos nossos profetas, aos nossos pais e a todo o teu povo, desde os dias dos reis da Assíria até ao dia de hoje.'),
('acf','ne',9,33,'Porém tu és justo em tudo quanto tem vindo sobre nós; porque tu tens agido fielmente, e nós temos agido impiamente.'),
('acf','ne',9,34,'E os nossos reis, os nossos príncipes, os nossos sacerdotes, e os nossos pais não guardaram a tua lei, e não deram ouvidos aos teus mandamentos e aos teus testemunhos, que testificaste contra eles.'),
('acf','ne',9,35,'Porque eles nem no seu reino, nem na muita abundância de bens que lhes deste, nem na terra espaçosa e fértil que puseste diante deles, te serviram, nem se converteram de suas más obras.'),
('acf','ne',9,36,'Eis que hoje somos servos; e até na terra que deste a nossos pais, para comerem o seu fruto e o seu bem, eis que somos servos nela.'),
('acf','ne',9,37,'E ela multiplica os seus produtos para os reis, que puseste sobre nós, por causa dos nossos pecados; e conforme a sua vontade dominam sobre os nossos corpos e sobre o nosso gado; e estamos numa grande angústia.'),
('acf','ne',9,38,'E, todavia fizemos uma firme aliança, e o escrevemos; e selaram-no os nossos príncipes, os nossos levitas e os nossos sacerdotes.'),
('acf','ne',10,1,'E os que selaram foram: Neemias, o governador, filho de Hacalias, e Zedequias,'),
('acf','ne',10,2,'Seraías, Azarias, Jeremias,'),
('acf','ne',10,3,'Pasur, Amarias, Malquias,'),
('acf','ne',10,4,'Hatus, Sebanias, Maluque,'),
('acf','ne',10,5,'Harim, Meremote, Obadias,'),
('acf','ne',10,6,'Daniel, Ginetom, Baruque,'),
('acf','ne',10,7,'Mesulão, Abias, Miamim,'),
('acf','ne',10,8,'Maazias, Bilgai, Semaías; estes eram os sacerdotes.'),
('acf','ne',10,9,'E os levitas: Jesuá, filho de Azanias, Binui, dos filhos de Henadade, Cadmiel,'),
('acf','ne',10,10,'E seus irmãos: Sebanias, Hodias, Quelita, Pelaías, Hanã,'),
('acf','ne',10,11,'Mica, Reobe, Hasabias,'),
('acf','ne',10,12,'Zacur, Serebias, Sebanias,'),
('acf','ne',10,13,'Hodias, Bani e Beninu.'),
('acf','ne',10,14,'Os chefes do povo: Parós, Paate-Moabe, Elão, Zatu, Bani,'),
('acf','ne',10,15,'Buni, Azgade, Bebai,'),
('acf','ne',10,16,'Adonias, Bigvai, Adim,'),
('acf','ne',10,17,'Ater, Ezequias, Azur,'),
('acf','ne',10,18,'Hodias, Hasum, Bezai,'),
('acf','ne',10,19,'Harife, Anatote, Nebai,'),
('acf','ne',10,20,'Magpias, Mesulão, Hezir,'),
('acf','ne',10,21,'Mesezabeel, Zadoque, Jadua,'),
('acf','ne',10,22,'Pelatias, Hanã, Anaías,'),
('acf','ne',10,23,'Oséias, Hananias, Hassube,'),
('acf','ne',10,24,'Haloés, Pilha, Sobeque,'),
('acf','ne',10,25,'Reum, Hasabná, Maaséias,'),
('acf','ne',10,26,'E Aías, Hanã, Anã,'),
('acf','ne',10,27,'Maluque, Harim e Baaná.'),
('acf','ne',10,28,'E o restante do povo, os sacerdotes, os levitas, os porteiros, os cantores, os servidores do templo, todos os que se tinham separado dos povos das terras para a lei de Deus, suas mulheres, seus filhos e suas filhas, todos os que tinham conhecimento e entendimento,'),
('acf','ne',10,29,'Firmemente aderiram a seus irmãos os mais nobres dentre eles, e convieram num anátema e num juramento, de que andariam na lei de Deus, que foi dada pelo ministério de Moisés, servo de Deus; e de que guardariam e cumpririam todos os mandamentos do Senhor nosso Senhor, e os seus juízos e os seus estatutos;'),
('acf','ne',10,30,'E que não daríamos as nossas filhas aos povos da terra, nem tomaríamos as filhas deles para os nossos filhos.'),
('acf','ne',10,31,'E que, trazendo os povos da terra no dia de sábado qualquer mercadoria, e qualquer grão para venderem, nada compraríamos deles no sábado, nem no dia santificado; e no sétimo ano deixaríamos descansar a terra, e perdoaríamos toda e qualquer cobrança.'),
('acf','ne',10,32,'Também sobre nós pusemos preceitos, impondo-nos cada ano a terça parte de um siclo, para o ministério da casa do nosso Deus;'),
('acf','ne',10,33,'Para os pães da proposição, para a contínua oferta de alimentos, e para o contínuo holocausto dos sábados, das luas novas, para as festas solenes, para as coisas sagradas, e para os sacrifícios pelo pecado, para expiação de Israel, e para toda a obra da casa do nosso Deus.'),
('acf','ne',10,34,'Também lançamos sortes entre os sacerdotes, levitas, e o povo, acerca da oferta da lenha que se havia de trazer à casa do nosso Deus, segundo as casas de nossos pais, a tempos determinados, de ano em ano, para se queimar sobre o altar do Senhor nosso Deus, como está escrito na lei.'),
('acf','ne',10,35,'Que também traríamos as primícias da nossa terra, e as primícias de todos os frutos de todas as árvores, de ano em ano, à casa do Senhor.'),
('acf','ne',10,36,'E os primogênitos dos nossos filhos, e os do nosso gado, como está escrito na lei; e que os primogênitos do nosso gado e das nossas ovelhas traríamos à casa do nosso Deus, aos sacerdotes, que ministram na casa do nosso Deus.'),
('acf','ne',10,37,'E que as primícias da nossa massa, as nossas ofertas alçadas, o fruto de toda a árvore, o mosto e o azeite, traríamos aos sacerdotes, às câmaras da casa do nosso Deus; e os dízimos da nossa terra aos levitas; e que os levitas receberiam os dízimos em todas as cidades, da nossa lavoura.'),
('acf','ne',10,38,'E que o sacerdote, filho de Arão, estaria com os levitas quando estes recebessem os dízimos, e que os levitas trariam os dízimos dos dízimos à casa do nosso Deus, às câmaras da casa do tesouro.'),
('acf','ne',10,39,'Porque àquelas câmaras os filhos de Israel e os filhos de Levi devem trazer ofertas alçadas do grão, do mosto e do azeite; porquanto ali estão os vasos do santuário, como também os sacerdotes que ministram, os porteiros e os cantores; e que assim não desampararíamos a casa do nosso Deus.'),
('acf','ne',11,1,'E os líderes do povo habitaram em Jerusalém, porém o restante do povo lançou sortes, para tirar um de dez, que habitasse na santa cidade de Jerusalém, e as nove partes nas outras cidades.'),
('acf','ne',11,2,'E o povo bendisse a todos os homens que voluntariamente se ofereciam para habitar em Jerusalém.'),
('acf','ne',11,3,'E estes são os chefes da província, que habitaram em Jerusalém; porém nas cidades de Judá habitou cada um na sua possessão, nas suas cidades, Israel, os sacerdotes, os levitas, os servidores do templo, e os filhos dos servos de Salomão.'),
('acf','ne',11,4,'Habitaram, pois, em Jerusalém alguns dos filhos de Judá e dos filhos de Benjamim. Dos filhos de Judá, Ataías, filho de Uzias, filho de Zacarias, filho de Amarias, filho de Sefatias, filho de Maalaleel, dos filhos de Perez;'),
('acf','ne',11,5,'E Maaséias, filho de Baruque, filho de Col-Hoze, filho de Hazaías, filho de Adaías, filho de Joiaribe, filho de Zacarias, filho de Siloni.'),
('acf','ne',11,6,'Todos os filhos de Perez, que habitaram em Jerusalém, foram quatrocentos e sessenta e oito homens valentes.'),
('acf','ne',11,7,'E estes são os filhos de Benjamim: Salu, filho de Mesulão, filho de Joede, filho de Pedaías, filho de Colaías, filho de Maaséias, filho de Itiel, filho de Jesaías.'),
('acf','ne',11,8,'E depois dele Gabai e Salai, ao todo novecentos e vinte e oito.'),
('acf','ne',11,9,'E Joel, filho de Zicri, superintendente sobre eles; e Judá, filho de Senua, o segundo sobre a cidade.'),
('acf','ne',11,10,'Dos sacerdotes: Jedaías, filho de Joiaribe, Jaquim,'),
('acf','ne',11,11,'Seraías, filho de Hilquias, filho de Mesulão, filho de Zadoque, filho de Meraiote, filho de Aitube, líder da casa de Deus,'),
('acf','ne',11,12,'E seus irmãos, que faziam a obra na casa, oitocentos e vinte e dois; e Adaías, filho de Jeroão, filho de Pelalias, filho de Anzi, filho de Zacarias, filho de Pasur, filho de Malquias,'),
('acf','ne',11,13,'E seus irmãos, chefes dos pais, duzentos e quarenta e dois; e Amassai, filho de Azareel, filho de Azai, filho de Mesilemote, filho de Imer,'),
('acf','ne',11,14,'E os irmãos deles, homens valentes, cento e vinte e oito, e superintendente sobre eles Zabdiel, filho de Gedolim.'),
('acf','ne',11,15,'E dos levitas: Semaías, filho de Hassube, filho de Azricão, filho de Hasabias, filho de Buni;'),
('acf','ne',11,16,'E Sabetai, e Jozabade, dos chefes dos levitas, presidiam sobre a obra de fora da casa de Deus.'),
('acf','ne',11,17,'E Matanias, filho de Mica, filho de Zabdi, filho de Asafe, o chefe, que iniciava as ações de graças na oração, e Bacbuquias, o segundo de seus irmãos; depois Abda, filho de Samua, filho de Galal, filho de Jedutum.'),
('acf','ne',11,18,'Todos os levitas na santa cidade, foram duzentos e oitenta e quatro.'),
('acf','ne',11,19,'E os porteiros, Acube, Talmom, com seus irmãos, os guardas das portas, cento e setenta e dois.'),
('acf','ne',11,20,'E o restante de Israel, dos sacerdotes e levitas, habitou em todas as cidades de Judá, cada um na sua herança.'),
('acf','ne',11,21,'E os servidores do templo, habitaram em Ofel; e Zia e Gispa presidiam sobre os servidores do templo.'),
('acf','ne',11,22,'E o superintendente dos levitas em Jerusalém foi Uzi, filho de Bani, filho de Hasabias, filho de Matanias, filho de Mica; dos filhos de Asafe, os cantores, ao serviço da casa de Deus.'),
('acf','ne',11,23,'Porque havia um mandado do rei acerca deles, e uma certa regra para os cantores, cada qual no seu dia.'),
('acf','ne',11,24,'E Petaías, filho de Mesezabeel, dos filhos de Zerá, filho de Judá, estava à mão do rei, em todos os negócios do povo.'),
('acf','ne',11,25,'E quanto às aldeias, com as suas terras, alguns dos filhos de Judá habitaram em Quiriate-Arba e nos lugares da sua jurisdição, e em Dibom, e nos lugares da sua jurisdição, e em Jecabzeel e nas suas aldeias,'),
('acf','ne',11,26,'E em Jesuá, e em Molada, e em Bete-Pelete,'),
('acf','ne',11,27,'E em Hazar-Sual, e em Berseba e nos lugares da sua jurisdição,'),
('acf','ne',11,28,'E em Ziclague, em Mecona e nos lugares da sua jurisdição,'),
('acf','ne',11,29,'E em En-Rimom, em Zorá e em Jarmute,'),
('acf','ne',11,30,'Em Zanoa, Adulão e nas suas aldeias, em Laquis e nas suas terras, em Azaca e nos lugares da sua jurisdição. Acamparam-se desde Berseba até ao vale de Hinom.'),
('acf','ne',11,31,'E os filhos de Benjamim habitaram desde Geba, em Micmás, Aia, Betel e nos lugares da sua jurisdição,'),
('acf','ne',11,32,'E em Anatote, em Nobe, em Ananias,'),
('acf','ne',11,33,'Em Hazor, em Ramá, em Gitaim,'),
('acf','ne',11,34,'Em Hadide, em Zeboim, em Nebalate,'),
('acf','ne',11,35,'Em Lode e em Ono, no vale dos artífices,'),
('acf','ne',11,36,'E alguns dos levitas habitaram nas divisões de Judá e de Benjamim.'),
('acf','ne',12,1,'Estes são sacerdotes e levitas que subiram com Zorobabel, filho de Sealtiel, e com Jesuá: Seraías, Jeremias, Esdras,'),
('acf','ne',12,2,'Amarias, Maluque, Hatus,'),
('acf','ne',12,3,'Secanias, Reum, Meremote,'),
('acf','ne',12,4,'Ido, Ginetoi, Abias,'),
('acf','ne',12,5,'Miamim, Maadias, Bilga,'),
('acf','ne',12,6,'Semaías, Joiaribe, Jedaías,'),
('acf','ne',12,7,'Salu, Amoque, Hilquias, Jedaías; estes foram os chefes dos sacerdotes e de seus irmãos, nos dias de Jesuá.'),
('acf','ne',12,8,'E os levitas: Jesuá, Binui, Cadmiel, Serebias, Judá, Matanias; este e seus irmãos dirigiam os louvores.'),
('acf','ne',12,9,'E Bacbuquias e Uni, seus irmãos, estavam defronte deles, nas guardas.'),
('acf','ne',12,10,'E Jesuá gerou a Joiaquim, e Joiaquim gerou a Eliasibe, e Eliasibe gerou a Joiada,'),
('acf','ne',12,11,'E Joiada gerou a Jônatas, e Jônatas gerou a Jadua.'),
('acf','ne',12,12,'E nos dias de Joiaquim foram sacerdotes, chefes dos pais: de Seraías, Meraías; de Jeremias, Hananias;'),
('acf','ne',12,13,'De Esdras, Mesulão; de Amarias, Joanã;'),
('acf','ne',12,14,'De Maluqui, Jônatas; de Sebanias, José;'),
('acf','ne',12,15,'De Harim, Adna; de Meraiote, Helcai;'),
('acf','ne',12,16,'De Ido, Zacarias; de Ginetom, Mesulão.'),
('acf','ne',12,17,'De Abias, Zicri; de Miamim e de Moadias, Piltai;'),
('acf','ne',12,18,'De Bilga, Samua; de Semaías, Jônatas;'),
('acf','ne',12,19,'E de Joiaribe, Matenai; de Jedaías, Uzi;'),
('acf','ne',12,20,'De Salai, Calai; de Amoque, Éber;'),
('acf','ne',12,21,'De Hilquias, Hasabias; de Jedaías, Natanael.'),
('acf','ne',12,22,'Dos levitas, nos dias de Eliasibe, foram inscritos como chefes de pais, Joiada, Joanã e Jadua; como também os sacerdotes, até ao reinado de Dario, o persa.'),
('acf','ne',12,23,'Os filhos de Levi foram inscritos, como chefes de pais, no livro das crônicas, até aos dias de Joanã, filho de Eliasibe.'),
('acf','ne',12,24,'Foram, pois, os chefes dos levitas: Hasabias, Serabias, e Jesuá, filho de Cadmiel; e seus irmãos estavam defronte deles, para louvarem e darem graças, segundo o mandado de Davi, homem de Deus; guarda contra guarda.'),
('acf','ne',12,25,'Matanias, Bacbuquias, Obadias, Mesulão, Talmom e Acube, eram porteiros, que faziam a guarda às tesourarias das portas.'),
('acf','ne',12,26,'Estes viveram nos dias de Jeoiaquim, filho de Jesuá, o filho de Jozadaque; como também nos dias de Neemias, o governador, e do sacerdote Esdras, o escriba.'),
('acf','ne',12,27,'E na dedicação dos muros de Jerusalém buscaram os levitas de todos os seus lugares, para trazê-los, a fim de fazerem a dedicação com alegria, com louvores e com canto, saltérios, címbalos e com harpas.'),
('acf','ne',12,28,'E assim ajuntaram os filhos dos cantores, tanto da campina dos arredores de Jerusalém, como das aldeias de Netofati;'),
('acf','ne',12,29,'Como também da casa de Gilgal, e dos campos de Geba, e Azmavete; porque os cantores edificaram para si aldeias nos arredores de Jerusalém.'),
('acf','ne',12,30,'E purificaram-se os sacerdotes e os levitas; e logo purificaram o povo, as portas e o muro.'),
('acf','ne',12,31,'Então fiz subir os príncipes de Judá sobre o muro, e ordenei dois grandes coros em procissão, um à mão direita sobre o muro do lado da porta do monturo.'),
('acf','ne',12,32,'E após ele ia Hosaías, e a metade dos príncipes de Judá.'),
('acf','ne',12,33,'E Azarias, Esdras e Mesulão,'),
('acf','ne',12,34,'Judá, Benjamim, Semaías e Jeremias.'),
('acf','ne',12,35,'E dos filhos dos sacerdotes, com trombetas: Zacarias, filho de Jônatas, filho de Semaías, filho de Matanias, filho de Micaías, filho de Zacur, filho de Asafe.'),
('acf','ne',12,36,'E seus irmãos, Semaías, e Azareel, Milalai, Gilalai, Maai, Natanael, Judá e Hanani, com os instrumentos musicais de Davi, homem de Deus; e Esdras, o escriba, ia adiante deles.'),
('acf','ne',12,37,'Indo assim para a porta da fonte, defronte deles, subiram as escadas da cidade de Davi, onde começa a subida do muro, desde cima da casa de Davi, até à porta das águas, do lado do oriente.'),
('acf','ne',12,38,'E o segundo coro ia em frente, e eu após ele; e a metade do povo ia sobre o muro, desde a torre dos fornos, até à muralha larga;'),
('acf','ne',12,39,'E desde a porta de Efraim, passaram por cima da porta velha, e da porta do peixe, e pela torre de Hananeel e a torre de Meá, até à porta do gado; e pararam à porta da prisão.'),
('acf','ne',12,40,'Então ambos os coros pararam na casa de Deus; como também eu, e a metade dos magistrados comigo.'),
('acf','ne',12,41,'E os sacerdotes Eliaquim, Maaséias, Miniamim, Micaías, Elioenai, Zacarias e Hananias, com trombetas.'),
('acf','ne',12,42,'Como também, Maaséias, Semaías, Eleazar, Uzi, Joanã, Malquias, Elão e Ezer; e faziam-se ouvir os cantores, juntamente com Jezraías, o seu superintendente.'),
('acf','ne',12,43,'E ofereceram, no mesmo dia, grandes sacrifícios e se alegraram; porque Deus os alegrara com grande alegria; e até as mulheres e os meninos se alegraram, de modo que a alegria de Jerusalém se ouviu até de longe.'),
('acf','ne',12,44,'Também no mesmo dia se nomearam homens sobre as câmaras, dos tesouros, das ofertas alçadas, das primícias, dos dízimos, para ajuntarem nelas, dos campos das cidades, as partes da lei para os sacerdotes e para os levitas; porque Judá estava alegre por causa dos sacerdotes e dos levitas que assistiam ali.'),
('acf','ne',12,45,'E observava os preceitos do seu Deus, e os da purificação; como também os cantores e porteiros, conforme ao mandado de Davi e de seu filho Salomão.'),
('acf','ne',12,46,'Porque já nos dias de Davi e Asafe, desde a antiguidade, havia chefes dos cantores, e dos cânticos de louvores e de ação de graças a Deus.'),
('acf','ne',12,47,'Por isso todo o Israel, já nos dias de Zorobabel e nos dias de Neemias, dava aos cantores e aos porteiros as porções de cada dia; e santificavam as porções aos levitas, e os levitas as santificavam aos filhos de Arão.'),
('acf','ne',13,1,'Naquele dia leu-se no livro de Moisés, aos ouvidos do povo; e achou-se escrito nele que os amonitas e os moabitas não entrassem jamais na congregação de Deus,'),
('acf','ne',13,2,'Porquanto não tinham saído ao encontro dos filhos de Israel com pão e água; antes contra eles assalariaram a Balaão para os amaldiçoar; porém o nosso Deus converteu a maldição em bênção.'),
('acf','ne',13,3,'Sucedeu, pois, que, ouvindo eles esta lei, apartaram de Israel todo o elemento misto.'),
('acf','ne',13,4,'Ora, antes disto, Eliasibe, sacerdote, que presidia sobre a câmara da casa do nosso Deus, se tinha aparentado com Tobias;'),
('acf','ne',13,5,'E fizera-lhe uma câmara grande, onde dantes se depositavam as ofertas de alimentos, o incenso, os utensílios, os dízimos do grão, do mosto e do azeite, que se ordenaram para os levitas, cantores e porteiros, como também a oferta alçada para os sacerdotes.'),
('acf','ne',13,6,'Mas durante tudo isto não estava eu em Jerusalém, porque no ano trinta e dois de Artaxerxes, rei de babilônia, fui ter com o rei; mas após alguns dias tornei a alcançar licença do rei.'),
('acf','ne',13,7,'E voltando a Jerusalém, compreendi o mal que Eliasibe fizera para Tobias, fazendo-lhe uma câmara nos pátios da casa de Deus.'),
('acf','ne',13,8,'O que muito me desagradou; de sorte que lancei todos os móveis da casa de Tobias fora da câmara.'),
('acf','ne',13,9,'E, ordenando-o eu, purificaram as câmaras; e tornei a trazer para ali os utensílios da casa de Deus, com as ofertas de alimentos e o incenso.'),
('acf','ne',13,10,'Também entendi que os quinhões dos levitas não se lhes davam, de maneira que os levitas e os cantores, que faziam a obra, tinham fugido cada um para a sua terra.'),
('acf','ne',13,11,'Então contendi com os magistrados, e disse: Por que se desamparou a casa de Deus? Porém eu os ajuntei, e os restaurei no seu posto.'),
('acf','ne',13,12,'Então todo o Judá trouxe os dízimos do grão, do mosto e do azeite aos celeiros.'),
('acf','ne',13,13,'E por tesoureiros pus sobre os celeiros a Selemias, o sacerdote, e a Zadoque, o escrivão e a Pedaías, dentre os levitas; e com eles Hanã, filho de Zacur, o filho de Matanias; porque foram achados fiéis; e se lhes encarregou a eles a distribuição para seus irmãos.'),
('acf','ne',13,14,'Por isto, Deus meu, lembra-te de mim e não risques as beneficências que eu fiz à casa de meu Deus e às suas observâncias.'),
('acf','ne',13,15,'Naqueles dias vi em Judá os que pisavam lagares ao sábado e traziam feixes que carregavam sobre os jumentos; como também vinho, uvas e figos, e toda a espécie de cargas, que traziam a Jerusalém no dia de sábado; e protestei contra eles no dia em que vendiam mantimentos.'),
('acf','ne',13,16,'Também habitavam em Jerusalém tírios que traziam peixe e toda a mercadoria, que vendiam no sábado aos filhos de Judá, e em Jerusalém.'),
('acf','ne',13,17,'E contendi com os nobres de Judá, e lhes disse: Que mal é este que fazeis, profanando o dia de sábado?'),
('acf','ne',13,18,'Porventura não fizeram vossos pais assim, e não trouxe o nosso Deus todo este mal sobre nós e sobre esta cidade? E vós ainda mais acrescentais o ardor de sua ira sobre Israel, profanando o sábado.'),
('acf','ne',13,19,'Sucedeu, pois, que, dando já sombra nas portas de Jerusalém antes do sábado, ordenei que as portas fossem fechadas; e mandei que não as abrissem até passado o sábado; e pus às portas alguns de meus servos, para que nenhuma carga entrasse no dia de sábado.'),
('acf','ne',13,20,'Então os negociantes e os vendedores de toda a mercadoria passaram a noite fora de Jerusalém, uma ou duas vezes.'),
('acf','ne',13,21,'Protestei, pois, contra eles, e lhes disse: Por que passais a noite defronte do muro? Se outra vez o fizerdes, hei de lançar mão de vós. Daquele tempo em diante não vieram no sábado.'),
('acf','ne',13,22,'Também disse aos levitas que se purificassem, e viessem guardar as portas, para santificar o sábado. Nisto também, Deus meu, lembra-te de mim e perdoa-me segundo a abundância da tua benignidade.'),
('acf','ne',13,23,'Vi também naqueles dias judeus que tinham casado com mulheres asdoditas, amonitas e moabitas.'),
('acf','ne',13,24,'E seus filhos falavam meio asdodita, e não podiam falar judaico, senão segundo a língua de cada povo.'),
('acf','ne',13,25,'E contendi com eles, e os amaldiçoei e espanquei alguns deles, e lhes arranquei os cabelos, e os fiz jurar por Deus, dizendo: Não dareis mais vossas filhas a seus filhos, e não tomareis mais suas filhas, nem para vossos filhos nem para vós mesmos.'),
('acf','ne',13,26,'Porventura não pecou nisto Salomão, rei de Israel, não havendo entre muitas nações rei semelhante a ele, e sendo ele amado de seu Deus, e pondo-o Deus rei sobre todo o Israel? E contudo as mulheres estrangeiras o fizeram pecar.'),
('acf','ne',13,27,'E dar-vos-íamos nós ouvidos, para fazermos todo este grande mal, prevaricando contra o nosso Deus, casando com mulheres estrangeiras?'),
('acf','ne',13,28,'Também um dos filhos de Joiada, filho de Eliasibe, o sumo sacerdote, era genro de Sambalate, o horonita, por isso o afugentei de mim.'),
('acf','ne',13,29,'Lembra-te deles, Deus meu, pois contaminaram o sacerdócio, como também a aliança do sacerdócio e dos levitas.'),
('acf','ne',13,30,'Assim os limpei de todo o estrangeiro, e designei os cargos dos sacerdotes e dos levitas, cada um na sua obra.'),
('acf','ne',13,31,'Como também para com as ofertas de lenha em tempos determinados, e para com as primícias; lembra-te de mim, Deus meu, para bem.')
insert into public.bible_verses (version, book_abbrev, chapter, verse, text) values
('acf','et',1,1,'E sucedeu nos dias de Assuero, o Assuero que reinou desde a India até a Etiópia, sobre cento e vinte e sete províncias,'),
('acf','et',1,2,'Que, naqueles dias, assentando-se o rei Assuero no trono do seu reino, que estava na fortaleza de Susã,'),
('acf','et',1,3,'No terceiro ano do seu reinado, fez um banquete a todos os seus príncipes e seus servos, estando assim perante ele o poder da Pérsia e Média e os nobres e príncipes das províncias,'),
('acf','et',1,4,'Para mostrar as riquezas da glória do seu reino, e o esplendor da sua excelente grandeza, por muitos dias, a saber: cento e oitenta dias.'),
('acf','et',1,5,'E, acabados aqueles dias, fez o rei um banquete a todo o povo que se achava na fortaleza de Susã, desde o maior até ao menor, por sete dias, no pátio do jardim do palácio real.'),
('acf','et',1,6,'As tapeçarias eram de pano branco, verde, e azul celeste, pendentes de cordões de linho fino e púrpura, e argolas de prata, e colunas de mármore; os leitos de ouro e de prata, sobre um pavimento de mármore vermelho, e azul, e branco, e preto.'),
('acf','et',1,7,'E dava-se de beber em copos de ouro, e os copos eram diferentes uns dos outros; e havia muito vinho real, segundo a generosidade do rei.'),
('acf','et',1,8,'E o beber era por lei, sem constrangimento; porque assim tinha ordenado o rei expressamente a todos os oficiais da sua casa, que fizessem conforme a vontade de cada um.'),
('acf','et',1,9,'Também a rainha Vasti deu um banquete às mulheres, na casa real do rei Assuero.'),
('acf','et',1,10,'E ao sétimo dia, estando já o coração do rei alegre do vinho, mandou a Meumã, Bizta, Harbona, Bigtá, Abagta, Zetar e Carcas, os sete camareiros que serviam na presença do rei Assuero,'),
('acf','et',1,11,'Que introduzissem na presença do rei a rainha Vasti, com a coroa real, para mostrar aos povos e aos príncipes a sua beleza, porque era formosa à vista.'),
('acf','et',1,12,'Porém a rainha Vasti recusou vir conforme a palavra do rei, por meio dos camareiros; assim o rei muito se enfureceu, e acendeu nele a sua ira.'),
('acf','et',1,13,'Então perguntou o rei aos sábios que entendiam dos tempos (porque assim se tratavam os negócios do rei na presença de todos os que sabiam a lei e o direito;'),
('acf','et',1,14,'E os mais chegados a ele eram: Carsena, Setar, Admata, Társis, Meres, Marsena, e Memucã, os sete príncipes dos persas e dos medos, que viam a face do rei, e se assentavam como principais no reino),'),
('acf','et',1,15,'O que, segundo a lei, se devia fazer à rainha Vasti, por não ter obedecido ao mandado do rei Assuero, por meio dos camareiros.'),
('acf','et',1,16,'Então disse Memucã na presença do rei e dos príncipes: Não somente contra o rei pecou a rainha Vasti, porém também contra todos os príncipes, e contra todos os povos que há em todas as províncias do rei Assuero.'),
('acf','et',1,17,'Porque a notícia do que fez a rainha chegará a todas as mulheres, de modo que aos seus olhos desprezarão a seus maridos quando ouvirem dizer: Mandou o rei Assuero que introduzissem à sua presença a rainha Vasti, porém ela não veio.'),
('acf','et',1,18,'E neste mesmo dia as senhoras da Pérsia e da Média, ouvindo o que fez a rainha, dirão o mesmo a todos os príncipes do rei; e assim haverá muito desprezo e indignação.'),
('acf','et',1,19,'Se bem parecer ao rei, saia da sua parte um edito real, e escreva-se nas leis dos persas e dos medos, e não se revogue, a saber: que Vasti não entre mais na presença do rei Assuero, e o rei dê o reino dela a outra que seja melhor do que ela.'),
('acf','et',1,20,'E, ouvindo-se o mandado, que o rei decretará em todo o seu reino (porque é grande), todas as mulheres darão honra a seus maridos, desde a maior até à menor.'),
('acf','et',1,21,'E pareceram bem estas palavras aos olhos do rei e dos príncipes; e fez o rei conforme a palavra de Memucã.'),
('acf','et',1,22,'Então enviou cartas a todas as províncias do rei, a cada província segundo a sua escrita, e a cada povo segundo a sua língua; que cada homem fosse senhor em sua casa, e que se falasse conforme a língua do seu povo.'),
('acf','et',2,1,'Passadas estas coisas, e apaziguado já o furor do rei Assuero, lembrou-se de Vasti, e do que fizera, e do que se tinha decretado a seu respeito.'),
('acf','et',2,2,'Então disseram os servos do rei, que lhe serviam: Busquem-se para o rei moças virgens e formosas.'),
('acf','et',2,3,'E ponha o rei oficiais em todas as províncias do seu reino, que ajuntem a todas as moças virgens e formosas, na fortaleza de Susã, na casa das mulheres, aos cuidados de Hegai, camareiro do rei, guarda das mulheres, e dêem-se-lhes os seus enfeites.'),
('acf','et',2,4,'E a moça que parecer bem aos olhos do rei, reine em lugar de Vasti. E isto pareceu bem aos olhos do rei, e ele assim fez.'),
('acf','et',2,5,'Havia então um homem judeu na fortaleza de Susã, cujo nome era Mardoqueu, filho de Jair, filho de Simei, filho de Quis, homem benjamita,'),
('acf','et',2,6,'Que fora transportado de Jerusalém, com os cativos que foram levados com Jeconias, rei de Judá, o qual transportara Nabucodonosor, rei de babilônia.'),
('acf','et',2,7,'Este criara a Hadassa (que é Ester, filha de seu tio), porque não tinha pai nem mãe; e era jovem bela de presença e formosa; e, morrendo seu pai e sua mãe, Mardoqueu a tomara por sua filha.'),
('acf','et',2,8,'Sucedeu que, divulgando-se o mandado do rei e a sua lei, e ajuntando-se muitas moças na fortaleza de Susã, aos cuidados de Hegai, também levaram Ester à casa do rei, sob a custódia de Hegai, guarda das mulheres.'),
('acf','et',2,9,'E a moça pareceu formosa aos seus olhos, e alcançou graça perante ele; por isso se apressou a dar-lhe os seus enfeites, e os seus quinhões, como também em lhe dar sete moças de respeito da casa do rei; e a fez passar com as suas moças ao melhor lugar da casa das mulheres.'),
('acf','et',2,10,'Ester, porém, não declarou o seu povo e a sua parentela, porque Mardoqueu lhe tinha ordenado que o não declarasse.'),
('acf','et',2,11,'E passeava Mardoqueu cada dia diante do pátio da casa das mulheres, para se informar de como Ester passava, e do que lhe sucederia.'),
('acf','et',2,12,'E, chegando a vez de cada moça, para vir ao rei Assuero, depois que fora feito a ela segundo a lei das mulheres, por doze meses (porque assim se cumpriam os dias das suas purificações, seis meses com óleo de mirra, e seis meses com especiarias, e com as coisas para a purificação das mulheres),'),
('acf','et',2,13,'Desta maneira, pois, vinha a moça ao rei; dava-se-lhe tudo quanto ela desejava, para levar consigo da casa das mulheres à casa do rei;'),
('acf','et',2,14,'À tarde entrava, e pela manhã tornava à segunda casa das mulheres, sob os cuidados de Saasgaz, camareiro do rei, guarda das concubinas; não tornava mais ao rei, salvo se o rei a desejasse, e fosse chamada pelo nome.'),
('acf','et',2,15,'Chegando, pois, a vez de Ester, filha de Abiail, tio de Mardoqueu (que a tomara por sua filha), para ir ao rei, coisa nenhuma pediu, senão o que disse Hegai, camareiro do rei, guarda das mulheres; e alcançava Ester graça aos olhos de todos quantos a viam.'),
('acf','et',2,16,'Assim foi levada Ester ao rei Assuero, à sua casa real, no décimo mês, que é o mês de tebete, no sétimo ano do seu reinado.'),
('acf','et',2,17,'E o rei amou a Ester mais do que a todas as mulheres, e alcançou perante ele graça e benevolência mais do que todas as virgens; e pôs a coroa real na sua cabeça, e a fez rainha em lugar de Vasti.'),
('acf','et',2,18,'Então o rei deu um grande banquete a todos os seus príncipes e aos seus servos; era o banquete de Ester; e deu alívio às províncias, e fez presentes segundo a generosidade do rei.'),
('acf','et',2,19,'E reunindo-se segunda vez as virgens, Mardoqueu estava assentado à porta do rei.'),
('acf','et',2,20,'Ester, porém, não declarava a sua parentela e o seu povo, como Mardoqueu lhe ordenara; porque Ester cumpria o mandado de Mardoqueu, como quando a criara.'),
('acf','et',2,21,'Naqueles dias, assentando-se Mardoqueu à porta do rei, dois camareiros do rei, dos guardas da porta, Bigtã e Teres, grandemente se indignaram, e procuraram atentar contra o rei Assuero.'),
('acf','et',2,22,'E veio isto ao conhecimento de Mardoqueu, e ele o fez saber à rainha Ester; e Ester o disse ao rei, em nome de Mardoqueu.'),
('acf','et',2,23,'E inquiriu-se o negócio, e se descobriu, e ambos foram pendurados numa forca; e foi escrito nas crônicas perante o rei.'),
('acf','et',3,1,'Depois destas coisas o rei Assuero engrandeceu a Hamã, filho de Hamedata, agagita, e o exaltou, e pôs o seu assento acima de todos os príncipes que estavam com ele.'),
('acf','et',3,2,'E todos os servos do rei, que estavam à porta do rei, se inclinavam e se prostravam perante Hamã; porque assim tinha ordenado o rei acerca dele; porém Mardoqueu não se inclinava nem se prostrava.'),
('acf','et',3,3,'Então os servos do rei, que estavam à porta do rei, disseram a Mardoqueu: Por que transgrides o mandado do rei?'),
('acf','et',3,4,'Sucedeu, pois, que, dizendo-lhe eles isto, dia após dia, e não lhes dando ele ouvidos, o fizeram saber a Hamã, para verem se as palavras de Mardoqueu se sustentariam, porque ele lhes tinha declarado que era judeu.'),
('acf','et',3,5,'Vendo, pois, Hamã que Mardoqueu não se inclinava nem se prostrava diante dele, Hamã se encheu de furor.'),
('acf','et',3,6,'Porém teve como pouco, nos seus propósitos, o pôr as mãos só em Mardoqueu (porque lhe haviam declarado de que povo era Mardoqueu); Hamã, pois, procurou destruir a todos os judeus, o povo de Mardoqueu, que havia em todo o reino de Assuero.'),
('acf','et',3,7,'No primeiro mês (que é o mês de Nisã), no ano duodécimo do rei Assuero, se lançou Pur, isto é, a sorte, perante Hamã, para cada dia, e para cada mês, até ao duodécimo mês, que é o mês de Adar.'),
('acf','et',3,8,'E Hamã disse ao rei Assuero: Existe espalhado e dividido entre os povos em todas as províncias do teu reino um povo, cujas leis são diferentes das leis de todos os povos, e que não cumpre as leis do rei; por isso não convém ao rei deixá-lo ficar.'),
('acf','et',3,9,'Se bem parecer ao rei, decrete-se que os matem; e eu porei nas mãos dos que fizerem a obra dez mil talentos de prata, para que entrem nos tesouros do rei.'),
('acf','et',3,10,'Então tirou o rei o anel da sua mão, e o deu a Hamã, filho de Hamedata, agagita, adversário dos judeus.'),
('acf','et',3,11,'E disse o rei a Hamã: Essa prata te é dada como também esse povo, para fazeres dele o que bem parecer aos teus olhos.'),
('acf','et',3,12,'Então chamaram os escrivães do rei no primeiro mês, no dia treze do mesmo e, conforme a tudo quanto Hamã mandou, se escreveu aos príncipes do rei, e aos governadores que havia sobre cada província, e aos líderes, de cada povo; a cada província segundo a sua escrita, e a cada povo segundo a sua língua; em nome do rei Assuero se escreveu, e com o anel do rei se selou.'),
('acf','et',3,13,'E enviaram-se as cartas por intermédio dos correios a todas as províncias do rei, para que destruíssem, matassem, e fizessem perecer a todos os judeus, desde o jovem até ao velho, crianças e mulheres, em um mesmo dia, a treze do duodécimo mês (que é o mês de Adar), e que saqueassem os seus bens.'),
('acf','et',3,14,'Uma cópia do despacho que determinou a divulgação da lei em cada província, foi enviada a todos os povos, para que estivessem preparados para aquele dia.'),
('acf','et',3,15,'Os correios, pois, impelidos pela palavra do rei, saíram, e a lei se proclamou na fortaleza de Susã. E o rei e Hamã se assentaram a beber, porém a cidade de Susã estava confusa.'),
('acf','et',4,1,'Quando Mardoqueu soube tudo quanto se havia passado, rasgou as suas vestes, e vestiu-se de saco e de cinza, e saiu pelo meio da cidade, e clamou com grande e amargo clamor;'),
('acf','et',4,2,'E chegou até diante da porta do rei, porque ninguém vestido de saco podia entrar pelas portas do rei.'),
('acf','et',4,3,'E em todas as províncias aonde a palavra do rei e a sua lei chegava, havia entre os judeus grande luto, com jejum, e choro, e lamentação; e muitos estavam deitados em saco e em cinza.'),
('acf','et',4,4,'Então vieram as servas de Ester, e os seus camareiros, e fizeram-na saber, do que a rainha muito se doeu; e mandou roupas para vestir a Mardoqueu, e tirar-lhe o pano de saco; porém ele não as aceitou.'),
('acf','et',4,5,'Então Ester chamou a Hatá (um dos camareiros do rei, que este tinha posto para servi-la), e deu-lhe ordem para ir a Mardoqueu, para saber que era aquilo, e porquê.'),
('acf','et',4,6,'E, saindo Hatá a Mardoqueu, à praça da cidade, que estava diante da porta do rei,'),
('acf','et',4,7,'Mardoqueu lhe fez saber tudo quanto lhe tinha sucedido; como também a soma exata do dinheiro, que Hamã dissera que daria para os tesouros do rei, pelos judeus, para destruí-los.'),
('acf','et',4,8,'Também lhe deu a cópia da lei escrita, que se publicara em Susã, para os destruir, para que a mostrasse a Ester, e a fizesse saber; e para lhe ordenar que fosse ter com o rei, e lhe pedisse e suplicasse na sua presença pelo seu povo.'),
('acf','et',4,9,'Veio, pois, Hatá, e fez saber a Ester as palavras de Mardoqueu.'),
('acf','et',4,10,'Então falou Ester a Hatá, mandando-o dizer a Mardoqueu:'),
('acf','et',4,11,'Todos os servos do rei, e o povo das províncias do rei, bem sabem que todo o homem ou mulher que chegar ao rei no pátio interior, sem ser chamado, não há senão uma sentença, a de morte, salvo se o rei estender para ele o cetro de ouro, para que viva; e eu nestes trinta dias não tenho sido chamada para ir ao rei.'),
('acf','et',4,12,'E fizeram saber a Mardoqueu as palavras de Ester.'),
('acf','et',4,13,'Então Mardoqueu mandou que respondessem a Ester: Não imagines no teu íntimo que, por estares na casa do rei, escaparás só tu entre todos os judeus.'),
('acf','et',4,14,'Porque, se de todo te calares neste tempo, socorro e livramento de outra parte sairá para os judeus, mas tu e a casa de teu pai perecereis; e quem sabe se para tal tempo como este chegaste a este reino?'),
('acf','et',4,15,'Então disse Ester que tornassem a dizer a Mardoqueu:'),
('acf','et',4,16,'Vai, ajunta a todos os judeus que se acharem em Susã, e jejuai por mim, e não comais nem bebais por três dias, nem de dia nem de noite, e eu e as minhas servas também assim jejuaremos. E assim irei ter com o rei, ainda que não seja segundo a lei; e se perecer, pereci.'),
('acf','et',4,17,'Então Mardoqueu foi, e fez conforme a tudo quanto Ester lhe ordenou.'),
('acf','et',5,1,'Sucedeu, pois, que ao terceiro dia Ester se vestiu com trajes reais, e se pôs no pátio interior da casa do rei, defronte do aposento do rei; e o rei estava assentado sobre o seu trono real, na casa real, defronte da porta do aposento.'),
('acf','et',5,2,'E sucedeu que, vendo o rei a rainha Ester, que estava no pátio, ela alcançou graça aos seus olhos; e o rei estendeu para Ester o cetro de ouro, que tinha na sua mão, e Ester chegou, e tocou a ponta do cetro.'),
('acf','et',5,3,'Então o rei lhe disse: Que é que queres, rainha Ester, ou qual é a tua petição? Até metade do reino se te dará.'),
('acf','et',5,4,'E disse Ester: Se parecer bem ao rei, venha hoje com Hamã ao banquete que lhe tenho preparado.'),
('acf','et',5,5,'Então disse o rei: Fazei apressar a Hamã, para que se atenda ao desejo de Ester. Vindo, pois, o rei e Hamã ao banquete, que Ester tinha preparado,'),
('acf','et',5,6,'Disse o rei a Ester, no banquete do vinho: Qual é a tua petição? E ser-te-á concedida, e qual é o teu desejo? E se fará, ainda até metade do reino.'),
('acf','et',5,7,'Então respondeu Ester, e disse: Minha petição e desejo é:'),
('acf','et',5,8,'Se achei graça aos olhos do rei, e se bem parecer ao rei conceder-me a minha petição, e cumprir o meu desejo, venha o rei com Hamã ao banquete que lhes hei de preparar, e amanhã farei conforme a palavra do rei.'),
('acf','et',5,9,'Então saiu Hamã naquele dia alegre e de bom ânimo; porém, vendo Mardoqueu à porta do rei, e que ele não se levantara nem se movera diante dele, então Hamã se encheu de furor contra Mardoqueu.'),
('acf','et',5,10,'Hamã, porém, se refreou, e foi para sua casa; e enviou, e mandou vir os seus amigos, e Zeres, sua mulher.'),
('acf','et',5,11,'E contou-lhes Hamã a glória das suas riquezas, a multidão de seus filhos, e tudo em que o rei o tinha engrandecido, e como o tinha exaltado sobre os príncipes e servos do rei.'),
('acf','et',5,12,'Disse mais Hamã: Tampouco a rainha Ester a ninguém fez vir com o rei ao banquete que tinha preparado, senão a mim; e também para amanhã estou convidado por ela juntamente com o rei.'),
('acf','et',5,13,'Porém tudo isto não me satisfaz, enquanto eu vir o judeu Mardoqueu assentado à porta do rei.'),
('acf','et',5,14,'Então lhe disseram Zeres, sua mulher, e todos os seus amigos: Faça-se uma forca de cinqüenta côvados de altura, e amanhã dize ao rei que nela seja enforcado Mardoqueu; e então entra alegre com o rei ao banquete. E este conselho bem pareceu a Hamã, que mandou fazer a forca.'),
('acf','et',6,1,'Naquela mesma noite fugiu o sono do rei; então mandou trazer o livro de registro das crônicas, as quais se leram diante do rei.'),
('acf','et',6,2,'E achou-se escrito que Mardoqueu tinha denunciado Bigtã e Teres, dois dos camareiros do rei, da guarda da porta, que tinham procurado lançar mão do rei Assuero.'),
('acf','et',6,3,'Então disse o rei: Que honra e distinção se deu por isso a Mardoqueu? E os servos do rei, que ministravam junto a ele, disseram: Coisa nenhuma se lhe fez.'),
('acf','et',6,4,'Então disse o rei: Quem está no pátio? E Hamã tinha entrado no pátio exterior da casa do rei, para dizer ao rei que enforcassem a Mardoqueu na forca que lhe tinha preparado.'),
('acf','et',6,5,'E os servos do rei lhe disseram: Eis que Hamã está no pátio. E disse o rei que entrasse.'),
('acf','et',6,6,'E, entrando Hamã, o rei lhe disse: Que se fará ao homem de cuja honra o rei se agrada? Então Hamã disse no seu coração: De quem se agradaria o rei para lhe fazer honra mais do que a mim?'),
('acf','et',6,7,'Assim disse Hamã ao rei: Para o homem, de cuja honra o rei se agrada,'),
('acf','et',6,8,'Tragam a veste real que o rei costuma vestir, como também o cavalo em que o rei costuma andar montado, e ponha-se-lhe a coroa real na sua cabeça.'),
('acf','et',6,9,'E entregue-se a veste e o cavalo à mão de um dos príncipes mais nobres do rei, e vistam delas aquele homem a quem o rei deseja honrar; e levem-no a cavalo pelas ruas da cidade, e apregoe-se diante dele: Assim se fará ao homem a quem o rei deseja honrar!'),
('acf','et',6,10,'Então disse o rei a Hamã: Apressa-te, toma a veste e o cavalo, como disseste, e faze assim para com o judeu Mardoqueu, que está assentado à porta do rei; e coisa nenhuma omitas de tudo quanto disseste.'),
('acf','et',6,11,'E Hamã tomou a veste e o cavalo, e vestiu a Mardoqueu, e o levou a cavalo pelas ruas da cidade, e apregoou diante dele: Assim se fará ao homem a quem o rei deseja honrar!'),
('acf','et',6,12,'Depois disto Mardoqueu voltou para a porta do rei; porém Hamã se retirou correndo à sua casa, triste, e de cabeça coberta.'),
('acf','et',6,13,'E contou Hamã a Zeres, sua mulher, e a todos os seus amigos, tudo quanto lhe tinha sucedido. Então os seus sábios e Zeres, sua mulher, lhe disseram: Se Mardoqueu, diante de quem já começaste a cair, é da descendência dos judeus, não prevalecerás contra ele, antes certamente cairás diante dele.'),
('acf','et',6,14,'E estando eles ainda falando com ele, chegaram os camareiros do rei, e se apressaram a levar Hamã ao banquete que Ester preparara.'),
('acf','et',7,1,'Vindo, pois, o rei com Hamã, para beber com a rainha Ester,'),
('acf','et',7,2,'Disse outra vez o rei a Ester, no segundo dia, no banquete do vinho: Qual é a tua petição, rainha Ester? E se te dará. E qual é o teu desejo? Até metade do reino, se te dará.'),
('acf','et',7,3,'Então respondeu a rainha Ester, e disse: Se, ó rei, achei graça aos teus olhos, e se bem parecer ao rei, dê-se-me a minha vida como minha petição, e o meu povo como meu desejo.'),
('acf','et',7,4,'Porque fomos vendidos, eu e o meu povo, para nos destruírem, matarem, e aniquilarem de vez; se ainda por servos e por servas nos vendessem, calar-me-ia; ainda que o opressor não poderia ter compensado a perda do rei.'),
('acf','et',7,5,'Então falou o rei Assuero, e disse à rainha Ester: Quem é esse e onde está esse, cujo coração o instigou a assim fazer?'),
('acf','et',7,6,'E disse Ester: O homem, o opressor, e o inimigo, é este mau Hamã. Então Hamã se perturbou perante o rei e a rainha.'),
('acf','et',7,7,'E o rei no seu furor se levantou do banquete do vinho e passou para o jardim do palácio; e Hamã se pôs em pé, para rogar à rainha Ester pela sua vida; porque viu que já o mal lhe estava determinado pelo rei.'),
('acf','et',7,8,'Tornando, pois, o rei do jardim do palácio à casa do banquete do vinho, Hamã tinha caído prostrado sobre o leito em que estava Ester. Então disse o rei: Porventura quereria ele também forçar a rainha perante mim nesta casa? Saindo esta palavra da boca do rei, cobriram o rosto de Hamã.'),
('acf','et',7,9,'Então disse Harbona, um dos camareiros que serviam diante do rei: Eis que também a forca de cinqüenta côvados de altura que Hamã fizera para Mardoqueu, que falara em defesa do rei, está junto à casa de Hamã. Então disse o rei: Enforcai-o nela.'),
('acf','et',7,10,'Enforcaram, pois, a Hamã na forca, que ele tinha preparado para Mardoqueu. Então o furor do rei se aplacou.'),
('acf','et',8,1,'Naquele mesmo dia deu o rei Assuero à rainha Ester a casa de Hamã, inimigo dos judeus; e Mardoqueu veio perante o rei, porque Ester tinha declarado quem ele era.'),
('acf','et',8,2,'E tirou o rei o seu anel, que tinha tomado de Hamã, e o deu a Mardoqueu. E Ester encarregou Mardoqueu da casa de Hamã.'),
('acf','et',8,3,'Falou mais Ester perante o rei, e se lhe lançou aos seus pés; e chorou, e lhe suplicou que revogasse a maldade de Hamã, o agagita, e o intento que tinha projetado contra os judeus.'),
('acf','et',8,4,'E estendeu o rei para Ester o cetro de ouro. Então Ester se levantou, e pôs-se em pé perante o rei,'),
('acf','et',8,5,'E disse: Se bem parecer ao rei, e se eu achei graça perante ele, e se este negócio é reto diante do rei, e se eu lhe agrado aos seus olhos, escreva-se que se revoguem as cartas concebidas por Hamã filho de Hamedata, o agagita, as quais ele escreveu para aniquilar os judeus, que estão em todas as províncias do rei.'),
('acf','et',8,6,'Pois como poderei ver o mal que sobrevirá ao meu povo? E como poderei ver a destruição da minha parentela?'),
('acf','et',8,7,'Então disse o rei Assuero à rainha Ester e ao judeu Mardoqueu: Eis que dei a Ester a casa de Hamã, e a ele penduraram numa forca, porquanto estendera as mãos contra os judeus.'),
('acf','et',8,8,'Escrevei, pois, aos judeus, como parecer bem aos vossos olhos, em nome do rei, e selai-o com o anel do rei; porque o documento que se escreve em nome do rei, e que se sela com o anel do rei, não se pode revogar.'),
('acf','et',8,9,'Então foram chamados os escrivães do rei, naquele mesmo tempo, no terceiro mês (que é o mês de Sivã), aos vinte e três dias; e se escreveu conforme a tudo quanto ordenou Mardoqueu aos judeus, como também aos sátrapas, e aos governadores, e aos líderes das províncias, que se estendem da Úndia até Etiópia, cento e vinte e sete províncias, a cada província segundo o seu modo de escrever, e a cada povo conforme a sua língua; como também aos judeus segundo o seu modo de escrever, e conforme a sua língua.'),
('acf','et',8,10,'E escreveu-se em nome do rei Assuero e, selando-as com o anel do rei, enviaram as cartas pela mão de correios a cavalo, que cavalgavam sobre ginetes, que eram das cavalariças do rei.'),
('acf','et',8,11,'Nelas o rei concedia aos judeus, que havia em cada cidade, que se reunissem, e se dispusessem para defenderem as suas vidas, e para destruírem, matarem e aniquilarem todas as forças do povo e da província que viessem contra eles, crianças e mulheres, e que se saqueassem os seus bens,'),
('acf','et',8,12,'Num mesmo dia, em todas as províncias do rei Assuero, no dia treze do duodécimo mês, que é o mês de Adar;'),
('acf','et',8,13,'E uma cópia da carta seria divulgada como decreto em todas as províncias, e publicada entre todos os povos, para que os judeus estivessem preparados para aquele dia, para se vingarem dos seus inimigos.'),
('acf','et',8,14,'Os correios, sobre ginetes velozes, saíram apressuradamente, impelidos pela palavra do rei; e esta ordem foi publicada na fortaleza de Susã.'),
('acf','et',8,15,'Então Mardoqueu saiu da presença do rei com veste real azul-celeste e branca, como também com uma grande coroa de ouro, e com uma capa de linho fino e púrpura, e a cidade de Susã exultou e se alegrou.'),
('acf','et',8,16,'E para os judeus houve luz, e alegria, e gozo, e honra.'),
('acf','et',8,17,'Também em toda a província, e em toda a cidade, aonde chegava a palavra do rei e a sua ordem, havia entre os judeus alegria e gozo, banquetes e dias de folguedo; e muitos, dos povos da terra, se fizeram judeus, porque o temor dos judeus tinha caído sobre eles.'),
('acf','et',9,1,'E, no duodécimo mês, que é o mês de Adar, no dia treze do mesmo mês em que chegou a palavra do rei e a sua ordem para se executar, no dia em que os inimigos dos judeus esperavam assenhorear-se deles, sucedeu o contrário, porque os judeus foram os que se assenhorearam dos que os odiavam.'),
('acf','et',9,2,'Porque os judeus nas suas cidades, em todas as províncias do rei Assuero, se ajuntaram para pôr as mãos naqueles que procuravam o seu mal; e ninguém podia resistir-lhes, porque o medo deles caíra sobre todos aqueles povos.'),
('acf','et',9,3,'E todos os líderes das províncias, e os sátrapas, e os governadores, e os que faziam a obra do rei, auxiliavam os judeus; porque tinha caído sobre eles o temor de Mardoqueu.'),
('acf','et',9,4,'Porque Mardoqueu era grande na casa do rei, e a sua fama crescia por todas as províncias, porque o homem Mardoqueu ia sendo engrandecido.'),
('acf','et',9,5,'Feriram, pois, os judeus a todos os seus inimigos, a golpes de espada, com matança e com destruição; e fizeram dos seus inimigos o que quiseram.'),
('acf','et',9,6,'E na fortaleza de Susã os judeus mataram e destruíram quinhentos homens;'),
('acf','et',9,7,'Como também a Parsandata, e a Dalfom e a Aspata,'),
('acf','et',9,8,'E a Porata, e a Adalia, e a Aridata,'),
('acf','et',9,9,'E a Farmasta, e a Arisai, e a Aridai, e a Vaisata; ú'),
('acf','et',9,10,'Os dez filhos de Hamã, filho de Hamedata, o inimigo dos judeus, mataram, porém ao despojo não estenderam a sua mão.'),
('acf','et',9,11,'No mesmo dia foi comunicado ao rei o número dos mortos na fortaleza de Susã.'),
('acf','et',9,12,'E disse o rei à rainha Ester: Na fortaleza de Susã os judeus mataram e destruíram quinhentos homens, e os dez filhos de Hamã; nas mais províncias do rei que teriam feito? Qual é, pois, a tua petição? E dar-se-te-á. Ou qual é ainda o teu requerimento? E far-se-á.'),
('acf','et',9,13,'Então disse Ester: Se bem parecer ao rei, conceda-se aos judeus que se acham em Susã que também façam amanhã conforme ao mandado de hoje; e pendurem numa forca os dez filhos de Hamã.'),
('acf','et',9,14,'Então disse o rei que assim se fizesse; e publicou-se um edito em Susã, e enforcaram os dez filhos de Hamã.'),
('acf','et',9,15,'E reuniram-se os judeus que se achavam em Susã também no dia catorze do mês de Adar, e mataram em Susã trezentos homens; porém ao despojo não estenderam a sua mão.'),
('acf','et',9,16,'Também os demais judeus que se achavam nas províncias do rei se reuniram e se dispuseram em defesa das suas vidas, e tiveram descanso dos seus inimigos; e mataram dos seus inimigos setenta e cinco mil; porém ao despojo não estenderam a sua mão.'),
('acf','et',9,17,'Sucedeu isto no dia treze do mês de Adar; e descansaram no dia catorze, e fizeram, daquele dia, dia de banquetes e de alegria.'),
('acf','et',9,18,'Também os judeus, que se achavam em Susã se ajuntaram nos dias treze e catorze do mesmo; e descansaram no dia quinze, e fizeram, daquele dia, dia de banquetes e de alegria.'),
('acf','et',9,19,'Os judeus, porém, das aldeias, que habitavam nas vilas, fizeram do dia catorze do mês de Adar dia de alegria e de banquetes, e dia de folguedo, e de mandarem presentes uns aos outros.'),
('acf','et',9,20,'E Mardoqueu escreveu estas coisas, e enviou cartas a todos os judeus que se achavam em todas as províncias do rei Assuero, aos de perto, e aos de longe,'),
('acf','et',9,21,'Ordenando-lhes que guardassem o dia catorze do mês de Adar, e o dia quinze do mesmo, todos os anos,'),
('acf','et',9,22,'Como os dias em que os judeus tiveram repouso dos seus inimigos, e o mês que se lhes mudou de tristeza em alegria, e de luto em dia de festa, para que os fizessem dias de banquetes e de alegria, e de mandarem presentes uns aos outros, e dádivas aos pobres.'),
('acf','et',9,23,'E os judeus encarregaram-se de fazer o que já tinham começado, como também o que Mardoqueu lhes tinha escrito.'),
('acf','et',9,24,'Porque Hamã, filho de Hamedata, o agagita, inimigo de todos os judeus, tinha intentado destruir os judeus, e tinha lançado Pur, isto é, a sorte, para os assolar e destruir.'),
('acf','et',9,25,'Mas, vindo isto perante o rei, mandou ele por cartas que o mau intento que Hamã formara contra os judeus, se tornasse sobre a sua cabeça; pelo que penduraram a ele e a seus filhos numa forca.'),
('acf','et',9,26,'Por isso àqueles dias chamam Purim, do nome Pur; assim também por causa de todas as palavras daquela carta, e do que viram sobre isso, e do que lhes tinha sucedido,'),
('acf','et',9,27,'Confirmaram os judeus, e tomaram sobre si, e sobre a sua descendência, e sobre todos os que se achegassem a eles, que não se deixaria de guardar estes dois dias conforme ao que se escrevera deles, e segundo o seu tempo determinado, todos os anos.'),
('acf','et',9,28,'E que estes dias seriam lembrados e guardados em cada geração, família, província e cidade, e que esses dias de Purim não fossem revogados entre os judeus, e que a memória deles nunca teria fim entre os de sua descendência.'),
('acf','et',9,29,'Então a rainha Ester, filha de Abiail, e Mardoqueu, o judeu, escreveram com toda autoridade uma segunda vez, para confirmar a carta a respeito de Purim.'),
('acf','et',9,30,'E mandaram cartas a todos os judeus, às cento e vinte e sete províncias do reino de Assuero, com palavras de paz e verdade.'),
('acf','et',9,31,'Para confirmarem estes dias de Purim nos seus tempos determinados, como Mardoqueu, o judeu, e a rainha Ester lhes tinham estabelecido, e como eles mesmos já o tinham estabelecido sobre si e sobre a sua descendência, acerca do jejum e do seu clamor.'),
('acf','et',9,32,'E o mandado de Ester estabeleceu os sucessos daquele Purim; e escreveu-se no livro.'),
('acf','et',10,1,'Depois disto impôs o rei Assuero tributo sobre a terra, e sobre as ilhas do mar.'),
('acf','et',10,2,'E todos os atos do seu poder e do seu valor, e o relato da grandeza de Mardoqueu, a quem o rei exaltou, porventura não estão escritos no livro das crônicas dos reis da Média e da Pérsia?'),
('acf','et',10,3,'Porque o judeu Mardoqueu foi o segundo depois do rei Assuero, e grande entre os judeus, e estimado pela multidão de seus irmãos, procurando o bem do seu povo, e proclamando a prosperidade de toda a sua descendência.')
